TURATH_CHUNK(9,[{"num":1800,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كُنَّا نُصَلِّي الْعَصْرَ، ثُمَّ يَخْرُجُ الإِنْسَانُ إِلَى بَنِي عَمْرِو بْنِ عَوْفٍ، فَيَجِدُهُمْ يُصَلُّونَ الْعَصْرَ."],"takhrij":"متفق عليه: رواه مالك في وقوت الصلاة (10) عن إسحاق بن عبدالله بن أبي طلحة، عن أنس بن مالك، فذكره. ومن طريق مالك رواه البخاري في المواقيت (548)، ومسلم في المساجد (621: 194).","grade":"متفق عليه","chapter_ar":"باب استحباب التبكير بالعصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (Report 10), al-Bukhari (548), and Muslim (621:194).","chapter_en":"The recommendation to pray the ‘Asr (afternoon) prayer early.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Malik said: We used to pray ‘Asr, then a person would go to Banu ‘Amr ibn ‘Awf and find them still praying ‘Asr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (10) والبخاري (548)، ومسلم (621:194)."},{"num":1801,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الْعَصْرَ وَالشَّمْسُ مُرْتَفِعَةٌ حَيَّةٌ، فَيَذْهَبُ الذَّاهِبُ إِلَى الْعَوَالِي، فَيَأْتِيهِمْ وَالشَّمْسُ مُرْتَفِعَةٌ...(فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: البخاري في المواقيت (550) من طريق شعيب، ومسلم في المساجد (621: 192) من طريق الليث وعمرو، ثلاثتهم عن ابن شهاب الزهريّ، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب التبكير بالعصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (550) and Muslim (621:192).","chapter_en":"The recommendation to pray the ‘Asr (afternoon) prayer early.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ used to pray ‘Asr while the sun was still high and bright. A person could go to al-‘Awali and reach them while the sun was still high."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (550)، ومسلم (621:192)."},{"num":1802,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ يَقُولُ: صَلَّيْنَا مَعَ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ الظُّهْرَ، ثُمَّ خَرَجْنَا حَتَّى دَخَلْنَا عَلَى أَنَسِ بْنِ مَالِكٍ فَوَجَدْنَاهُ يُصَلِّي الْعَصْرَ، فَقُلْتُ: يَا عَمِّ مَا هَذِهِ الصَّلَاةُ الَّتِي صَلَّيْتَ ؟ قَالَ: الْعَصْرُ، وَهَذِهِ صَلَاةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّتِي كُنَّا نُصَلِّي مَعَهُ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (549)، ومسلم في المساجد (623) كلاهما من طريق عبدالله بن المبارك، عن أبي بكر بن عثمان بن سهل بن حُنَيف، قال سمعت أبا أمامة يقول: فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب استحباب التبكير بالعصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (549) and Muslim (623).","chapter_en":"The recommendation to pray the ‘Asr (afternoon) prayer early.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Anas narrated that Abu Umamah ibn Sahl said: We prayed Zuhr with ‘Umar ibn ‘Abd al-‘Aziz, then we went and entered upon Anas ibn Malik and found him praying ‘Asr. I said: “Uncle, what is this prayer you just prayed?” He said: “It is ‘Asr—this is the prayer of the Messenger of Allah ﷺ that we used to pray with him.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (549)، ومسلم (623)."},{"num":1803,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ قَالَ: كُنَّا نُصَلِّي الْعَصْرَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ تُنْحَرُ الْجَزُورُ، فَتُقْسَمُ عَشَرَ قِسَمٍ، ثُمَّ تُطْبَخُ فَنَأْكُلُ لَحْمًا نَضِيجًا قَبْلَ مَغِيبِ الشَّمْسِ."],"takhrij":"متفق عليه: رواه البخاري في الشركة (2485)، ومسلم في المساجد (625)، واللفظ له، كلاهما من طريق الأوزاعي، قال: ثنا أبو النجاشي، قال: سمعتُ رافع بن خديج فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب التبكير بالعصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2485) and Muslim (625), with Muslim’s wording. Another wording states: “We used to slaughter the camel in the time of the Messenger of Allah ﷺ after ‘Asr,” without stating “with him.”","chapter_en":"The recommendation to pray the ‘Asr (afternoon) prayer early.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Rafi‘ ibn Khadij said: We used to pray ‘Asr with the Messenger of Allah ﷺ. Then a camel would be slaughtered, divided into ten portions, cooked, and we would eat cooked meat before sunset."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2485)، ومسلم (625)، واللفظ له. وفي رواية: كنا ننحر الجزور على عهد رسول الله ﷺ بعد العصر. ولم يقل: (( كنا نصلي معه ))."},{"num":1804,"demo":false,"sanad":"","matn":["عَنِ الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ قَالَ: دَخَلْنَا عَلَى أَنَسِ بْنِ مَالِكٍ بَعْدَ الظُّهْرِ فَقَامَ يُصَلِّي الْعَصْرَ، فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ ذَكَرْنَا تَعْجِيلَ الصَّلَاةِ أَوْ ذَكَرَهَا فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: تِلْكَ صَلَاةُ الْمُنَافِقِينَ، تِلْكَ صَلَاةُ الْمُنَافِقِينَ، تِلْكَ صَلَاةُ الْمُنَافِقِينَ، يَجْلِسُ أَحَدُهُمْ حَتَّى إِذَا اصْفَرَّتِ الشَّمْسُ وَكَانَتْ بَيْنَ قَرْنَيِ الشَّيْطَانِ أَوْ عَلَى قَرْنِ الشَّيْطَانِ، قَامَ فَنَقَرَ أَرْبَعًا لَا يَذْكُرُ اللَّهَ فِيهَا إِلَّا قَلِيلًا."],"takhrij":"صحيح: رواه مالك في القرآن (46) عن العلاء بن عبدالرحمن قال: دخلنا على أنس بن مالك فذكر الحديث.","grade":"صحيح","chapter_ar":"باب استحباب التبكير بالعصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Malik (Report 46) and Muslim (622). Muslim’s wording is: “That is the prayer of the hypocrite: he sits watching the sun until it is between the two horns of Satan, then he stands and pecks it out as four rakʿahs, remembering Allah in them only a little.”","chapter_en":"The recommendation to pray the ‘Asr (afternoon) prayer early.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Al-‘Ala’ ibn ‘Abd al-Rahman said: He entered upon Anas ibn Malik after Zuhr, and Anas stood and prayed ‘Asr. When he finished, we mentioned praying early (or it was mentioned), and he said: I heard the Messenger of Allah ﷺ say: “That is the prayer of the hypocrites— that is the prayer of the hypocrites— that is the prayer of the hypocrites: one of them sits until the sun becomes yellow and is between the two horns of Satan (or upon a horn of Satan), then he stands and pecks out four (quick) units, scarcely remembering Allah in them at all.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (46)، ورواه مسلم (622) وفيه: (( تلك صلاة المنافق، يجلس يرقب الشمس، حتى إذا كانت بين قرني الشيطان قام فنقرها أربعا، لا يذكر الله فيها إلا قليلا))."},{"num":1805,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا أُخْبِرُكُمْ بِصَلَاةِ الْمُنَافِقِ؟، أَنْ يُؤَخِّرَ الْعَصْرَ حَتَّى إِذَا كَانَتْ كَثَرَبِ الْبَقَرَةِ صَلَّاهَا."],"takhrij":"حسن: رواه الدارقطني في سننه (993) واللفظ له، والحاكم (702) كلاهما من طريق عبد السلام بن عبد الحميد، حدثنا موسى بن أعين، عن الأوزاعي، عن أبي النجاشي (واسمه عطاء بن صهيب) قال: سمعت رافع بن خديج يقول: فذكره.","grade":"حسن","chapter_ar":"باب استحباب التبكير بالعصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni in his Sunan (Report 993) and al-Hakim (Volume 1, page 195). The phrase “kathrib al-baqarah” refers to the thin fat that covers the stomach and intestines; the sun is compared to it when its light becomes thin/weak.","chapter_en":"The recommendation to pray the ‘Asr (afternoon) prayer early.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Rafi‘ ibn Khadij reported that the Messenger of Allah ﷺ said: “Shall I not tell you about the prayer of the hypocrite? He delays ‘Asr until the sun becomes like the thin fat that covers a cow’s stomach and intestines (meaning: when its light has weakened), then he prays it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني في سننه (993)، والحاكم (702). قوله: كثرب البقرة هو: الشحم الرقيق الذي يغشى الكرش والأمعاء تشبه الشمس بها إذا رق ضوءها."},{"num":1806,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: صَلَّى لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعَصْرَ، فَلَمَّا انْصَرَفَ، أَتَاهُ رَجُلٌ مِنْ بَنِي سَلِمَةَ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّا نُرِيدُ أَنْ نَنْحَرَ جَزُورًا لَنَا، وَنَحْنُ نُحِبُّ أَنْ تَحْضُرَهَا، قَالَ: نَعَمْ، فَانْطَلَقَ، وَانْطَلَقْنَا مَعَه، فَوَجَدْنَا الْجَزُورَ لَمْ تُنْحَرْ، فَنُحِرَتْ، ثُمَّ قُطِّعَتْ، ثُمَّ طُبِخَ مِنْهَا، ثُمَّ أَكَلْنَا قَبْلَ أَنْ تَغِيبَ الشَّمْسُ."],"takhrij":"صحيح: رواه مسلم في المساجد (624) من طريق ابن وهب، أخبرني عمرو","grade":"صحيح","chapter_ar":"باب استحباب التبكير بالعصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim (624).","chapter_en":"The recommendation to pray the ‘Asr (afternoon) prayer early.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ led us in the ‘Asr prayer. When he finished, a man from Banu Salimah came and said: “O Messenger of Allah, we want to slaughter a camel for ourselves, and we would love for you to attend.” He said: “Yes.” So he went and we went with him. We found that the camel had not yet been slaughtered, so it was slaughtered, cut up, cooked, and we ate before the sun set."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (624)."},{"num":1807,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قال: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِنَا الْعَصْرَ وَالشَّمْسُ بَيْضَاءُ مُحَلِّقَةٌ ."],"takhrij":"صحيح: رواه النسائي (508) عن إسحاق بن إبراهيم، قال: حدثنا جرير، عن منصور، عن رِبعي بن حِراش، عن أبي الأبيض، عن أنس فذكر الحديث.","grade":"صحيح","chapter_ar":"باب استحباب التبكير بالعصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by al-Nasa’i (508).","chapter_en":"The recommendation to pray the ‘Asr (afternoon) prayer early.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ used to lead us in the ‘Asr prayer while the sun was still bright and high."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (508)."},{"num":1808,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّمَا بَقَاؤُكُمْ فِيمَا سَلَفَ قَبْلَكُمْ مِنَ الْأُمَمِ كَمَا بَيْنَ صَلَاةِ الْعَصْرِ إِلَى غُرُوبِ الشَّمْسِ، أُوتِيَ أَهْلُ التَّوْرَاةِ التَّوْرَاةَ فَعَمِلُوا حَتَّى إِذَا انْتَصَفَ النَّهَارُ عَجَزُوا فَأُعْطُوا قِيرَاطًا قِيرَاطًا، ثُمَّ أُوتِيَ أَهْلُ الْإِنْجِيلِ الْإِنْجِيلَ فَعَمِلُوا إِلَى صَلَاةِ الْعَصْرِ ثُمَّ عَجَزُوا فَأُعْطُوا قِيرَاطًا قِيرَاطًا، ثُمَّ أُوتِينَا الْقُرْآنَ فَعَمِلْنَا إِلَى غُرُوبِ الشَّمْسِ فَأُعْطِينَا قِيرَاطَيْنِ قِيرَاطَيْنِ، فَقَالَ أَهْلُ الْكِتَابَيْنِ: أَيْ رَبَّنَا أَعْطَيْتَ هَؤُلَاءِ قِيرَاطَيْنِ قِيرَاطَيْنِ وَأَعْطَيْتَنَا قِيرَاطًا قِيرَاطًا وَنَحْنُ كُنَّا أَكْثَرَ عَمَلًا ؟ قَالَ: قَالَ اللَّهُ عَزَّ وَجَلَّ: هَلْ ظَلَمْتُكُمْ مِنْ أَجْرِكُمْ مِنْ شَيْءٍ ؟ قَالُوا: لَا، قَالَ: فَهُوَ فَضْلِي أُوتِيهِ مَنْ أَشَاءُ."],"takhrij":"صحيح: رواه البخاري في المواقيت (557) من حديث ابن شهاب، عن سالم بن عبدالله، عن أبيه عبدالله بن عمر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب أن وقت صلاة العصر يمتدّ إلى قبل الغروب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by al-Bukhari (557). The commentary indicates this points to the ‘Asr time extending until sunset, and it explains the meaning of the report: “Whoever catches one unit of the ‘Asr prayer before the sun sets should complete the prayer.”","chapter_en":"The time for the ‘Asr prayer extends until just before sunset.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar reported that he heard the Messenger of Allah ﷺ say: “Your remaining time compared to the nations before you is like the period between the ‘Asr prayer and sunset. The people of the Torah were given the Torah and worked until midday; then they became unable, so they were given one portion each. Then the people of the Gospel were given the Gospel and worked until the ‘Asr prayer; then they became unable, so they were given one portion each. Then we were given the Qur’an and worked until sunset, so we were given two portions each. The people of the two scriptures said: ‘Our Lord, You gave these people two portions each and gave us one portion each, even though we did more work.’ Allah, the Mighty and Majestic, said: ‘Have I wronged you in any part of your reward?’ They said: ‘No.’ He said: ‘That is My bounty; I grant it to whom I will.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (557). وفيه إشارة إلى أن وقت صلاة العصر يمتد إلى غروب الشمس، وهو تفسير لما جاء في حديث أبي هريرة: (( إذا أدرك أحدكم سجدة من صلاة العصر قبل أن تغرب الشمس فليتم صلاته ))."},{"num":1809,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الَّذِي تَفُوتُهُ صَلَاةُ الْعَصْرِ كَأَنَّمَا وُتِرَ أَهْلَهُ وَمَالَهُ."],"takhrij":"متفق عليه: رواه مالك في وقوت الصلاة (21) عن نافع، عن ابن عمر فذكر مثله، وعن مالكٍ رواه البخاري في المواقيت (552)، ومسلم في المساجد (200).","grade":"متفق عليه","chapter_ar":"باب إثم من فاتته صلاةُ العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (Report 21), al-Bukhari (552), and Muslim (626). The commentary explains that “missing” has been interpreted as delaying it beyond the valid time without an excuse, or missing it in congregation; and “deprived” means “reduced/stripped away.”","chapter_en":"The sin of missing the ‘Asr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “Whoever misses the ‘Asr prayer, it is as if he has been deprived of his family and his wealth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (21) والبخاري (552)، ومسلم (200). اختلف في المراد بالفوات، فقيل: تأخيرها عن وقت الجواز بغير عذر؛ لأن الإثم يترتب على ذلك وقيل: المراد بالفوات: فواتها في الجماعة. وقوله: وتر - أي نقص، يقال: وترته - إذا نقصته، فكأنك جعلت وترا بعد أن كان كثيرا."},{"num":1810,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْمَلِيحِ قَالَ: كُنَّا مَعَ بُرَيْدَةَ فِي غَزْوَةٍ فِي يَوْمٍ ذِي غَيْمٍ، فَقَالَ: بَكِّرُوا بِصَلَاةِ الْعَصْرِ، فَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ تَرَكَ صَلَاةَ الْعَصْرِ فَقَدْ حَبِطَ عَمَلُهُ."],"takhrij":"صحيح: رواه البخاري في المواقيت (553) عن مسلم بن إبراهيم قال حدثنا هشام قال حدثنا يحيى بن أبي كثير عن أبي قلابة عن أبي المليح قال: فذكره.","grade":"صحيح","chapter_ar":"باب إثم من فاتته صلاةُ العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by al-Bukhari (553). The commentary clarifies that “abandoning” here means negligent failure, which is why the Companion urged praying it early.","chapter_en":"The sin of missing the ‘Asr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Abu al-Malih said: We were with Buraydah on an expedition on a cloudy day, and he said: “Pray ‘Asr early, for the Prophet ﷺ said: ‘Whoever abandons the ‘Asr prayer, his deeds are nullified.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (553). والترك هنا بمعنى التفريط، ولذا حث الصحابي على المبادرة."},{"num":1811,"demo":false,"sanad":"","matn":["عَنْ نَوْفَلِ بْنِ مُعَاوِيَةَ مَرْفُوعًا: مِنَ الصَّلَاةِ صَلَاةٌ مَنْ فَاتَتْهُ فَكَأَنَّمَا وُتِرَ أَهْلَهُ وَمَالَهُ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3602)، ومسلم في الفتن (2886/11) كلاهما من حديث صالح بن كيسان، عن ابن شهاب، قال: حدثني أبو بكر بن عبدالرحمن بن الحارث، عن عبدالرحمن بن مطيع بن الأسود، عن نوفل بن معاوية فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب إثم من فاتته صلاةُ العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (3602) and Muslim (2886).","chapter_en":"The sin of missing the ‘Asr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Nawfal ibn Mu‘awiyah reported (as a statement attributed to the Prophet ﷺ): “Among the prayers is a prayer—whoever misses it, it is as if he has been deprived of his family and his wealth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3602)، ومسلم (2886)."},{"num":1812,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: لَمَّا كَانَ يَوْمُ الْأَحْزَابِ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَلَأَ اللَّهُ بُيُوتَهُمْ وَقُبُورَهُمْ نَارًا شَغَلُونَا عَنِ الصَّلَاةِ الْوُسْطَى حَتَّى غَابَتِ الشَّمْسُ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2931) وفي المغازي bukhari(4111) وفي التفسير bukhari(4533) وفي الدعوات (6396)، ومسلم في المساجد (627) كلاهما من طرق عن هشام، عن محمد، عن عَبِيدة، عن علي بن أبي طالب فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب الدليل لمن قال: الصلاة الوسطى هي العَصْرُ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6396, 4533, 4111, 2931) and Muslim (627).","chapter_en":"Evidence for the view that the middle prayer is the ‘Asr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["‘Ali ibn Abi Talib reported: On the day of the Confederates, the Messenger of Allah ﷺ said: “May Allah fill their houses and their graves with fire; they kept us busy from the middle prayer until the sun set.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿ حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَىٰ وَقُومُوا لِلَّهِ قَانِتِينَ ﴾","[سورة البقرة: ٢٣٨]"],"en":["Allah the Exalted said: “Guard the prayers and the middle prayer, and stand before Allah devoutly.” [Surah al-Baqarah, 2:238]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6396 ،4533 ،4111،2931)، ومسلم (627)."},{"num":1813,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: حَبَسَ الْمُشْرِكُونَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صَلَاةِ الْعَصْرِ حَتَّى احْمَرَّتِ الشَّمْسُ، أَوِ اصْفَرَّتْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: شَغَلُونَا عَنِ الصَّلَاةِ الْوُسْطَى صَلَاةِ الْعَصْرِ، مَلَأَ اللَّهُ أَجْوَافَهُمْ وَقُبُورَهُمْ نَارًا أَوَ قَالَ: حَشَا اللَّهُ أَجْوَافَهُمْ وَقُبُورَهُمْ نَارًا."],"takhrij":"صحيح: رواه مسلم في المساجد (628)، عن عون بن سلام الكوفي، نا محمد","grade":"صحيح","chapter_ar":"باب الدليل لمن قال: الصلاة الوسطى هي العَصْرُ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (628).","chapter_en":"Evidence for the view that the middle prayer is the ‘Asr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud reported: The polytheists kept the Messenger of Allah ﷺ from the ‘Asr prayer until the sun became red, or yellow. The Messenger of Allah ﷺ said: “They kept us busy from the middle prayer—the ‘Asr prayer. May Allah fill their insides and their graves with fire,” or he said: “May Allah stuff their insides and their graves with fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (628)."},{"num":1814,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: نَزَلَتْ هَذِهِ الآيَةُ: ﴿حَافِظُوا عَلَى الصَّلَوَاتِ وَصَلَاةِ الْعَصْرِ﴾ [ البقرة: 238]، فَقَرَأْنَاهَا مَا شَاءَ اللَّهُ، ثُمَّ نَسَخَهَا اللَّهُ، فَنَزَلَتْ ﴿حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى﴾ [ سورة البقرة: 238]، فَقَالَ رَجُلٌ، كَانَ جَالِسًا عِنْدَ شَقِيقٍ لَهُ: هِيَ إِذًا صَلَاةُ الْعَصْرِ ؟ فَقَالَ الْبَرَاءُ: قَدْ أَخْبَرْتُكَ كَيْفَ نَزَلَتْ، وَكَيْفَ نَسَخَهَا اللَّهُ، وَاللَّهُ أَعْلَمُ."],"takhrij":"صحيح: رواه مسلم في المساجد (630) من طريق الفُضيل بن مرزوق، عن شقيق بن عُقبة، عن البراء فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الدليل لمن قال: الصلاة الوسطى هي العَصْرُ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (630).","chapter_en":"Evidence for the view that the middle prayer is the ‘Asr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib reported: This verse was revealed: “Guard the prayers and the ‘Asr prayer.” We recited it as Allah willed, then Allah abrogated it and revealed: “Guard the prayers and the middle prayer.” A man who was sitting with Shuqayq said: “So it is the ‘Asr prayer then.” Al-Bara’ said: “I already told you how it was revealed and how Allah abrogated it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (630)."},{"num":1815,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدَبٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: صَلَاةُ الْوُسْطَى صَلَاةُ الْعَصْرِ."],"takhrij":"حسن: رواه الترمذي (182) عن هنّاد، حدثنا عَبْدَةُ، عن سعيد (وهو ابن أبي عروبة) عن الحسن، عن سمرة بن جندب فذكر مثله.","grade":"حسن","chapter_ar":"باب الدليل لمن قال: الصلاة الوسطى هي العَصْرُ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (182). Al-Tirmidhi said: Samurah’s report regarding the middle prayer is hasan.","chapter_en":"Evidence for the view that the middle prayer is the ‘Asr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Samurah ibn Jundub reported that the Prophet ﷺ said: “The middle prayer is the ‘Asr prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (182). وقال الترمذي: حديث سمرة في صلاة الوسطى حديث حسن."},{"num":1816,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَاتَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَدُوًّا، فَلَمْ يَفْرُغْ مِنْهُمْ حَتَّى أَخَّرَ الْعَصْرَ عَنْ وَقْتِهَا، فَلَمَّا رَأَى ذَلِكَ قَالَ: اللَّهُمَّ مَنْ حَبَسَنَا عَنِ الصَّلَاةِ الْوُسْطَى، فَامْلَأْ بُيُوتَهُمْ نَارًا، وَامْلَأْ قُبُورَهُمْ نَارًا وَنَحْوَ ذَلِكَ."],"takhrij":"حسن: رواه الإمام أحمد (2745)، والطبراني في الكبير (11905)، والأوسط (2016)، والبزار كشف الأستار (389)، كلهم من طريق هلال ابن خبَّاب، عن عكرمة، عن ابن عباس فذكره. ورواه عبد بن حميد في المنتخب (576) من هذا الوجه وقال فيه: فاملأ قلوبهم ناراً.","grade":"حسن","chapter_ar":"باب الدليل لمن قال: الصلاة الوسطى هي العَصْرُ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Imam Ahmad (2745), al-Tabarani in al-Mu‘jam al-Kabir (11905), and al-Bazzar in Kashf al-Astar (389).","chapter_en":"Evidence for the view that the middle prayer is the ‘Asr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Abbas said: The Prophet ﷺ fought an enemy and did not finish with them until he delayed the ‘Asr prayer beyond its time. When he realized that, he said: “O Allah, whoever kept us from the middle prayer, fill their houses with fire and fill their graves with fire,” or words to that effect."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (2745)، والطبراني في الكبير (11905)، والبزار في كشف الأستار (389)."},{"num":1817,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الأَحْزَابِ: شَغَلُونَا عَنِ الصَّلاةِ الْوُسْطَى مَلأَ اللَّهُ بُيُوتَهُمْ وَقُبُورَهُمْ نَارًا، يَعْنِي: صَلاةَ الْعَصْرِ."],"takhrij":"حسن: رواه البزار -كشف الأستار (388) عن سلمة بن شَبِيب، ثنا عبدالله بن جعفر الرقى، ثنا عبيدالله بن عمرو، عن زيد بن أبي أنيسة، عن عَديّ ابن ثابت، عن زِر، عن حذيفة فذكر الحديث.","grade":"حسن","chapter_ar":"باب الدليل لمن قال: الصلاة الوسطى هي العَصْرُ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Bazzar in Kashf al-Astar (388). Ibn Hibban graded it authentic (2891) with the wording: “They kept us busy from the ‘Asr prayer.”","chapter_en":"Evidence for the view that the middle prayer is the ‘Asr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Hudhayfah said: The Messenger of Allah ﷺ said on the Day of the Confederates: “They kept us busy from the middle prayer; may Allah fill their houses and their graves with fire,” meaning the ‘Asr prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (388). وصححه ابن حبان (2891) ولفظه: (( شغلونا عن صلاة العصر ))."},{"num":1818,"demo":false,"sanad":"","matn":["عَنْ كُهَيْلِ بْنِ حَرْمَلَةَ، عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ أَقْبَلَ حَتَّى نَزَلَ دِمَشْقَ، فَنَزَلَ عَلَى أَبِي كُلْثُومٍ الدَّوْسِيُّ، فَتَذَاكَرُوا الصَّلاةَ الْوُسْطَى، فَقَالَ: اخْتَلَفْنَا كَمَا اخْتَلَفْتُمْ، وَنَحْنُ بِفِنَاءِ بَيْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَ الرَّجُلُ الصَّالِحُ أَبُو هَاشِمِ بْنُ عُتْبَةَ، وَقَالَ: أَنَا أَعْلَمُ، لَكُمْ ذَلِكَ، فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَأْذَنَ عَلَيْهِ، وَكَانَ جَرِيئًا عَلَيْهِ، ثُمَّ خَرَجَ إِلَيْنَا فَأَعْلَمَنَا أَنَّهَا صَلاةُ الْعَصْرِ.","وَفِي رِوَايَةِ: وَفِينَا الرَّجُلُ الصَّالِحُ أَبُو هَاشِمِ بْنُ عُتْبَةَ بْنِ رَبِيعَةَ، فَقَامَ فَدَخَلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ جَرِيئًا عَلَيْهِ، ثُمَّ خَرَجَ إِلَيْنَا، فَأَخْبَرَنَا أَنَّهَا الْعَصْرُ."],"takhrij":"حسن: رواه البزار -كشف الأستار (391) عن أحمد بن منصور، ثنا هشام","grade":"حسن","chapter_ar":"باب الدليل لمن قال: الصلاة الوسطى هي العَصْرُ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Bazzar in Kashf al-Astar (391).","chapter_en":"Evidence for the view that the middle prayer is the ‘Asr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Kuhayl ibn Hurmalah, from Abu Hurayrah: He came until he reached Damascus and stayed with Abu Kulthum al-Dawsi. They discussed the middle prayer. He said: “We disagreed just as you have disagreed, while we were in the courtyard of the house of the Messenger of Allah ﷺ. Among us was a righteous man, Abu Hashim ibn ‘Utbah. He stood and went in to the Messenger of Allah ﷺ—he was bold with him—then he came out to us and informed us that it is the ‘Asr prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (391)."},{"num":1819,"demo":false,"sanad":"","matn":["عَنْ أَبِي يُونُسَ مَوْلَى عَائِشَةَ أَنَّهُ قَالَ: أَمَرَتْنِي عَائِشَةُ أَنْ أَكْتُبَ لَهَا مُصْحَفًا ثُمَّ قَالَتْ: إِذَا بَلَغْتَ هَذِهِ الآيَةَ فَآذِنِّي: ﴿حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى وَقُومُوا لِلَّهِ قَانِتِينَ﴾ [ البقرة: 238]، فَلَمَّا بَلَغْتُهَا، آذَنْتُهَا فَأَمْلَتْ عَلَيَّ: ﴿حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى ﴾ وَصَلَاةِ الْعَصْرِ ﴿ وَقُومُوا لِلَّهِ قَانِتِينَ﴾، قَالَتْ عَائِشَةُ: سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مالك في صلاة الجماعة (25) عن زيد بن أسلم، عن القعقاع بن حكيم، عن أبي يونس مولى عائشة أم المؤمنين فذكره.","grade":"صحيح","chapter_ar":"باب الدليل لمن قال: الصلاة الوُسطى هي الظهر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Malik in The Congregational Prayer (Report 25) and Muslim (629).","chapter_en":"Evidence for the view that the middle prayer is the Dhuhr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Abu Yunus, the freedman of ‘A’ishah, said: ‘A’ishah instructed me to write a copy of the Qur’an for her. She said: “When you reach this verse, inform me: ‘Guard the prayers and the middle prayer, and stand before Allah devoutly’ (2:238).” When I reached it, I informed her, and she dictated to me: “Guard the prayers, and the middle prayer, and the ‘Asr prayer, and stand before Allah devoutly.” ‘A’ishah said: “I heard it that way from the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (25)، ومسلم (629)."},{"num":1820,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ قَالَ: كَانَ رَسُولُ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الظُّهْرَ بِالْهَاجِرَةِ، وَلَمْ يَكُنْ يُصَلِّي صَلَاةً أَشَدَّ عَلَى أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهَا، فَنَزَلَتْ: ﴿حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى﴾ وَقَالَ: إِنَّ قَبْلَهَا صَلَاتَيْنِ وَبَعْدَهَا صَلَاتَيْنِ."],"takhrij":"صحيح: أخرجه أبو داود (411) قال: حدثنا محمد بن المثنى، حدثني محمد","grade":"صحيح","chapter_ar":"باب الدليل لمن قال: الصلاة الوُسطى هي الظهر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (411).","chapter_en":"Evidence for the view that the middle prayer is the Dhuhr prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Zayd ibn Thabit said: The Messenger of Allah ﷺ used to pray Dhuhr in the intense midday heat, and there was no prayer harder upon the Companions of the Messenger of Allah ﷺ than it. Then the verse was revealed: “Guard the prayers and the middle prayer.” And he said: “Before it are two prayers, and after it are two prayers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: أخرجه أبو داود (411)."},{"num":1821,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الأَكْوَعِ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي الْمَغْرِبَ إِذَا غَرَبَتِ الشَّمْسُ، وَتَوَارَتْ بِالْحِجَابِ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (561)، ومسلم في المساجد (636) كلاهما من طريق يزيد بن أبي عبيد، عن سلمة بن الأكوع فذكر الحديث، واللفظ لمسلم، ولفظ البخاري: كنا نُصَلِّي مع النبي صلى الله عليه وسلم المغربَ إذا توارتْ بالحجاب ولم يذكر إذا غربت الشمس اختصاراً لأن قوله: توارتْ بالحجاب يدل على غروبها.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أول وقت المغرب وهو عند غروب الشمس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (561) and Muslim (636). Muslim’s wording is as above; al-Bukhari’s wording: “We used to pray Maghrib with the Prophet ﷺ when it disappeared behind the horizon.”","chapter_en":"The beginning of the Maghrib time—at sunset.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Salamah ibn al-Akwa‘ reported that the Messenger of Allah ﷺ used to pray Maghrib when the sun set and disappeared behind the horizon."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (561)، ومسلم (636)، واللفظ لمسلم، ولفظ البخاري: (( كنا نصلي مع النبي ﷺ المغرب إذا توارت بالحجاب ))."},{"num":1822,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ، يَقُولُ: كُنَّا نُصَلِّي الْمَغْرِبَ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَنْصَرِفُ أَحَدُنَا وَإِنَّهُ لَيُبْصِرُ مَوَاقِعَ نَبْلِهِ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (559)، ومسلم في المساجد (637) كلاهما عن محمد بن مهران، حدثنا الوليد بن مسلم، حدثنا الأوزاعي، حدثني أبو النَجَاشِيّ هو: عطاء بن صهيب مولى رافع بن خَدِيجٍ قال: سمعت رافعَ بن خَديجٍ فذكر الحديث. ولفظهما سواء وشيخهما واحد.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أول وقت المغرب وهو عند غروب الشمس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (559) and Muslim (637). His saying “he could see where his arrow landed” means that Maghrib was begun at the very start of its time, immediately after sunset, so that they would finish while one of them could shoot an arrow and still see where it landed because light remained. These two hadiths show that Maghrib is hastened immediately after sunset, and this is a matter of consensus. As for the hadiths about delaying Maghrib until near the disappearance of twilight, they were intended to show the permissibility of delay, because they came in response to a question about the prayer time. Al-Nawawi noted this.","chapter_en":"The beginning of the Maghrib time—at sunset.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Rafi‘ ibn Khadij said: We used to pray Maghrib with the Prophet ﷺ, and one of us would finish and still be able to see where his arrow landed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (559)، ومسلم (637). وقوله: “ليبصر مواقع نبله”: معناه أنه يبكر بها في أول وقتها بمجرد غروب الشمس حتى ننصرف ويرمي أحدنا النبل عن قوسه، ويبصر موقعه لبقاء الضوء، وفي هذين الحديثين أن المغرب تعجل عقب غروب الشمس، وهذا مجمع عليه، وأما الأحاديث في تأخير المغرب إلى قريب سقوط الشفق فكانت لبيان جواز التأخير، فإنها كانت جواب سائل عن الوقت. أفاده النووي."},{"num":1823,"demo":false,"sanad":"","matn":["عَنْ مَرْثَدِ بْنِ عَبْدِ اللَّهِ قَالَ: لَمَّا قَدِمَ عَلَيْنَا أَبُو أَيُّوبَ غَازِيًا وَعُقْبَةُ بْنُ عَامِرٍ يَوْمَئِذٍ عَلَى مِصْرَ فَأَخَّرَ الْمَغْرِبَ، فَقَامَ إِلَيْهِ أَبُو أَيُّوبَ فَقَالَ لَهُ: مَا هَذِهِ الصَّلَاةُ يَا عُقْبَةُ ؟ قَالَ: أَمَا سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا تَزَالُ أُمَّتِي بِخَيْرٍ أَوْ قَالَ: عَلَى الْفِطْرَةِ مَا لَمْ يُؤَخِّرُوا الْمَغْرِبَ إِلَى أَنْ تَشْتَبِكَ النُّجُومُ."],"takhrij":"حسن: رواه أبو داود (418) عن عبيدالله بن عمر، حدثنا يزيد بن زريع، حدثنا محمد بن إسحاق، حدثني يزيد بن أبي حبيب، عن مَرْثَد بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أول وقت المغرب وهو عند غروب الشمس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan Sahih: narrated by Abu Dawud (418), Ahmad (23534), and Ibn Khuzaymah (339).","chapter_en":"The beginning of the Maghrib time—at sunset.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Marthad ibn ‘Abdullah said: When Abu Ayyub arrived among us as a campaigner, and ‘Uqbah ibn ‘Amir was then in authority over Egypt, he delayed the Maghrib prayer. Abu Ayyub went to him and said: “What is this prayer, O ‘Uqbah?” He said: “We were occupied.” Abu Ayyub said: “Did you not hear the Messenger of Allah ﷺ say: ‘My community will remain upon goodness—or he said: upon the natural way—so long as they do not delay Maghrib until the stars become interwoven’?”"]},"buhuth":{"en":["Commentary: The phrase “the stars become interwoven” means: the stars appear and become mixed together (i.e., they are clearly visible and spread across the sky)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (418)، وأحمد (23534)، وابن خزيمة (339)."},{"num":1824,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَسْلَمَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُمْ كَانُوا يُصَلُّونَ مَعَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَغْرِبَ ثُمَّ يَرْجِعُونَ إِلَى أَهَالِيهِمْ إِلَى أَقْصَى الْمَدِينَةِ يَرْمُونَ وَيُبْصِرُونَ مَوَاقِعَ سِهَامِهِمْ."],"takhrij":"حسن: رواه النسائي (520) قال: حدثنا محمد بن بشَّار، قال: حدثنا محمد، قال: حدثنا شعبة، عن أبي بِشْرٍ، قال: سمعت حسان بن بلال، عن رجل من أسلم من أصحاب النبي صلى الله عليه وسلم فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في أول وقت المغرب وهو عند غروب الشمس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasa’i (520).","chapter_en":"The beginning of the Maghrib time—at sunset.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["A man from the tribe of Aslam—one of the Companions of the Prophet ﷺ—said: They used to pray Maghrib with the Prophet ﷺ, then return to their families at the far end of the city, and they would shoot and still be able to see where their arrows landed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (520)."},{"num":1825,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كُنَّا نُصَلِّي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَغْرِبَ، ثُمَّ نَرْجِعُ إِلَى مَنَازِلِنَا وَهِيَ مِيلٌ، وَأَنَا أُبْصِرُ مَوَاقِعَ النَّبْلِ."],"takhrij":"حسن: رواه الإمام أحمد (14971) وأبو يعلى المقصد العلي (192) والبزار -كشف الأستار (374) كلهم من طرق عن سفيان، عن عبدالله بن محمد بن عقيل، قال: سمعت جابر بن عبدالله فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في أول وقت المغرب وهو عند غروب الشمس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Imam Ahmad (14971), Abu Ya‘la in al-Maqsad al-‘Ali (192), and al-Bazzar in Kashf al-Astar (374).","chapter_en":"The beginning of the Maghrib time—at sunset.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: We used to pray Maghrib with the Prophet ﷺ, then return to our homes, which were about a mile away, and we could still see where the arrows landed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (14971) وأبو يعلى في المقصد العلي (192) والبزار في كشف الأستار (374)."},{"num":1826,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ قَالَ: كُنَّا نُصَلِّي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَغْرِبَ، وَنَنْصَرِفُ إِلَى السُّوقِ، وَلَوْ رَمَى أَحَدُنَا بِالنَّبْلِ قَالَ عُثْمَانُ: رَمَى بِنَبْلٍ لَأَبْصَرَ مَوَاقِعَهَا."],"takhrij":"حسن: رواه الإمام أحمد (17029 ،17052) والطبراني في الكبير (5259) وعبد بن حميد (281) وابن أبي شيبة (3330) كلّهم من طريق ابن أبي ذئب، عن صالح مولى التوأمة، عن زيد بن خالد، فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في أول وقت المغرب وهو عند غروب الشمس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Imam Ahmad (17052 and 17029), al-Tabarani in al-Mu‘jam al-Kabir (volume 5, page 292), and Ibn Abi Shaybah (volume 1, page 329).","chapter_en":"The beginning of the Maghrib time—at sunset.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani said: We used to pray Maghrib with the Prophet ﷺ, then leave for the marketplace. If one of us were to shoot an arrow—‘Uthman said: “shot an arrow”—he would still be able to see where it landed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17052) (17029) والطبراني في الكبير (5259) وابن أبي شيبة (3330)."},{"num":1827,"demo":false,"sanad":"","matn":["عَنِ ابْنِ كَعْبِ بْنِ مَالِكٍ، عَنْ أَبِيهِ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي الْمَغْرِبَ، وَيُصَلِّي مَعَهُ رِجَالٌ مِنْ بَنِي سَلَمَةَ، ثُمَّ يَنْصَرِفُونَ إِلَى بَنِي سَلَمَةَ وَهُمْ يُبْصِرُونَ مَوَاقِعَ النَّبْلِ."],"takhrij":"حسن: رواه الطبراني في الكبير في الكبير (19/ح 115) وفي الأوسط (5284) مجمع البحرين (564) عن محمد بن أحمد بن البراء، ثنا المعافي بن سليمان، ثنا موسى بن أعين، عن إسحاق بن راشد، عن الزهري، أخبرني ابن كعب بن مالك، عن أبيه فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في أول وقت المغرب وهو عند غروب الشمس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Tabarani in al-Mu‘jam al-Kabir (volume 19, page 62), and in al-Awsat as cited in Majma‘ al-Bahrayn (reference 564).","chapter_en":"The beginning of the Maghrib time—at sunset.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["From Ibn Ka‘b ibn Malik, from his father: The Prophet ﷺ used to pray Maghrib, and men from Banu Salimah would pray with him. Then they would return to Banu Salimah while still able to see where arrows landed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (19/ح 115) وفي الأوسط في مجمع البحرين (564)."},{"num":1828,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أَعْتَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً مِنَ اللَّيَالِي بِصَلَاةِ الْعِشَاءِ، وَهِيَ الَّتِي تُدْعَى الْعَتَمَةَ، فَلَمْ يَخْرُجْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى قَالَ عُمَرُ بْنُ الْخَطَّابِ: نَامَ النِّسَاءُ وَالصِّبْيَانُ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لِأَهْلِ الْمَسْجِدِ حِينَ خَرَجَ عَلَيْهِمْ: مَا يَنْتَظِرُهَا أَحَدٌ مِنْ أَهْلِ الأَرْضِ غَيْرُكُمْ، وَذَلِكَ قَبْلَ أَنْ يَفْشُوَ الإِسْلَامُ فِي النَّاسِ.","وَفِي رِوَايَةِ: قَالَتْ: أَعْتَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، حَتَّى ذَهَبَ عَامَّةُ اللَّيْلِ، وَحَتَّى نَامَ أَهْلُ الْمَسْجِدِ، ثُمَّ خَرَجَ فَصَلَّى فَقَالَ: إِنَّهُ لَوَقْتُهَا لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (569)، ومسلم في المساجد (638) كلاهما من حديث ابن شهاب، عن عروة، عن عائشة واللفظ لمسلم، وقال: وزاد حرملة في روايته: قال ابن شهاب: وذُكِر لي أن رسول الله صلى الله عليه وسلم قال: وما كان لكم أن تَنْزُرُوا رسولَ الله صلى الله عليه وسلم على الصلاة وذلك حين صاحَ عمرُ بن الخطاب.","grade":"متفق عليه","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (569) and Muslim (638), with Muslim’s wording. The commentary explains that “much of the night” means a large portion, not most of it, because this statement indicates it was still within the preferred/valid time; it cannot mean after midnight, since no scholar considered delaying ‘Isha’ past midnight to be more virtuous (as noted by al-Nawawi).","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: One night the Messenger of Allah ﷺ delayed the ‘Isha’ prayer—the one also called “al-‘Atamah.” He did not come out until ‘Umar ibn al-Khattab said: “Women and children have fallen asleep.” Then the Messenger of Allah ﷺ came out and said to the people of the mosque when he appeared to them: “No one on earth is waiting for it except you,” and that was before Islam had spread widely among people. In another narration she said: The Messenger of Allah ﷺ delayed one night until much of the night had passed and the people of the mosque had fallen asleep. Then he came out, prayed, and said: “This is its time—if it were not that I would cause hardship for my community.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (569)، ومسلم (638) واللفظ لمسلم."},{"num":1829,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شُغِلَ عَنْهَا لَيْلَةً (أَيْ عَنِ الْعِشَاءِ) فَأَخَّرَهَا حَتَّى رَقَدْنَا فِي الْمَسْجِدِ، ثُمَّ اسْتَيْقَظْنَا، ثُمَّ رَقَدْنَا، ثُمَّ اسْتَيْقَظْنَا، ثُمَّ خَرَجَ عَلَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: لَيْسَ أَحَدٌ مِنْ أَهْلِ الْأَرْضِ يَنْتَظِرُ الصَّلَاةَ غَيْرُكُمْ.","وَفِي رِوَايَةِ: قَالَ ابْنِ عُمَرَ: مَكَثْنَا ذَاتَ لَيْلَةٍ نَنْتَظِرُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِصَلَاةِ الْعِشَاءِ الآخِرَةِ، فَخَرَجَ إِلَيْنَا، حِينَ ذَهَبَ ثُلُثُ اللَّيْلِ أَوْ بَعْدَهُ، فَلَا نَدْرِي أَشَيْءٌ شَغَلَهُ فِي أَهْلِهِ، أَوْ غَيْرُ ذَلِكَ، فَقَالَ حِينَ خَرَجَ: إِنَّكُمْ لَتَنْتَظِرُونَ صَلَاةً، مَا يَنْتَظِرُهَا أَهْلُ دِينٍ غَيْرُكُمْ، وَلَوْلَا أَنْ يَثْقُلَ عَلَى أُمَّتِي، لَصَلَّيْتُ بِهِمْ هَذِهِ السَّاعَةَ، ثُمَّ أَمَرَ الْمُؤَذِّنَ، فَأَقَامَ الصَّلَاةَ وَصَلَّى."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (570)، ومسلم في المساجد (639) كلاهما من عبد الرزاق، قال: أخبرني ابن جريج، قال: أخبرني نافع، قال: حدثنا عبدالله بن عمر فذكر الحديث، وهو في المصنف (2115).","grade":"متفق عليه","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (570) and Muslim (639).","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ was occupied from it—meaning the ‘Isha’ prayer—so he delayed it until we fell asleep in the mosque, then woke up, then fell asleep again, then woke up again. Then the Prophet ﷺ came out to us and said: “No one on earth is waiting for this prayer except you.” In another narration Ibn ‘Umar said: We stayed one night waiting for the Messenger of Allah ﷺ for the late ‘Isha’. He came out to us when a third of the night had passed or after that. We did not know whether something with his family or something else delayed him. When he came out he said: “You are waiting for a prayer that no followers of any other religion are waiting for; and if it were not burdensome for my community, I would have led them in it at this hour.” Then he ordered the caller to establish the prayer and he prayed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (570)، ومسلم (639)."},{"num":1830,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: أَخَّرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ، ثُمَّ صَلَّى ثُمَّ قَالَ: قَدْ صَلَّى النَّاسُ وَنَامُوا، أَمَا إِنَّكُمْ فِي صَلَاةٍ مَا انْتَظَرْتُمُوهَا.","وَفِي رِوَايَةِ: ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ بَعْدَ مَا صَلَّى فَقَالَ: صَلَّى النَّاسُ وَرَقَدُوا وَلَمْ تَزَالُوا فِي صَلَاةٍ مُنْذُ انْتَظَرْتُمُوهَا قَالَ (أَنَس): فَكَأَنِّي أَنْظُرُ إِلَى وَبِيصِ خَاتَمِهِ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (572) وفي الأذان (661)، من طريقين عن حميد الطويل، عن أنسٍ، ومسلم في المساجد (640) من وجهٍ آخر عن أنسٍ.","grade":"متفق عليه","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (572) and Muslim (640).","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ delayed the ‘Isha’ prayer until midnight, then he prayed and said: “People have prayed and gone to sleep, but you are considered in prayer so long as you were waiting for it.” In another narration: After he prayed, he turned to us and said: “People have prayed and gone to sleep, and you have remained in prayer since you began waiting for it.”","Anas said: It is as if I can still see the gleam of his ring."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (572)، ومسلم (640)."},{"num":1831,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: كُنْتُ أَنَا وَأَصْحَابِي الَّذِينَ قَدِمُوا مَعِي فِي السَّفِينَةِ، نُزُولًا فِي بَقِيعِ بُطْحَانَ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ، فَكَانَ يَتَنَاوَبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ صَلَاةِ الْعِشَاءِ كُلَّ لَيْلَةٍ نَفَرٌ مِنْهُمْ، قَالَ أَبُو مُوسَى: فَوَافَقْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَأَصْحَابِي، وَلَهُ بَعْضُ الشُّغْلِ فِي أَمْرِهِ، حَتَّى أَعْتَمَ بِالصَّلَاةِ حَتَّى ابْهَارَّ اللَّيْلُ، ثُمَّ خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى بِهِمْ، فَلَمَّا قَضَى صَلَاتَهُ قَالَ لِمَنْ حَضَرَهُ عَلَى رِسْلِكُمْ: أُعْلِمُكُمْ وَأَبْشِرُوا، أَنَّ مِنْ نِعْمَةِ اللَّهِ عَلَيْكُمْ، أَنَّهُ لَيْسَ مِنَ النَّاسِ أَحَدٌ يُصَلِّي هَذِهِ السَّاعَةَ غَيْرُكُمْ، أَوَ قَالَ: مَا صَلَّى هَذِهِ السَّاعَةَ أَحَدٌ غَيْرُكُمْ، لَا نَدْرِي أَيَّ الْكَلِمَتَيْنِ قَالَ. قَالَ أَبُو مُوسَى: فَرَجَعْنَا فَرِحِينَ بِمَا سَمِعْنَا مِنَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (567)، ومسلم في المساجد (641) كلاهما عن أبي أسامة، عن بُريد، عن أبي بردة، عن أبي موسى فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (567) and Muslim (641).","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Abu Musa said: My companions and I—who came with me on the ship—were staying at Baqi‘ Buthan, while the Messenger of Allah ﷺ was in Madinah. A group of them would take turns coming to the Messenger of Allah ﷺ at the ‘Isha’ prayer each night. Abu Musa said: My companions and I happened to meet the Messenger of Allah ﷺ while he was occupied with some matter, and he delayed the prayer until the night reached its middle. Then he came out and led them in prayer. When he finished, he said to those present: “Take it easy—let me inform you and give you good news: among Allah’s favors upon you is that none of the people are praying at this hour except you,” or he said: “No one has prayed at this hour except you.” (We do not know which of the two phrases he said.) Abu Musa said: We returned joyful because of what we heard from the Messenger of Allah ﷺ."]},"buhuth":{"en":["“Baqi‘ Buthan” — “baqi‘” is a spacious tract of land; Ibn al-Athir said it is not called “baqi‘” except when it contains trees or their roots. “Buthan” is a specific place: a valley in Madinah. “They take turns” means a group would come in shifts each night, not all together. “The night reached its middle” means it became halfway through; this is supported by narrations that say “close to midnight.” The “occupation” mentioned was preparing an army, as noted in al-Fath (2/48)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (567)، ومسلم (641)."},{"num":1832,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ يَقُولُ: أَعْتَمَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ الْعِشَاءَ قَالَ: حَتَّى رَقَدَ نَاسٌ وَاسْتَيْقَظُوا، وَرَقَدُوا وَاسْتَيْقَظُوا فَقَامَ عُمَرُ بْنُ الْخَطَّابِ فَقَالَ: الصَّلَاةَ فَقَالَ ابْنُ عَبَّاسٍ: فَخَرَجَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَأَنِّي أَنْظُرُ إِلَيْهِ الآنَ، يَقْطُرُ رَأْسُهُ مَاءً وَاضِعًا يَدَهُ عَلَى شِقِّ رَأْسِهِ، قَالَ: لَوْلَا أَنْ يَشُقَّ عَلَى أُمَّتِي، لَأَمَرْتُهُمْ أَنْ يُصَلُّوهَا، كَذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (571)، ومسلم في المساجد (642) كلاهما من حديث عبد الرزاق، قال أخبرني ابن جريج، قال: قلت لعطاء: أيُّ حينٍ أَحَبُّ إليك أن أُصَلِّي العِشَاءَ التي يقولُها الناس العَتَمَةَ إِمَاماً وخِلْواً؟ قال: سمعت ابن عباس يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (571) and Muslim (642).","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Ibn ‘Abbas said: One night the Messenger of Allah ﷺ delayed ‘Isha’ until some people fell asleep, then woke up, then fell asleep again, then woke up again. ‘Umar ibn al-Khattab stood and said: “The prayer!” ‘Ata’ said: Ibn ‘Abbas said: Then the Prophet of Allah ﷺ came out—I can almost see him now—with water dripping from his head, placing his hand on the side of his head, and he said: “If it were not that it would cause hardship for my community, I would have commanded them to pray it like this.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (571)، ومسلم (642)."},{"num":1833,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يُؤَخِّرُ صَلَاةَ الْعِشَاءِ الآخِرَةِ.","وَفِي رِوَايَةِ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يُصَلِّي الصَّلَوَاتِ نَحْوًا مِنْ صَلَاتِكُمْ، وَكَانَ يُؤَخِّرُ الْعَتَمَةَ بَعْدَ صَلَاتِكُمْ شَيْئًا، وَكَانَ يُخِفُّ الصَّلَاةَ.","وَفِي رِوَايَةِ: يُخَفِّفُ."],"takhrij":"صحيح: رواه مسلم في المساجد (643) عن أبي الأحوص، عن سماك، عن جابر، والرواية الثانية: عن أبي عوانة، عن سماك به مثله.","grade":"صحيح","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (643). Also narrated by Abu Dawud al-Tayalisi in his Musnad (810) with wording indicating: he prayed Dhuhr, ‘Asr, and Maghrib similarly to you, but delayed ‘Isha’ somewhat.","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn Samurah said: The Messenger of Allah ﷺ used to delay the late ‘Isha’ prayer. In another narration: The Messenger of Allah ﷺ used to pray the prayers roughly as you do, but he would delay “al-‘Atamah” (the ‘Isha’ prayer) somewhat beyond the time you prayed it, and he would keep the prayer light (brief)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (643). ورواه أبو داود الطيالسي في مسنده (810) ولفظه: كان رسول الله ﷺ يصلي الظهر نحو صلاتكم، والعصر نحو صلاتكم، والمغرب نحو صلاتكم، وكان يؤخر العشاء شيئا."},{"num":1834,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ وَلَأَخَّرْتُ صَلَاةَ الْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ."],"takhrij":"صحيح: رواه الترمذي (23) قال: حدثنا هنَّاد، حدثنا عبدة بن سليمان، عن محمد بن إسحاق، عن محمد بن إبراهيم، عن أبي سلمة، عن زيد بن خالد الجهني فذكر الحديث. قال الترمذي: حسن صحيح.","grade":"صحيح","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih (graded “Hasan Sahih” by al-Tirmidhi): narrated by al-Tirmidhi (23), Abu Dawud (47), and al-Nasa’i in al-Kubra (volume 3, page 291).","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani said: I heard the Messenger of Allah ﷺ say: “If it were not that I would cause hardship for my community, I would have commanded them to use the tooth-stick at every prayer, and I would have delayed the ‘Isha’ prayer until a third of the night.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (23) وقال: (( حسن صحيح)). وأبو داود (47)، والنسائي في الكبرى (6)."},{"num":1835,"demo":false,"sanad":"","matn":["عَنْ النُّعْمَانِ بْنِ بَشِيرٍ قَالَ: أَنَا أَعْلَمُ النَّاسِ بِوَقْتِ هَذِهِ الصَّلَاةِ صَلَاةِ الْعِشَاءِ الْآخِرَةِ، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّيهَا لِسُقُوطِ الْقَمَرِ لِثَالِثَةٍ."],"takhrij":"صحيح: أخرجه أبو داود (419)، والترمذي (165)، والنسائي (529) كلهم من طريق أبي عوانة، عن أبي بِشْرٍ، عن بَشِير بن ثابتٍ، عن حبيب بن سالم، عن النعمان بن بشير فذكر مثله.","grade":"صحيح","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (419), al-Tirmidhi (165), and al-Nasa’i (529).","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Al-Nu‘man ibn Bashir said: I know best the time of this prayer: the Messenger of Allah ﷺ used to pray it when the moon had set for the third night (i.e., early in the night, shortly after its time began)."]},"buhuth":{"en":["This hadith indicates performing ‘Isha’ early after its time begins, while other hadiths indicate that delaying it is recommended. The guideline is what Jabir ibn ‘Abdullah mentioned: the Prophet ﷺ sometimes prayed ‘Isha’ earlier and sometimes later—if he saw people had gathered, he hastened it; if he saw they were slow to gather, he delayed it—just as discussed in the chapter on timing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: أخرجه أبو داود (419)، والترمذي (165)، والنسائي (529)."},{"num":1836,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: صَلَّيْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْعَتَمَةِ، فَلَمْ يَخْرُجْ حَتَّى مَضَى نَحْوٌ مِنْ شَطْرِ اللَّيْلِ فَقَالَ: خُذُوا مَقَاعِدَكُمْ، فَأَخَذْنَا مَقَاعِدَنَا، فَقَالَ: إِنَّ النَّاسَ قَدْ صَلَّوْا وَأَخَذُوا مَضَاجِعَهُمْ، وَإِنَّكُمْ لَنْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمُ الصَّلَاةَ، وَلَوْلَا ضَعْفُ الضَّعِيفِ وَسَقَمُ السَّقِيمِ لَأَخَّرْتُ هَذِهِ الصَّلَاةَ إِلَى شَطْرِ اللَّيْلِ."],"takhrij":"صحيح: أخرجه أبو داود (422)، والنسائي (538)، وابن ماجة (693) كلهم من طريق داود بن أبي هند، عن أبي نَضْرة، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (422), al-Nasa’i (538), and Ibn Majah (693), with Abu Dawud’s wording.","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: We prayed with the Messenger of Allah ﷺ the prayer called “al-‘Atamah,” and he did not come out until about half the night had passed. Then he said: “Stay where you are,” so we remained seated. He said: “The people have prayed and gone to their beds, and you will remain counted as being in prayer as long as you are waiting for the prayer. If it were not for the weakness of the weak and the illness of the sick, I would have delayed this prayer until half the night.”"]},"buhuth":{"en":["The phrase “we prayed al-‘Atamah” means the ‘Isha’ prayer; al-‘Atamah is a name used for ‘Isha’, and this hadith concerns delaying it until about half the night."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: أخرجه أبو داود (422)، والنسائي (538)، وابن ماجه (693) واللفظ لأبي داود."},{"num":1837,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ جَبَلٍ يَقُولُ: ارْتَقَبْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الْعَتَمَةِ فَأَخَّرَ حَتَّى ظَنَّ الظَّانُّ أَنَّهُ لَيْسَ بِخَارِجٍ، وَالْقَائِلُ مِنَّا يَقُولُ: صَلَّى، فَإِنَّا لَكَذَلِكَ، حَتَّى خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا لَهُ كَمَا قَالُوا، فَقَالَ لَهُمْ: أَعْتِمُوا بِهَذِهِ الصَّلَاةِ، فَإِنَّكُمْ قَدْ فُضِّلْتُمْ بِهَا عَلَى سَائِرِ الْأُمَمِ، وَلَمْ تُصَلِّهَا أُمَّةٌ قَبْلَكُمْ."],"takhrij":"صحيح: أخرجه أبو داود (421) قال: حدثنا عمرو بن عثمان الحِمصي، ثنا أبي، ثنا حَريز، يعني عثمان، عن راشد بن سعد، عن عاصم بن حُميد السَّكوني، أنه سمع معاذ بن جبل يقول: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (421)","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Mu‘adh ibn Jabal said: We waited for the Prophet ﷺ for the night prayer, and he delayed it until someone thought he would not come out, while one of us kept saying, “He has prayed.” We remained like that until the Prophet ﷺ came out. They said to him what they had been saying, so he said: “Pray this prayer when it is truly dark, for you have been favored with it over the rest of the nations, and no nation before you performed it.”"]},"buhuth":{"en":["“Praying when it is truly dark” means entering into the darkness of the night. The phrase “we waited” is pronounced with an open “b” and “q,” on the pattern of “we threw.” Al-Khattabi said its meaning is “we waited.” It is said: “I waited for a man” meaning: I stayed expecting him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (421)."},{"num":1838,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْلَا أَنْ أَشُقَّ عَلَى الْمُؤْمِنِينَ لَأَمَرْتُهُمْ بِتَأْخِيرِ الْعِشَاءِ وَبِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ."],"takhrij":"صحيح: رواه أبو داود (46)، وابن ماجة (690) كلاهما من حديث سفيان بن عيينة، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (46), Ibn Majah (690)","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “If it were not that I would cause hardship for the believers, I would have commanded them to delay the night prayer and to use the tooth-stick at every prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (46)، ابن ماجه (690)."},{"num":1839,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَصْحَابِهِ ذَاتَ لَيْلَةٍ، وَهُمْ يَنْتَظِرُونَ الْعِشَاءَ، فَقَالَ: صَلَّى النَّاسُ وَرَقَدُوا وَأَنْتُمْ تَنْتَظِرُونَهَا، أَمَا إِنَّكُمْ فِي صَلَاةٍ مَا انْتَظَرْتُمُوهَا، ثُمَّ قَالَ: لَوْلَا ضَعْفُ الضَّعِيفِ وَكِبَرُ الْكَبِيرِ لَأَخَّرْتُ هَذِهِ الصَّلَاةَ إِلَى شِطْرِ اللَّيْلِ."],"takhrij":"صحيح: أخرجه أبو يعلى (1939) (1935 تحقيق الأثري)، قال: حدثنا أبو خيثمة، حدثنا محمد بن حازم (وهو أبو معاوية الضرير)، حدثنا داود بن أبي هند، عن أبي نضرة، عن جابر فذكر مثله.","grade":"صحيح","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Ya‘la (1935, al-Athari edition), Ibn Hibban (1529), Ibn Abi Shaybah (1/402)","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: One night the Messenger of Allah ﷺ came out to his companions while they were waiting for the night prayer and said: “People have prayed and gone to sleep, while you are waiting for it. Indeed, you are in prayer as long as you are waiting for it.” Then he said: “Were it not for the weakness of the weak and the age of the elderly, I would have delayed this prayer until the middle of the night.”"]},"buhuth":{"en":["Additional report","In Ahmad (14949): The Messenger of Allah ﷺ prepared an expedition one night until half the night passed (or nearly that), then he came out and said: “People have prayed and gone to sleep, while you are waiting for this prayer. Indeed, you will remain in prayer as long as you are waiting for it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (1939)، وابن حبان (1529)، وابن أبي شيبة (4063)."},{"num":1840,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ وَقْتِ الْعِشَاءِ؟ قَالَ: إِذَا مَلَأَ اللَّيْلُ بَطْنَ كُلَّ وَادٍ."],"takhrij":"حسن: أخرجه الطبراني في الأوسط (3963)، مجمع البحرين (567) عن علي بن سعيد الرازي، ثنا قطن بن نُسير الذراع، ثنا جعفر بن سليمان الضبعي، عن محمد بن عمرو، عن يحيى بن عبدالرحمن بن حاطب، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAl-Tabarani in al-Awsat; cited in Majma‘ al-Bahrayn (567) and (1/434)","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ was asked about the time of the night prayer, and he said: “When the night has filled the depth of every valley.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط، كما في مجمع البحرين (567)."},{"num":1841,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ قَالَ: أَخَّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْعِشَاءِ ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ، فَإِذَا النَّاسُ يَنْتَظِرُونَ الصَّلَاةَ قَالَ: أَمَا إِنَّهُ لَيْسَ مِنْ أَهْلِ هَذِهِ الْأَدْيَانِ أَحَدٌ يَذْكُرُ اللَّهَ هَذِهِ السَّاعَةَ غَيْرُكُمْ قَالَ: وَأَنْزَلَ هَؤُلَاءِ الْآيَاتِ: ﴿لَيْسُوا سَوَاءً مِنْ أَهْلِ الْكِتَابِ﴾ حَتَّى بَلَغَ ﴿وَمَا يَفْعَلُوا مِنْ خَيْرٍ فَلَنْ يُكْفَرُوهُ وَاللَّهُ عَلِيمٌ بِالْمُتَّقِينَ﴾ [آل عمران: 113، 115]."],"takhrij":"حسن: أخرجه أحمد (3760)، وأبو يعلى (5306) (5285 الأثري)، والبزار- كشف الأستار (375)، والحارث بن أبي أسامة: بغية الباحث (1/255، 132)كلهم من طريق عاصم، عن زِرّ، عن عبدالله بن مسعود فذكره.","grade":"حسن","chapter_ar":"باب وقت صلاة العشاء وتأخيرها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (3760), Abu Ya‘la (5285, al-Athari edition), al-Bazzar in Kashf al-Astar (1/190)","chapter_en":"The time of the ‘Isha’ prayer and delaying it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Ibn Mas‘ud said: The Messenger of Allah ﷺ delayed the night prayer, then came out to the mosque while the people were waiting for the prayer. He said: “There is none from the followers of these religions who remembers Allah at this hour except you.” He said: And these verses were revealed: “They are not all alike among the People of the Book …” until His saying: “Whatever good they do will not be denied to them, and Allah knows well those who are mindful of Him.” (Al ‘Imran 3:113–115)"]},"buhuth":{"en":["The phrase “the followers of these religions” refers to the Jews and Christians in Madinah and nearby areas, not to all people on earth in an absolute sense, because remembrance of Allah does not cease at any hour of the night or day.","Summary on the time of the night prayer: Al-Zayla‘i cited a good discussion from al-Tahawi in Sharh Ma‘ani al-Athar (1/158). In brief, he said: From the combined reports, the last time for the night prayer extends until dawn begins. This is because Ibn ‘Abbas, Abu Musa, and Abu Sa‘id reported that the Prophet ﷺ delayed it until one-third of the night; Abu Hurayrah and Anas reported he delayed it until half the night; Ibn ‘Umar reported he delayed it until a third of the night had passed; and ‘A’ishah reported he delayed it until most of the night was gone—these narrations are in the authentic collections. Thus, the entire night is a valid time for it, but it has three levels: from its start until one-third of the night is the most virtuous; after that until half the night is less virtuous; and after half the night is less than that. See Nasb al-Rayah (1/234–235)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (3760)، وأبو يعلى (5306)، والبزار في كشف الأستار (375)."},{"num":1842,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا تَغْلِبَنَّكُمْ الأَعْرَابُ عَلَى اسْمِ صَلَاتِكُمْ، أَلَا إِنَّهَا الْعِشَاءُ، وَهُمْ يُعْتِمُونَ بِالإِبِلِ.","وَفِي رِوَايَةِ: فَإِنَّهَا فِي كِتَابِ اللَّهِ الْعِشَاءُ، وَإِنَّهَا تُعْتِمُ بِحِلَابِ الإِبِلِ."],"takhrij":"صحيح: رواه مسلم في المساجد (644) من طريق سفيان بن عيينة، عن أبي لبيد، عن أبي سلمة، عن عبدالله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب كراهية أن يُقالَ لصلاة العِشَاء العَتَمَة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (644)","chapter_en":"Dislike of calling the night prayer “al-‘Atamah.”","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: I heard the Messenger of Allah ﷺ say: “Do not let the desert Arabs override you regarding the name of your prayer. Indeed, it is the night prayer, while they delay milking the camels until late.” In another narration: “For in the Book of Allah it is called the night prayer, and they delay it because of camel-milking.”"]},"buhuth":{"en":["The phrase “they delay” means they postpone milking the camels, and they name the prayer after the time when milking occurs. Al-Khattabi mentioned a related expression: a person is described as one who delays hospitality when guests arrive and he does not serve them promptly.","His statement, “Its name in the Book of Allah is the night prayer,” points to the verse: “and after the night prayer” (Qur’an 24:58). However, authentic reports also use the term “the late-night prayer,” such as: “If they knew what is in the dawn prayer and the late-night prayer, they would come to them even crawling.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (644)."},{"num":1843,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: صَلَّى لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً صَلَاةَ الْعِشَاءِ وَهِيَ الَّتِي يَدْعُو النَّاسُ الْعَتَمَةَ، ثُمَّ انْصَرَفَ فَأَقْبَلَ عَلَيْنَا فَقَالَ: أَرَأَيْتُمْ لَيْلَتَكُمْ هَذِهِ، فَإِنَّ رَأْسَ مِائَةِ سَنَةٍ مِنْهَا لَا يَبْقَى مِمَّنْ هُوَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ."],"takhrij":"متفق عليه: رواه البخاري في مواقيت الصلاة (564) ومسلم في فضائل الصحابة (2537) كلاهما من طريق الزهري، قال سالم: أخبرني عبدالله فذكره، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب كراهية أن يُقالَ لصلاة العِشَاء العَتَمَة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (564), Muslim (2537) — wording per al-Bukhari","chapter_en":"Dislike of calling the night prayer “al-‘Atamah.”","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: The Messenger of Allah ﷺ led us one night in the night prayer—the one people call “the late-night prayer.” Then he turned to us and said: “Do you see this night of yours? At the end of one hundred years from it, no one who is on the face of the earth today will remain.”"]},"buhuth":{"en":["Reconciling these narrations","It shows that using the term “the late-night prayer” for the night prayer can be permissible, so the prohibition is for discouragement, not strict forbiddance.","People may be addressed using the terms they commonly recognize.","It can also be a teaching method to guide them away from less suitable wording.","It prevents confusion with the sunset prayer, because “night meal / evening” could sometimes be used for sunset prayer in some usage.","It is also possible that some narrators used that wording to explain what people called it.","Conclusion","The preferred Islamic name for the night prayer is “the night prayer,” so it is better not to replace it with “the late-night prayer.” Even so, using it is not prohibited, because the Prophet ﷺ used it, and the Companions used it after him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (564)، مسلم (2537)، واللفظ للبخاري."},{"num":1844,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَغْلِبَنَّكُمُ الْأَعْرَابُ عَلَى اسْمِ صَلَاتِكُمُ الْمَغْرِبِ قَالَ: الْأَعْرَابُ وَتَقُولُ هِيَ: الْعِشَاءُ."],"takhrij":"صحيح: رواه البخاري في المواقيت (563) عن أبي معمر، (وهو عبدالله بن عمرو) قال: حدثنا عبد الوارث، عن الحسين، قال: حدثنا عبدالله بن بُريدة، قال: حدثنا عبدالله المزني فذكر الحديث.","grade":"صحيح","chapter_ar":"باب كراهية أن يقال للمغرب العِشاءُ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (563)","chapter_en":"Dislike of calling the sunset prayer “the night prayer.”","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["‘Abdullah ibn Mughaffal al-Muzani reported that the Prophet ﷺ said: “Do not let the desert Arabs override you regarding the name of your sunset prayer. The desert Arabs call it ‘the night prayer.’”"]},"buhuth":{"en":["It is disliked to call it “the night prayer” so that it is not confused with the other prayer. But if it is specified by saying “the first night prayer,” then it is not disliked, as appears in authentic usage, such as the phrase “the later night prayer,” reported from Anas: “The Prophet ﷺ delayed the later night prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (563)."},{"num":1845,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ قَالَ: أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَكْرَهُ النَّوْمَ قَبْلَ الْعِشَاءِ وَالْحَدِيثَ بَعْدَهَا."],"takhrij":"متفق عليه: وهو جزء من حديث أبي برزة السابق في باب ما جاء في توقيت الصلوات. رواه البخاري في المواقيت (568-599)، ومسلم في المساجد ومواضع الصلاة (647).","grade":"متفق عليه","chapter_ar":"باب ما يكره من السمر بعد العشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (568) and Muslim (647)","chapter_en":"What is disliked of staying up talking after the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Abu Barzah said: “The Messenger of Allah ﷺ used to dislike sleeping before the night prayer and talking after it.”"]},"buhuth":{"en":["This is part of Abu Barzah’s earlier narration in the chapter on the timing of the prayers."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (568)، ومسلم (647)."},{"num":1846,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: انتَظَرْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ حَتَّى كَانَ شَطْرُ اللَّيْلِ يَبْلُغُهُ، فَجَاءَ فَصَلَّى لَنَا ثُمَّ خَطَبَنَا، فَقَالَ: أَلَا إِنَّ النَّاسَ قَدْ صَلَّوْا ثُمَّ رَقَدُوا، وَإِنَّكُمْ لَمْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمُ الصَّلَاةَ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (600) من طريق قُرة بن خالد، قال: انتظرنا الحسنَ، وراثَ علينا، حتى قَربنا من وقت قيامه، فجاء فقال: دعانا جيرانُنا هؤلاء، ثم قال: قال أنس فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب جواز السمر في الفقه والخير بعد العشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (600), Muslim (640)","chapter_en":"Permissibility of staying up after the night prayer for knowledge and good matters.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["Anas said: We waited for the Prophet ﷺ one night until it was about the middle of the night. He came and led us in prayer, then addressed us and said: “People have prayed and then slept, while you have not ceased to be in prayer as long as you were waiting for the prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (600)، مسلم (640)."},{"num":1847,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنَ عُمَرَ قَالَ: صَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْعِشَاءِ فِي آخِرِ حَيَاتِهِ، فَلَمَّا سَلَّمَ قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَرَأَيْتَكُمْ لَيْلَتَكُمْ هَذِهِ فَإِنَّ رَأْسَ مِائَةٍ لَا يَبْقَى مِمَّنْ هُوَ الْيَوْمَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ، فَوَهِلَ النَّاسُ فِي مَقَالَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى مَا يَتَحَدَّثُونَ مِنْ هَذِهِ الْأَحَادِيثِ عَنْ مِائَةِ سَنَةٍ، وَإِنَّمَا قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَبْقَى مِمَّنْ هُوَ الْيَوْمَ عَلَى ظَهْرِ الْأَرْضِ، يُرِيدُ بِذَلِكَ أَنَّهَا تَخْرِمُ ذَلِكَ الْقَرْنَ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (601)، ومسلم في فضائل الصحابة (2537) كلاهما من حديث الزهري، قال: أخبرني سالم بن عبدالله وأبو بكر بن سليمان، أن عبدالله بن عمر قال، فذكر الحديث، والبخاري رواه أيضاً في كتاب العلم، باب السمر في العلم (116).","grade":"متفق عليه","chapter_ar":"باب جواز السمر في الفقه والخير بعد العشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (601), Muslim (2537)","chapter_en":"Permissibility of staying up after the night prayer for knowledge and good matters.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: The Prophet ﷺ prayed the night prayer near the end of his life. When he finished with the greeting of peace, he stood and said: “Do you see this night of yours? At the end of one hundred years, none of those who are on the face of the earth today will remain.” People became confused by the Prophet’s statement because of other reports they spoke about regarding “one hundred years.” But the Prophet ﷺ said, “none of those who are on the face of the earth today,” meaning that this would mark the end of that generation."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (601)، مسلم (2537)."},{"num":1848,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْمُرُ مَعَ أَبِي بَكْرٍ فِي الْأَمْرِ مِنْ أَمْرِ الْمُسْلِمِينَ وَأَنَا مَعَهُمَا."],"takhrij":"صحيح: رواه الترمذي (169) قال: حدثنا أحمد بن منيع، حدثنا أبو معاوية، عن الأعمش، عن إبراهيم، عن علقمة، عن عمر بن الخطاب فذكر الحديث.","grade":"صحيح","chapter_ar":"باب جواز السمر في الفقه والخير بعد العشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good\nal-Tirmidhi (169) — he said: “Hasan”","chapter_en":"Permissibility of staying up after the night prayer for knowledge and good matters.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["‘Umar ibn al-Khattab said: The Messenger of Allah ﷺ would stay up at night with Abu Bakr discussing matters concerning the Muslims, and I would be with them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9585],"tks":"صحيح: رواه الترمذي (169)، وقال: حسن."},{"num":1849,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَدْرَكَ رَكْعَةً مِنَ الصَّلَاةِ فَقَدْ أَدْرَكَ الصَّلَاةَ."],"takhrij":"متفق عليه: رواه مالك في وقوت الصلاة (15) عن ابن شهاب، عن أبي سلمة بن عبدالرحمن، عن أبي هريرة فذكر الحديث. وعن مالك رواه البخاري في المواقيت (580)، ومسلم في المساجد (607).","grade":"متفق عليه","chapter_ar":"باب من أدرك ركعةً من الصلاة فقد أدرك تلك الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (15), al-Bukhari (580), Muslim (607)","chapter_en":"Whoever catches one unit of a prayer has caught that prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever catches one unit of a prayer has caught the prayer.” In another narration in Muslim: “Whoever catches one unit of the prayer with the imam has caught one unit.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3334],"tks":"متفق عليه: رواه مالك (15)، البخاري (580)، مسلم (607)."},{"num":1850,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَدْرَكَ مِنَ الصُّبْحِ رَكْعَةً قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَ الصُّبْحَ، وَمَنْ أَدْرَكَ رَكْعَةً مِنَ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَ الْعَصْرَ."],"takhrij":"متفق عليه: رواه مالك في وقوت الصلاة (5) عن زيد بن أسْلَم، عن عطاء","grade":"متفق عليه","chapter_ar":"باب من أدرك ركعةً من الصلاة فقد أدرك تلك الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (in the chapter on prayer times, 5), al-Bukhari (579); Muslim (608). Also al-Bukhari (556)","chapter_en":"Whoever catches one unit of a prayer has caught that prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever catches one unit of the dawn prayer before the sun rises has caught the dawn prayer, and whoever catches one unit of the afternoon prayer before the sun sets has caught the afternoon prayer.” Al-Bukhari also narrated with the wording: “If one of you catches a prostration of the afternoon prayer before the sun sets, then let him complete his prayer; and if he catches a prostration of the dawn prayer before the sun rises, then let him complete his prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (5)، والبخاري (579)، ومسلم (608)، ورواه البخاري أيضا (556)."},{"num":1851,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَدْرَكَ مِنَ الْعَصْرِ سَجْدَةً، قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ أَوْ مِنَ الصُّبْحِ، قَبْلَ أَنْ تَطْلُعَ، فَقَدْ أَدْرَكَهَا، وَالسَّجْدَةُ إِنَّمَا هِيَ الرَّكْعَةُ."],"takhrij":"صحيح: رواه مسلم في المساجد (609) من طرق عن يونس، عن ابن شهاب، أنَّ عروة بن الزبير حدَّثه عن عائشة فذكرت مثله.","grade":"صحيح","chapter_ar":"باب من أدرك ركعةً من الصلاة فقد أدرك تلك الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (609)","chapter_en":"Whoever catches one unit of a prayer has caught that prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said: “Whoever catches a prostration of the afternoon prayer before the sun sets, or of the dawn prayer before the sun rises, has caught it.” And “a prostration” here means a full unit of prayer."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (609)."},{"num":1852,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّهُ كَانَ يَقُولُ: كَانَ الْمُسْلِمُونَ حِينَ قَدِمُوا الْمَدِينَةَ يَجْتَمِعُونَ فَيَتَحَيَّنُونَ الصَّلَاةَ لَيْسَ يُنَادَى لَهَا، فَتَكَلَّمُوا يَوْمًا فِي ذَلِكَ، فَقَالَ بَعْضُهُمْ: اتَّخِذُوا نَاقُوسًا مِثْلَ نَاقُوسِ النَّصَارَى، وَقَالَ بَعْضُهُمْ: بَلْ بُوقًا مِثْلَ قَرْنِ الْيَهُودِ، فَقَالَ عُمَرُ: أَوَلَا تَبْعَثُونَ رَجُلًا يُنَادِي بِالصَّلَاةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا بِلَالُ قُمْ فَنَادِ بِالصَّلَاةِ."],"takhrij":"متفق عليه: رواه البخاري في الآذان (604) واللفظ له، ومسلم في الصلاة (377) كلاهما من طريق عبد الرزاق وهو في مصنفه abdrazzaq(1839) قال: أخبرنا ابن جُريج، قال: أخبرني نافع، أن عبدالله بن عمر كان يقول فذكر الحديث، ولم يذكر مسلم بوقاً بل قال: قرْناً مثل قرْن اليهود.","grade":"متفق عليه","chapter_ar":"باب بدء الأذان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (604) — wording his; Muslim (377)","chapter_en":"The beginning of the call to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Umar used to say: When the Muslims arrived in Madinah, they would gather and try to estimate the prayer time, and no call was made for it. One day they discussed this. Some said, “Use a bell like the Christians’ bell,” and others said, “Rather, a horn like the Jews’ horn.” ‘Umar said, “Why not send a man to call out for the prayer?” So the Messenger of Allah ﷺ said: “Bilal, stand and call out for the prayer.”"]},"buhuth":{"en":["His statement “Stand, Bilal, and call out for the prayer” means calling out “Prayer, prayer,” and it is not the later, well-known formula of the call to prayer that ‘Abdullah ibn Zayd saw in the dream."]},"intro_majmu":{"ar":["الأذان: هو بمعنى الإعلام بدخول وقت الصلاة، فهو موجَّه إلى المسلمين لا إلى الله. وبعض غير المسلمين يظنون أنه موجَّه إلى الله، وأن الله لا يسمع إلا إذا نودي بصوت عال، وهذا خطأ. وفي القرآن:","(وَأَذِّنْ فِي النَّاسِ بِالْحَجِّ يَأْتُوكَ رِجَالًا وَعَلَىٰ كُلِّ ضَامِرٍ يَأْتِينَ مِنْ كُلِّ فَجٍّ عَمِيقٍ) [الحج: 27] أي: أعلِن في الناس."],"en":["The call to prayer means making an announcement that the time for prayer has begun. It is directed to Muslims, not to Allah. Some non-Muslims mistakenly think it is directed to Allah, as if Allah only hears when someone calls loudly—this is incorrect. In the Qur’an it says: “And proclaim to the people the pilgrimage; they will come to you on foot and on every lean mount; they will come from every distant pass” (Qur’an 22:27), meaning: make a public announcement to the people."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (604)، واللفظ له، مسلم (377)."},{"num":1853,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: ذَكَرُوا النَّارَ وَالنَّاقُوسَ، فَذَكَرُوا الْيَهُودَ وَالنَّصَارَى: ذَكَرُوا النَّارَ فَأُمِرَ بِلَالٌ أَنْ يَشْفَعَ الْأَذَانَ وَأَنْ يُوتِرَ الْإِقَامَةَ."],"takhrij":"متفق عليه: رواه البخاري في الآذان (603)، ومسلم في الصلاة (378) كلاهما من طريق عبد الوهاب الثقفي، حدثنا خالد الحـذ َّاء، عن أبي قِلابة، عن أنس فذكره واللفظ للبخاري، وفي لفظٍ لهما: وذكروا أن يعلموا وقت الصلاة بشيء يعرفونه، فذكروا أن يوروا – وعند مسلم:أن يُنَوِّروا، ناراً، أو يضربوا ناقوساً. فأُمر بلال أن يشفع الأذان ويُوتر الإقامة.","grade":"متفق عليه","chapter_ar":"باب بدء الأذان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (603) in the chapter on the call to prayer; Muslim (378)","chapter_en":"The beginning of the call to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik said: They mentioned fire and a bell, and they mentioned the Jews and Christians. Then Bilal was ordered to make the call to prayer in repeated phrases, and to make the second call for standing to prayer in single phrases. In another wording: They discussed informing people of prayer time using something they recognized, such as lighting a fire or striking a bell. Then Bilal was ordered to repeat the phrases of the call to prayer, and to say the phrases of the second call in singles. In a narration: “that they should kindle a fire,” meaning: light it and ignite it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (603) في باب الأذان، مسلم (378)."},{"num":1854,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَحْذُورَةَ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَّمَهُ هَذَا الأَذَانَ: اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، ثُمَّ يَعُودُ، فَيَقُولُ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، حَيَّ عَلَى الصَّلَاةِ مَرَّتَيْنِ، حَيَّ عَلَى الْفَلَاحِ مَرَّتَيْنِ، زَادَ إِسْحَاق اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (379) عن أبي غسان المِسْمَعي مالك بن عبد الواحد وإسحاق بن إبراهيم، قال أبو غسَّان: حدثنا مُعاذ: وقال إسحاق: أخبرنا معاذ بن هشام صاحب الدستوائي، وحدثني أبي، عن عامر الأحول، عن مكحول، عن عبدالله بن مُحَيرِيز، عن أبي محذُورة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب بدء الأذان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (379)","chapter_en":"The beginning of the call to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu Mahdhurah reported that the Prophet ﷺ taught him this call to prayer: “Allah is the Greatest, Allah is the Greatest. I testify that there is no god worthy of worship except Allah, I testify that there is no god worthy of worship except Allah. I testify that Muhammad is the Messenger of Allah, I testify that Muhammad is the Messenger of Allah.” Then he repeats and says: “I testify that there is no god worthy of worship except Allah, I testify that there is no god worthy of worship except Allah. I testify that Muhammad is the Messenger of Allah, I testify that Muhammad is the Messenger of Allah. Come to prayer (twice). Come to success (twice).” Ishaq added: “Allah is the Greatest, Allah is the Greatest. There is no god worthy of worship except Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (379)."},{"num":1855,"demo":false,"sanad":"","matn":["عَنْ أَبِي عُمَيْرِ بْنِ أَنَسٍ، عَنْ عُمُومَةٍ لَهُ مِنْ الْأَنْصَارِ، قَالَ: اهْتَمَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلصَّلَاةِ كَيْفَ يَجْمَعُ النَّاسَ لَهَا ؟ فَقِيلَ لَهُ: انْصِبْ رَايَةً عِنْدَ حُضُورِ الصَّلَاةِ فَإِذَا رَأَوْهَا آذَنَ بَعْضُهُمْ بَعْضًا، فَلَمْ يُعْجِبْهُ ذَلِكَ، قَالَ: فَذُكِرَ لَهُ الْقُنْعُ يَعْنِي الشَّبُّورَ، وَقَالَ زِيَادٌ: شَبُّورُ الْيَهُودِ فَلَمْ يُعْجِبْهُ ذَلِكَ، وَقَالَ: هُوَ مِنْ أَمْرِ الْيَهُودِ، قَالَ: فَذُكِرَ لَهُ النَّاقُوسُ، فَقَالَ: هُوَ مِنْ أَمْرِ النَّصَارَى، فَانْصَرَفَ عَبْدُ اللَّهِ بْنُ زَيْدِ بْنِ عَبْدِ رَبِّهِ وَهُوَ مُهْتَمٌّ لِهَمِّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأُرِيَ الْأَذَانَ فِي مَنَامِهِ، قَالَ: فَغَدَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، فَقَالَ لَهُ: يَا رَسُولَ اللَّهِ، إِنِّي لَبَيْنَ نَائِمٍ وَيَقْظَانَ إِذْ أَتَانِي آتٍ فَأَرَانِي الْأَذَانَ، قَالَ: وَكَانَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَدْ رَآهُ قَبْلَ ذَلِكَ فَكَتَمَهُ عِشْرِينَ يَوْمًا، قَالَ: ثُمَّ أَخْبَرَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ: مَا مَنَعَكَ أَنْ تُخْبِرَنِي ؟ فَقَالَ: سَبَقَنِي عَبْدُ اللَّهِ بْنُ زَيْدٍ فَاسْتَحْيَيْتُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا بِلَالُ، قُمْ فَانْظُرْ مَا يَأْمُرُكَ بِهِ عَبْدُ اللَّهِ بْنُ زَيْدٍ فَافْعَلْهُ، قَالَ: فَأَذَّنَ بِلَالٌ، قَالَ أَبُو بِشْرٍ: فَأَخْبَرَنِي أَبُو عُمَيْرٍ أَنَّ الْأَنْصَارَ تَزْعُمُ أَنَّ عَبْدَ اللَّهِ بْنَ زَيْدٍ لَوْلَا أَنَّهُ كَانَ يَوْمَئِذٍ مَرِيضًا لَجَعَلَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُؤَذِّنًا."],"takhrij":"صحيح: رواه أبو داود (498) عن عباد بن موسى الختّلي وزياد بن أيوب، وحديث عباد أتم، قالا: حدثنا هُشُيم، عن أبي بشْر، قال زياد: أخبرنا أبو بشر، عن أبي عمير بن أنس فذكره.","grade":"صحيح","chapter_ar":"باب بدء الأذان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (498)","chapter_en":"The beginning of the call to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu ‘Umayr ibn Anas narrated from paternal uncles of his among the Ansar: The Prophet ﷺ was concerned about the prayer—how to gather the people for it. It was suggested to him: “Raise a flag when the prayer time comes; when they see it, they will inform one another.” But he did not like that. Then a horn was mentioned—meaning a trumpet—and Ziyad said: the Jews’ trumpet; but he did not like that and said: “That is from the practices of the Jews.” Then a bell was mentioned, and he said: “That is from the practices of the Christians.” Then ‘Abdullah ibn Zayd ibn ‘Abd Rabbih left, worried because of the Prophet’s concern, and he was shown the call to prayer in his dream. In the morning he came to the Messenger of Allah ﷺ and informed him, saying: “O Messenger of Allah, I was between sleep and wakefulness when someone came to me and showed me the call to prayer.” ‘Umar ibn al-Khattab (may Allah be pleased with him) had seen it before that, but he kept it to himself for twenty days, then he informed the Prophet ﷺ. The Prophet said to him: “What prevented you from telling me?” He replied: “ ‘Abdullah ibn Zayd preceded me, so I felt shy.” The Messenger of Allah ﷺ then said: “Bilal, stand and see what ‘Abdullah ibn Zayd instructs you, and do it.” So Bilal gave the call to prayer. Abu Bishr said: Abu ‘Umayr told me that the Ansar claimed that if ‘Abdullah ibn Zayd had not been ill that day, the Messenger of Allah ﷺ would have made him the caller to prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (498)."},{"num":1856,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ قَالَ: لَمَّا أَصْبَحْنَا أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ بِالرُّؤْيَا، فَقَالَ: إِنَّ هَذِهِ الرُّؤْيَا حَقٌّ، فَقُمْ مَعَ بِلالٍ، فَإِنَّهُ أَنْدَى أَوْ أَمَدُّ صَوْتًا مِنْكَ، فَأَلْقِ عَلَيْهِ مَا قِيلَ لَكَ، فَيُنَادِي بِذَلِكَ، قَالَ: فَفَعَلْتُ، فَلَمَّا سَمِعَ عُمَرُ بْنُ الْخَطَّابِ نِدَاءَ بِلالٍ بِالصَّلاةِ، خَرَجَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجُرُّ رِدَاءَهُ وَهُوَ يَقُولُ: يَا رَسُولَ اللَّهِ وَالَّذِي بَعَثَكَ بِالْحَقِّ، لَقَدْ رَأَيْتُ مِثْلَ الَّذِي، قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَلِلَّهِ الْحَمْدُ."],"takhrij":"حسن: بهذا السياق رواه ابن خزيمة (363) من طريق سعيد بن يحيى بن سعيد الأموي، عن أبيه، نا محمد بن إسحاق، عن محمد بن إبراهيم بن الحارث، عن محمد بن عبدالله بن زيد، عن أبيه فذكر الحديث.","grade":"حسن","chapter_ar":"باب بدء الأذان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Khuzaymah (363), al-Tirmidhi (189), Abu Dawud (499), Ibn Majah (706)","chapter_en":"The beginning of the call to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["‘Abdullah ibn Zayd said: When morning came, we went to the Messenger of Allah ﷺ and I told him about the dream. He said: “This dream is true. Go with Bilal, for his voice is more resonant— or stronger— than yours. Convey to him what was said to you, and he will call with it.” So I did so. When ‘Umar ibn al-Khattab heard Bilal’s call to prayer, he came out to the Messenger of Allah ﷺ dragging his cloak, saying: “O Messenger of Allah, by the One who sent you with the truth, I saw the same as he said.” The Messenger of Allah ﷺ said: “All praise is for Allah.”"]},"buhuth":{"en":["Adhan wording","“Allah is the Greatest, Allah is the Greatest. Allah is the Greatest, Allah is the Greatest. I testify that there is no god worthy of worship except Allah, I testify that there is no god worthy of worship except Allah. I testify that Muhammad is the Messenger of Allah, I testify that Muhammad is the Messenger of Allah. Come to prayer, come to prayer. Come to success, come to success. Allah is the Greatest, Allah is the Greatest. There is no god worthy of worship except Allah.”","Iqamah wording","“Allah is the Greatest, Allah is the Greatest. I testify that there is no god worthy of worship except Allah. I testify that Muhammad is the Messenger of Allah. Come to prayer. Come to success. The prayer has begun, the prayer has begun. Allah is the Greatest, Allah is the Greatest. There is no god worthy of worship except Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (363)، الترمذي (189)، أبو داود (499)، ابن ماجه (706)."},{"num":1857,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنْ ثَلَاثَةٍ فِي قَرْيَةٍ لَا يُؤَذَّنُ وَلَا تُقَامُ فِيهِمْ الصَّلَاةُ إِلَّا اسْتَحْوَذَ عَلَيْهِمْ الشَّيْطَانُ، فَعَلَيْكَ بِالْجَمَاعَةِ، فَإِنَّ الذِّئْبَ يَأْكُلُ الْقَاصِيَةَ."],"takhrij":"حسن: رواه الإمام أحمد عن وكيع (21710) وعن ابن مهدي (27514) كلاهما عن زائدة بن قدامة، حدثني السائب بن حُبيش الكلاعي، عن معدان بن أبي طلحة اليعمري قال: قال لي أبو الدرداء: أين مسكنك؟ قال: قلت: في قرية دون حِمْص، قال: سمعتُ رسول الله صلى الله عليه وسلم يقول فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في تأكيد الأذان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (21710, 27514), Abu Dawud (547), al-Nasa’i (847)","chapter_en":"Emphasis on establishing the call to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abu al-Darda’ said: I heard the Messenger of Allah ﷺ say: “There are no three people in a village among whom the call to prayer is not given and the prayer is not established except that Satan gains dominance over them. So keep to the congregation, for the wolf eats the one that strays away from the group.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (21710، 27514)، أبو داود (547)، النسائي (847)."},{"num":1858,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا نُودِيَ لِلصَّلَاةِ أَدْبَرَ الشَّيْطَانُ لَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ النِّدَاءَ، فَإِذَا قُضِيَ النِّدَاءُ أَقْبَلَ، حَتَّى إِذَا ثُوِّبَ بِالصَّلَاةِ أَدْبَرَ، حَتَّى إِذَا قُضِيَ التَّثْوِيبُ أَقْبَلَ، حَتَّى يَخْطِرَ بَيْنَ الْمَرْءِ وَنَفْسِهِ يَقُولُ: اذْكُرْ كَذَا اذْكُرْ كَذَا لِمَا لَمْ يَكُنْ يَذْكُرُ، حَتَّى يَظَلَّ الرَّجُلُ إِنْ يَدْرِي كَمْ صَلَّى."],"takhrij":"متفق عليه: رواه مالك في الصلاة (6) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكر الحديث واللفظ له.","grade":"متفق عليه","chapter_ar":"باب رفع الصوت بالنداء وفضل الأذان وهروب الشيطان عند سماعه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (608) and Muslim (389).","chapter_en":"Raising the voice in the call, the virtue of the call to prayer, and Satan fleeing when he hears it","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “When the call to prayer is made, Satan turns away, passing wind so that he does not hear the call. When the call is finished, he comes back. Then when the call for the prayer to begin is made, he turns away again. When that is finished, he returns and comes between a person and his own self, saying: ‘Remember this, remember that,’ things he was not thinking about before, until the man remains not knowing how many units he has prayed.”"]},"buhuth":{"en":["Al-Bukhari narrated it through another route and added at the end: “If one of you does not know whether he prayed three or four, then let him perform two prostrations while seated.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (608)، ومسلم (389)."},{"num":1859,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ أَنَّهُ قَالَ لِعَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَة الْأَنْصَارِيِّ، ثُمَّ الْمَازِنِيِّ: إِنِّي أَرَاكَ تُحِبُّ الْغَنَمَ وَالْبَادِيَةَ، فَإِذَا كُنْتَ فِي غَنَمِكَ أَوْ بَادِيَتِكَ فَأَذَّنْتَ بِالصَّلَاةِ فَارْفَعْ صَوْتَكَ بِالنِّدَاءِ، فَإِنَّهُ لَا يَسْمَعُ مَدَى صَوْتِ الْمُؤَذِّنِ جِنٌّ وَلَا إِنْسٌ وَلَا شَيْءٌ إِلَّا شَهِدَ لَهُ يَوْمَ الْقِيَامَةِ، قَالَ أَبُو سَعِيدٍ: سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: أخرجه مالك في الصلاة (5) عن عبدالرحمن بن عبدالله بن عبدالرحمن بن أبي صَعْصَعَة الأنصاري ثم المازِني، عن أبيه أنه أخبره أن أبا سعيد الخدري قال له، فذكره.","grade":"صحيح","chapter_ar":"باب رفع الصوت بالنداء وفضل الأذان وهروب الشيطان عند سماعه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (5), al-Bukhari (609)","chapter_en":"Raising the voice in the call, the virtue of the call to prayer, and Satan fleeing when he hears it","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said to ‘Abdullah ibn ‘Abd al-Rahman ibn Abi Sa‘sa‘ah al-Ansari, then al-Mazini: “I see that you love sheep and the open countryside. When you are with your sheep or in the countryside and you give the call to prayer, raise your voice in the call, for: ‘Nothing hears the reach of the caller’s voice—no jinn, no human, and nothing at all—except that it will testify for him on the Day of Resurrection.’” Abu Sa‘id said: I heard it from the Messenger of Allah ﷺ."]},"buhuth":{"en":["The phrase “and nothing at all” is like Allah’s saying: “The seven heavens and the earth and whoever is in them glorify Him; there is nothing except that it glorifies Him with praise, but you do not understand their glorification. Indeed, He is Most Forbearing, Most Forgiving.” (Qur’an 17:44)","It is explained explicitly in a narration reported by Ibn Majah (723) and Ibn Khuzaymah (389): “No jinn, no human, no tree, and no stone hears it except that it will testify for him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8229,16211],"tks":"صحيح: رواه مالك (5)، البخاري (609)."},{"num":1860,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ الشَّيْطَانَ إِذَا سَمِعَ النِّدَاءَ بِالصَّلَاةِ، ذَهَبَ حَتَّى يَكُونَ مَكَانَ الرَّوْحَاءِ.","قَالَ سُلَيْمَانُ: فَسَأَلْتُهُ عَنِ الرَّوْحَاءِ ؟ فَقَالَ: هِيَ مِنَ الْمَدِينَةِ، سِتَّةٌ وَثَلَاثُونَ مِيلًا."],"takhrij":"صحيح: رواه مسلم في الصلاة (388) من طريق الأعمش، عن أبي سفيان، عن جابر فذكر مثله.","grade":"صحيح","chapter_ar":"باب رفع الصوت بالنداء وفضل الأذان وهروب الشيطان عند سماعه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (388), in the Book of Prayer","chapter_en":"Raising the voice in the call, the virtue of the call to prayer, and Satan fleeing when he hears it","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Jabir said: I heard the Prophet ﷺ say: “When Satan hears the call to prayer, he goes away until he reaches the place called al-Rawha’.” Sulayman said: I asked him about al-Rawha’, and he said: “It is thirty-six miles from Madinah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (388) في كتاب الصلاة."},{"num":1861,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْمُؤَذِّنُونَ أَطْوَلُ النَّاسِ أَعْنَاقًا يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (387) من طريق طلحة بن يحيى، عن عمه قال: كنت عند معاوية بن أبي سفيان، فجاءه المؤذن يدعوه إلى الصلاة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل المؤذّن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (387), in the Book of Prayer","chapter_en":"What has been narrated about the virtue of the caller to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Mu‘awiyah ibn Abi Sufyan said: I heard the Messenger of Allah ﷺ say: “The callers to prayer will have the longest necks on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (387) في كتاب الصلاة."},{"num":1862,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمُؤَذِّنُونَ أَطْوَلُ النَّاسِ أَعْنَاقًا يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه ابن حبان في صحيحه (1670) عن عبد الرزاق، قال: أخبرنا معمر، عن منصور، عن عباد بن أُنيس، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في فضل المؤذّن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Hibban (1670)","chapter_en":"What has been narrated about the virtue of the caller to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The callers to prayer will have the longest necks on the Day of Resurrection.”"]},"buhuth":{"en":["The phrase “the longest necks” has been explained in more than one way. One strong meaning is: the caller to prayer is a reason people establish the prayer on time, so everyone who responds and prays at the known times gives the caller to prayer a share of reward without decreasing their reward at all. Thus, on the Day of Resurrection the callers to prayer will be seen with heads held high, as if from the “length of their necks.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (1670)."},{"num":1863,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْمُؤَذِّنُ يُغْفَرُ لَهُ مَدَى صَوْتِهِ وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ، وَشَاهِدُ الصَّلَاةِ يُكْتَبُ لَهُ خَمْسٌ وَعِشْرُونَ صَلَاةً وَيُكَفَّرُ عَنْهُ مَا بَيْنَهُمَا."],"takhrij":"حسن: رواه أبوداود (515) واللفظ له، والنسائي (645)، وابن ماجه (724). كلهم من حديث شعبة عن موسى بن أبي عثمان، عن أبي يحيى فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل المؤذّن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (515 — wording his), al-Nasa’i (645), Ibn Majah (724)","chapter_en":"What has been narrated about the virtue of the caller to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The caller to prayer is forgiven to the extent of his voice, and everything moist and dry testifies for him. The one who attends the congregational prayer has twenty-five prayers written for him, and what is between them is erased for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (515، واللفظ له)، النسائي (645)، ابن ماجه (724)."},{"num":1864,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَغْفِرُ اللَّهُ لِلْمُؤَذِّنِ مَدَّ صَوْتِهِ، وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ سَمِعَ صَوْتَهُ."],"takhrij":"حسن: رواه الإمام أحمد (6201) قال: حدثنا أبو الجوَّاب، حدثنا عمارُ بن رُزيق، عن الأعمش، عن مجاهد، عن ابن عمر فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في فضل المؤذّن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (6201)","chapter_en":"What has been narrated about the virtue of the caller to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said: “Allah forgives the caller to prayer to the extent of his voice, and everything moist and dry that hears his voice testifies for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6201)."},{"num":1865,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَذَّنَ اثْنَتَيْ عَشْرَةَ سَنَةً، وَجَبَتْ لَهُ الْجَنَّةُ، وَكُتِبَ لَهُ بِكُلِّ أَذَانٍ سِتُّونَ حَسَنَةً وَبِكُلِّ إِقَامَةٍ ثَلاثُونَ حَسَنَةً."],"takhrij":"حسن: رواه الدارقطني (929)، والحاكم (742) كلاهما من طرق عن عبد الله بن وهب، أخبرني ابنُ لهيعة، عن عبيد الله بن أبي جعفر، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل المؤذّن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Daraqutni (929), Ibn Majah (728), al-Hakim (737)","chapter_en":"What has been narrated about the virtue of the caller to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Ibn ‘Umar reported that the Prophet ﷺ said: “Whoever gives the call to prayer for twelve years, Paradise becomes guaranteed for him. For every call to prayer, sixty good deeds are written for him, and for every call to begin the prayer, thirty good deeds are written for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني (929)، ابن ماجه (728)، الحاكم (742)."},{"num":1866,"demo":false,"sanad":"","matn":["عَنِ امْرَأَةٍ مِنْ بَنِي النَّجَّارِ، قَالَتْ: كَانَ بَيْتِي مِنْ أَطْوَلِ بَيْتٍ حَوْلَ الْمَسْجِدِ وَكَانَ بِلَالٌ يُؤَذِّنُ عَلَيْهِ الْفَجْرَ، فَيَأْتِي بِسَحَرٍ فَيَجْلِسُ عَلَى الْبَيْتِ يَنْظُرُ إِلَى الْفَجْرِ، فَإِذَا رَآهُ تَمَطَّى، ثُمَّ قَالَ: اللَّهُمَّ إِنِّي أَحْمَدُكَ وَأَسْتَعِينُكَ عَلَى قُرَيْشٍ أَنْ يُقِيمُوا دِينَكَ، قَالَتْ: ثُمَّ يُؤَذِّنُ، قَالَتْ: وَاللَّهِ مَا عَلِمْتُهُ كَانَ تَرَكَهَا لَيْلَةً وَاحِدَةً تَعْنِي هَذِهِ الْكَلِمَاتِ."],"takhrij":"حسن: رواه أبو داود (519) قال: حدثنا أحمد بن محمد بن أيوب، حدثنا إبراهيم بن سعد، عن محمد بن إسحاق، عن محمد بن جعفر بن الزبير، عن عروة بن الزبير، عن امرأة من بني النجار فذكرت الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في الأذان فوق المنار","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (519)","chapter_en":"The call to prayer from an elevated place","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["A woman from Banu al-Najjar said: My house was among the tallest houses around the mosque, and Bilal used to give the dawn call to prayer from it. He would come in the pre-dawn time and sit on the house watching for dawn. When he saw it, he would stretch, then say: “O Allah, I praise You and I seek Your help against Quraysh, that they establish Your religion.” Then he would give the call. She said: By Allah, I never knew him to leave these words even for a single night."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (519)."},{"num":1867,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَحْذُورَةَ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَّمَهُ هَذَا الأَذَانَ: اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، ثُمَّ يَعُودُ، فَيَقُولُ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، حَيَّ عَلَى الصَّلَاةِ مَرَّتَيْنِ، حَيَّ عَلَى الْفَلَاحِ مَرَّتَيْنِ، زَادَ إِسْحَاق اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ.","وَفِي بَعْضِ رِوَايَاتِ مُسْلِمٍ: عَلَّمَهُ الْأَذَانَ تِسْعَ عَشْرَةَ كَلِمَةً – يَعْنِي تَكْرَارَ اللَّهُ أَكْبَرُ أَرْبَعَ مَرَّاتٍ.","كَمَا فِي لَفْظِ أَبِي دَاوُد: قُلْ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ (مَرَّتَيْنِ مَرَّتَيْنِ) ثُمَّ قَالَ: ارْجِعْ فَامْدُدْ صَوْتَكَ، ثُمَّ قَالَ: قُلْ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ، حَيَّ عَلَى الْفَلَاحِ، اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (379) كما سبق عن أبي غسان، ثنا معاذ بن هشام، عن أبيه، عن عامر الأحول، عن مكحول، عن عبدالله بن محيريز، عن أبي محذورة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الترجيع في الأذان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (379).","chapter_en":"What has been narrated about “tarji‘” in the call to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Abū Maḥdhūrah reported that the Messenger of Allah ﷺ taught him this adhān: “Allah is the Greatest, Allah is the Greatest. I testify that there is no deity worthy of worship except Allah. I testify that there is no deity worthy of worship except Allah. I testify that Muḥammad is the Messenger of Allah. I testify that Muḥammad is the Messenger of Allah.”","Then he repeats: “I testify that there is no deity worthy of worship except Allah. I testify that there is no deity worthy of worship except Allah. I testify that Muḥammad is the Messenger of Allah. I testify that Muḥammad is the Messenger of Allah. Come to prayer,” twice, and, “Come to success,” twice.","Isḥāq added: “Allah is the Greatest, Allah is the Greatest. There is no deity worthy of worship except Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (379)."},{"num":1868,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَحْذُورَةَ قَالَ: كُنْتُ أُؤَذِّنُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكُنْتُ أَقُولُ فِي أَذَانِ الْفَجْرِ الْأَوَّلِ: حَيَّ عَلَى الْفَلَاحِ، الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"حسن: رواه النسائي (647) قال: أخبرنا سويد بن نصر، ثنا عبدالله، عن سفيان، عن أبي جعفر، عن أبي سلمان، عن أبي محذورة، قال فذكر الحديث.","grade":"حسن","chapter_ar":"باب في قول المؤذن في صلاة الصبح: «الصلاة خير من النوم»","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (647)","chapter_en":"The caller’s phrase in the dawn prayer: “Prayer is better than sleep.”","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Abu Mahdhurah said: I used to give the call to prayer for the Messenger of Allah ﷺ, and in the first dawn call I would say: “Come to success. Prayer is better than sleep, prayer is better than sleep. Allah is the Greatest, Allah is the Greatest. There is no god worthy of worship except Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (647)."},{"num":1869,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: مِنَ السُّنَّةِ إِذَا قَالَ الْمُؤَذِّنُ فِي أَذَانِ الْفَجْرِ: حِيَّ عَلَى الْفَلَاحِ قَالَ: الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ...(فَذَكَرَ الْحَدِيثَ)."],"takhrij":"صحيح: رواه الدارقطني (944) ومن طريقه البيهقي (1984) عن الحسين بن إسماعيل، ثنا محمد بن عثمان بن كرامة، ثنا أبو أسامة، ثنا ابن عون، عن محمد (ابن سيرين) عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب في قول المؤذن في صلاة الصبح: «الصلاة خير من النوم»","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Daraqutni (1/243), al-Bayhaqi (1/423)","chapter_en":"The caller’s phrase in the dawn prayer: “Prayer is better than sleep.”","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Anas said: “From the Sunnah is that when the caller says in the dawn call: ‘Come to success,’ he says: ‘Prayer is better than sleep, prayer is better than sleep.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الدارقطني (944)، البيهقي (1984)."},{"num":1870,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: أُمِرَ بِلَالٌ أَنْ يَشْفَعَ الْأَذَانَ وَأَنْ يُوتِرَ الْإِقَامَةَ، إِلَّا الْإِقَامَةَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (605) ومسلم في الصلاة (378) كلاهما من طريق أيوب، عن أبي قلابة، عن أنس فذكره، وبعض طرق الحديث مضى في بدء الأذان.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تثنية الأذان وإفراد الإقامة وأن من أذّن فهو يقيم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (605), Muslim (378)","chapter_en":"Repeating the call to prayer, making the second call single, and that whoever calls also makes the second call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Anas said: Bilal was ordered to repeat the phrases of the call to prayer, and to make the phrases of the call to begin the prayer single."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (605)، مسلم (378)."},{"num":1871,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: إِنَّمَا كَانَ الْأَذَانُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّتَيْنِ مَرَّتَيْنِ، وَالْإِقَامَةُ مَرَّةً مَرَّةً، غَيْرَ أَنَّهُ، يَقُولُ: قَدْ قَامَتِ الصَّلَاةُ، قَدْ قَامَتِ الصَّلَاةُ، فَإِذَا سَمِعْنَا الْإِقَامَةَ تَوَضَّأْنَا ثُمَّ خَرَجْنَا إِلَى الصَّلَاةِ."],"takhrij":"حسن: رواه أبو داود (510)، والنسائي (628) كلاهما من حديث شعبة، قال: سمعتُ أبا جعفر يحدث عن مسلم أبي المثنى، عن ابن عمر فذكر الحديث، وصححه ابن خزيمة (374).","grade":"حسن","chapter_ar":"باب ما جاء في تثنية الأذان وإفراد الإقامة وأن من أذّن فهو يقيم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (510), al-Nasa’i (628), and Ibn Khuzaymah authenticated it (374)","chapter_en":"Repeating the call to prayer, making the second call single, and that whoever calls also makes the second call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: The call to prayer at the time of the Messenger of Allah ﷺ was in pairs—each phrase said twice—while the call to begin the prayer was said once—each phrase said once—except that the phrase “The prayer has begun” was said twice. When we heard the call to begin the prayer, we would perform ablution and then go out to the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (510)، النسائي (628)، وصححه ابن خزيمة (374)."},{"num":1872,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ بِلَالًا يُؤَذِّنُ بِلَيْلٍ، فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ابْنُ أُمِّ مَكْتُومٍ، ثُمَّ قَالَ: وَكَانَ رَجُلًا أَعْمَى لَا يُنَادِي حَتَّى يُقَالَ لَهُ أَصْبَحْتَ أَصْبَحْتَ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (14) عن عبدالله بن دينار، عن ابن عمر فذكر الحديث. ورواه أيضاً malik(15) عن ابن شهاب، عن سالم بن عبدالله مرسلاً.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأذان قبل الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (14), al-Bukhari (617), Muslim (1092)","chapter_en":"What has been narrated about calling before dawn","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar reported that the Messenger of Allah ﷺ said: “Bilal gives the call during the night, so eat and drink until Ibn Umm Maktum calls.” Then he said: He was a blind man, and he would not call until it was said to him, “Morning has come, morning has come.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4361],"tks":"متفق عليه: رواه مالك (14)، البخاري (617)، مسلم (1092)."},{"num":1873,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَمْنَعَنَّ أَحَدَكُمْ أَوْ أَحَدًا مِنْكُمْ أَذَانُ بِلَالٍ مِنْ سَحُورِهِ، فَإِنَّهُ يُؤَذِّنُ أَوْ يُنَادِي بِلَيْلٍ لِيَرْجِعَ قَائِمَكُمْ وَلِيُنَبِّهَ نَائِمَكُمْ، وَلَيْسَ أَنْ يَقُولَ الْفَجْرُ أَوِ الصُّبْحُ، وَقَالَ: بأَصَابِعِهِ وَرَفَعَهَا إِلَى فَوْقُ وَطَأْطَأَ إِلَى أَسْفَلُ حَتَّى يَقُولَ هَكَذَا.","وَقَالَ زُهَيْرٌ (وَهُوَ ابْنُ مُعَاوِيَةَ الْجُعْفِىُّ) بِسَبَّابَتَيْهِ إِحْدَاهُمَا فَوْقَ الْأُخْرَى ثُمَّ مَدَّهَا عَنْ يَمِينِهِ وَشِمَالِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (621)، ومسلم في الصيام (1093) كلاهما من طريق سليمان التيمي، عن أبي عثمان النهدي، عن عبدالله بن مسعود فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأذان قبل الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (621), Muslim (1093)","chapter_en":"What has been narrated about calling before dawn","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Ibn Mas‘ud reported that the Prophet ﷺ said: “Let not Bilal’s call prevent any of you— or any among you— from taking his pre-dawn meal. He calls— or announces— during the night so that the one praying at night may return (and stop), and the sleeper may wake up. The true dawn is not the one that rises vertically like this; rather, it is the one that spreads out like this.” He gestured with his fingers, raising them upward and lowering them, then Zuhayr (that is, Ibn Mu‘awiyah al-Ju‘fi) said: He placed his two index fingers one above the other and then spread them to the right and left."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (621)، مسلم (1093)."},{"num":1874,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: إِنَّ بِلَالًا يُؤَذِّنُ بِلَيْلٍ، فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ابْنُ أُمِّ مَكْتُومٍ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (622) عن إسحاق قال: أخبرنا أبو أسامة قال: عبيدالله حدثنا، عن القاسم بن محمد، عن عائشة فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأذان قبل الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (622), Muslim (1092)","chapter_en":"What has been narrated about calling before dawn","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ said: “Bilal calls during the night, so eat and drink until Ibn Umm Maktum gives the call.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (622)، مسلم (1092)."},{"num":1875,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ ابْنَ أُمِّ مَكْتُومٍ يُؤَذِّنُ بِلَيْلٍ، فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ بِلالٌ، فَإِنَّ بِلالا لا يُؤَذِّنُ حَتَّى يَرَى الْفَجْرَ."],"takhrij":"صحيح: أخرجه ابن خزيمة (406) من طريق عبد العزيز، يعني ابن محمد، (الدراوردي) عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في الأذان قبل الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Khuzaymah (406)","chapter_en":"What has been narrated about calling before dawn","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah reported that the Messenger of Allah ﷺ said: “Ibn Umm Maktum calls during the night, so eat and drink until Bilal calls, for Bilal does not call until he sees the dawn.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (406)."},{"num":1876,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ يَقُولُ: سَمِعْتُ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: لَا يَغُرَّنَّ أَحَدَكُمْ نِدَاءُ بِلَالٍ مِنَ السَّحُورِ، وَلَا هَذَا الْبَيَاضُ حَتَّى يَسْتَطِيرَ.","وَفِي رِوَايَةِ: لَا يَمْنَعَنَّكُمْ مِنْ سُحُورِكُمْ أَذَانُ بِلَالٍ وَلَا الْفَجْرُ الْمُسْتَطِيلُ، وَلَكِنْ الْفَجْرُ الْمُسْتَطِيرُ فِي الْأُفُقِ."],"takhrij":"صحيح: الرواية الأولى أخرجها مسلم في الصيام (1094) من طرق عن عبدالله بن سوادة القشيري، عن أبيه، عن سمرة بن جندب، وفي رواية شعبة، عن سوادة به بلفظ: لا يغرنكم نداءُ بلال، ولا هذا البياض حتى يبدوَ الفجرُ، أو قال: حتى ينفجر الفجر.","grade":"صحيح","chapter_ar":"باب ما جاء في الأذان قبل الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (1094) for the first wording; al-Tirmidhi (706) for the second. Abu Dawud (2346) has a close wording.","chapter_en":"What has been narrated about calling before dawn","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Samurah ibn Jundub said: I heard the Messenger of Allah ﷺ say: “Let not Bilal’s call deceive any of you regarding the pre-dawn meal, nor this whiteness, until it spreads out.” In another narration: “Let neither Bilal’s call prevent you from your pre-dawn meal, nor the vertical dawn, but rather the true dawn is the one that spreads across the horizon.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1094) للفظ الأول، والترمذي (706) للفظ الثاني، ولأبي داود (2346) لفظ قريب."},{"num":1877,"demo":false,"sanad":"","matn":["عَنْ أُنَيْسَةَ بِنْتِ خُبَيْبٍ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَذَّنَ ابْنُ أُمِّ مَكْتُومٍ فَكُلُوا وَاشْرَبُوا، وَإِذَا أَذَّنَ بِلالٌ فَلا تَأْكُلُوا وَلا تَشْرَبُوا، فَإِنْ كَانَتِ الْمَرْأَةُ مِنَّا لَيَبْقَى عَلَيْهَا شَيْءٌ مِنْ سُحُورِهَا، فَتَقُولُ لِبِلالٍ: أَمْهِلْ حَتَّى أَفْرَغَ مِنْ سُحُورِي."],"takhrij":"صحيح: رواه النسائي (640) قال: أخبرنا يعقوب بن إبراهيم، عن هُشيم، قال: أخبرنا منصور، يعني ابن زاذان، عن خُبَيب بن عبدالرحمن، عن عمته أُنَيسة بنت خُبيب فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في الأذان قبل الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (640), Ahmad (27440), and Ibn Khuzaymah authenticated it (404)","chapter_en":"What has been narrated about calling before dawn","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Unaysah bint Khubayb said: The Messenger of Allah ﷺ said: “When Ibn Umm Maktum gives the call, then eat and drink; and when Bilal gives the call, then do not eat or drink.” If one of the women still had something left of her pre-dawn meal, she would say to Bilal: “Wait until I finish my pre-dawn meal.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (640)، أحمد (27440)، وصححه ابن خزيمة (404)."},{"num":1878,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَفَرٍ مِنْ قَوْمِي، فَأَقَمْنَا عِنْدَهُ عِشْرِينَ لَيْلَةً وَكَانَ رَحِيمًا رَفِيقًا، فَلَمَّا رَأَى شَوْقَنَا إِلَى أَهَالِينَا قَالَ: ارْجِعُوا فَكُونُوا فِيهِمْ وَعَلِّمُوهُمْ وَصَلُّوا، فَإِذَا حَضَرَتِ الصَّلَاةُ فَلْيُؤَذِّنْ لَكُمْ أَحَدُكُمْ وَلْيَؤُمَّكُمْ أَكْبَرُكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (628)، ومسلم في المساجد (674) كلاهما من طريق أيوب، عن أبي قلابة، عن مالك بن الحويرث فذكر الحديث واللفظ للبخاري، وفي لفظ آخر قال: وصَلُّوا كما رأيتُموني أصَلِّي، فإذا حضرت الصلاة فليؤذن لكم أحدكم وليؤمكم أكبركم البخاري (631).","grade":"متفق عليه","chapter_ar":"باب الأذان في السفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (628) — wording his; Muslim (674). Also in al-Bukhari (631) with a similar wording.","chapter_en":"The call to prayer while traveling","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Malik ibn al-Huwayrith said: I came to the Prophet ﷺ with a group from my people, and we stayed with him for twenty nights. He was merciful and gentle. When he saw our longing for our families, he said: “Go back and remain among them, teach them, and pray as you have seen me pray. When the time for prayer comes, let one of you give the call to prayer, and let the eldest among you lead you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (628) واللفظ له، ومسلم (674)، ورواه البخاري أيضا (631) بلفظ قريب."},{"num":1879,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ قَالَ: سِرْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً، فَقَالَ بَعْضُ الْقَوْمِ: لَوْ عَرَّسْتَ بِنَا يَا رَسُولَ اللَّهِ، قَالَ: أَخَافُ أَنْ تَنَامُوا عَنِ الصَّلَاةِ، قَالَ بِلَالٌ: أَنَا أُوقِظُكُمْ، فَاضْطَجَعُوا وَأَسْنَدَ بِلَالٌ ظَهْرَهُ إِلَى رَاحِلَتِهِ فَغَلَبَتْهُ عَيْنَاهُ فَنَامَ، فَاسْتَيْقَظَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ طَلَعَ حَاجِبُ الشَّمْسِ، فَقَالَ: يَا بِلَالُ، أَيْنَ مَا قُلْتَ ؟ قَالَ: مَا أُلْقِيَتْ عَلَيَّ نَوْمَةٌ مِثْلُهَا قَطُّ، قَالَ: إِنَّ اللَّهَ قَبَضَ أَرْوَاحَكُمْ حِينَ شَاءَ وَرَدَّهَا عَلَيْكُمْ حِينَ شَاءَ يَا بِلَالُ، قُمْ فَأَذِّنْ بِالنَّاسِ بِالصَّلَاةِ فَتَوَضَّأَ، فَلَمَّا ارْتَفَعَتِ الشَّمْسُ وَابْيَاضَّتْ قَامَ فَصَلَّى."],"takhrij":"متفق عليه: البخاري في المواقيت (595) وبوَّب عليه بقوله: الأذان بعد ذهاب الوقت، واللفظ له، ومسلم في المساجد (681) مفصلاً وفيه: ثم أذَّن بلال بالصـــــــلاة، فصلى رسول الله صلى الله عليه وسلم ركعتين، ثم صلى الغداةَ فصنع كما يصنع كل يوم، كلاهما من أوجه عن أبي قتادة.","grade":"متفق عليه","chapter_ar":"باب الأذان للفائتة والإقامة لها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (595) — wording his; Muslim (681) with a fuller version, including that Bilal gave the call, the Prophet prayed two units, then prayed the dawn prayer as he normally did each day.","chapter_en":"The call to prayer and the call to begin the prayer for a missed prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Abu Qatadah said: We traveled with the Prophet ﷺ one night. Some of the people said, “If only you would let us stop and rest, O Messenger of Allah ﷺ.” He said: “I fear you may sleep through the prayer.” Bilal said: “I will wake you.” So they lay down, and Bilal leaned his back against his mount, but his eyes overcame him and he fell asleep. The Prophet ﷺ woke up when the edge of the sun had appeared and said: “Bilal, where is what you said?” Bilal replied: “Never has a sleep overcome me like this before.” He said: “Allah took your souls when He willed and returned them to you when He willed. Bilal, stand and call the people to prayer.” Then he performed ablution, and when the sun had risen and become bright, he stood and prayed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (595) واللفظ له، ومسلم (681) بلفظ أطول، وفيه أن بلالا أذن، وصلى النبي ﷺ ركعتين، ثم صلى الصبح كما كان يصليها كل يوم."},{"num":1880,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، فِي هَذَا الْخَبَرِ، يَعْنِي قِصَّةَ التَّعْرِيس،  قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَحَوَّلُوا عَنْ مَكَانِكُمُ الَّذِي أَصَابَتْكُمْ فِيهِ الْغَفْلَةُ، قَالَ: فَأَمَرَ بِلَالًا، فَأَذَّنَ وَأَقَامَ وَصَلَّى."],"takhrij":"صحيح: رواه أبو داود (436) عن موسى بن إسماعيل، ثنا أبان، ثنا معمر، عن الزهري، عن سعيد بن المسيب، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الأذان للفائتة والإقامة لها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (436)","chapter_en":"The call to prayer and the call to begin the prayer for a missed prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah, in this report—meaning the story of stopping to rest—said: The Messenger of Allah ﷺ said: “Move away from this place where heedlessness overcame you.” Then he ordered Bilal to give the call and to begin the prayer, and he prayed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (436)."},{"num":1881,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ: شَغَلَنَا الْمُشْرِكُونَ يَوْمَ الْخَنْدَقِ عَنْ صَلَاةِ الظُّهْرِ حَتَّى غَرَبَتِ الشَّمْسُ، وَذَلِكَ قَبْلَ أَنْ يَنْزِلَ فِي الْقِتَالِ مَا نَزَلَ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: ﴿وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ﴾ [ سورة الأحزاب: 25] فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلَالًا فَأَقَامَ لِصَلَاةِ الظُّهْرِ فَصَلَّاهَا كَمَا كَانَ يُصَلِّيهَا لِوَقْتِهَا، ثُمَّ أَقَامَ لِلْعَصْرِ فَصَلَّاهَا كَمَا كَانَ يُصَلِّيهَا لِوَقْتِهَا، ثُمَّ أَذَّنَ لِلْمَغْرِبِ فَصَلَّاهَا كَمَا كَانَ يُصَلِّيهَا لِوَقْتِهَا."],"takhrij":"صحيح: رواه النسائي (661) عن عمرو بن علي، قال: حدثنا يحيى (يعني ابن سعيد القطان) قال: حدثنا ابن أبي ذئب، قال: حدثنا سعيد بن أبي سعيد، عن عبدالرحمن بن أبي سعيد، عن أبيه فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الأذان للفائتة والإقامة لها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (661)","chapter_en":"The call to prayer and the call to begin the prayer for a missed prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Abu Sa‘id said: On the Day of the Trench, the polytheists kept us so occupied that we missed the noon prayer until the sun set. This was before what was later revealed regarding fighting was revealed. Then Allah, Mighty and Majestic, revealed: “And Allah sufficed the believers in battle” (Qur’an 33:25). So the Messenger of Allah ﷺ ordered Bilal to begin the prayer for noon, and he prayed it as he would pray it at its proper time. Then he began the prayer for afternoon, and he prayed it as he would pray it at its proper time. Then he gave the call to prayer for sunset, and he prayed it as he would pray it at its proper time."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (661)."},{"num":1882,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي مَسِيرٍ لَهُ فَنَامُوا عَنْ صَلَاةِ الْفَجْرِ، فَاسْتَيْقَظُوا بِحَرِّ الشَّمْسِ، فَارْتَفَعُوا قَلِيلًا حَتَّى اسْتَقَلَّتِ الشَّمْسُ ثُمَّ أَمَرَ مُؤَذِّنًا فَأَذَّنَ فَصَلَّى رَكْعَتَيْنِ قَبْلَ الْفَجْرِ ثُمَّ أَقَامَ ثُمَّ صَلَّى الْفَجْرَ."],"takhrij":"صحيح: رواه أبو داود (443) قال: حدثنا وهب بن بقية، عن خالد، عن يونس بن عبيد، عن الحسن، عن عمران بن حصين فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الأذان للفائتة والإقامة لها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (443)","chapter_en":"The call to prayer and the call to begin the prayer for a missed prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["‘Imran ibn Husayn said: The Messenger of Allah ﷺ was on a journey and they slept through the dawn prayer. They woke up from the heat of the sun, so they moved a short distance until the sun had risen. Then he ordered a caller to give the call to prayer, so he prayed the two rakʿahs before the obligatory Fajr prayer, then the call to begin the prayer was made, and then he prayed the Fajr prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (443)."},{"num":1883,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ فَنَامَ عَنِ الصُّبْحِ، حَتَّى طَلَعَتِ الشَّمْسُ فَاسْتَيْقَظَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: تَنَحَّوْا عَنْ هَذَا الْمَكَانِ، قَالَ: ثُمَّ أَمَرَ بِلَالًا فَأَذَّنَ ثُمَّ تَوَضَّئُوا وَصَلَّوْا رَكْعَتَيِ الْفَجْرِ، ثُمَّ أَمَرَ بِلَالًا فَأَقَامَ الصَّلَاةَ فَصَلَّى بِهِمْ صَلَاةَ الصُّبْحِ."],"takhrij":"حسن: رواه أبو داود (444) قال: حدثنا عباس العنبري ح وحدثنا أحمد ابن صالح، وهذا لفظ عباس، أن عبدالله بن يزيد حدَّثهم عن حَيَّوة بن شريح، عن عيَّاش بن عباس، يعني القتباني، أن كليب بن صُبح حدَّثهم أن الزِبرقان حدَّثه عن عمه عمرو بن أميه الضمري فذكر الحديث.","grade":"حسن","chapter_ar":"باب الأذان للفائتة والإقامة لها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (444)","chapter_en":"The call to prayer and the call to begin the prayer for a missed prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["‘Amr ibn Umayyah al-Damri said: We were with the Messenger of Allah ﷺ on one of his journeys, and we slept through the dawn prayer until the sun rose. The Messenger of Allah ﷺ woke up and said: “Move away from this place.” Then he ordered Bilal to give the call to prayer. They performed ablution and prayed the two units of dawn, then he ordered Bilal to make the call to begin the prayer, and he led them in the dawn prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (444)."},{"num":1884,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَمَنَ الْحُدَيْبِيَةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ يَكْلَؤُنَا، فَقَالَ بِلَالٌ: أَنَا، فَنَامُوا حَتَّى طَلَعَتِ الشَّمْسُ، فَاسْتَيْقَظَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: افْعَلُوا كَمَا كُنْتُمْ تَفْعَلُونَ، قَالَ: فَفَعَلْنَا، قَالَ: فَكَذَلِكَ فَافْعَلُوا لِمَنْ نَامَ أَوْ نَسِيَ."],"takhrij":"صحيح: رواه أبو داود (447) عن محمد بن المثنى، حدثنا محمد بن جعفر، ثنا شعبة، عن جامع بن شداد، سمعت عبدالرحمن بن أبي علقمة، سمعتُ عبدالله بن مسعود فذكر الحديث،","grade":"صحيح","chapter_ar":"باب الأذان للفائتة والإقامة لها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (447)","chapter_en":"The call to prayer and the call to begin the prayer for a missed prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: We were traveling with the Messenger of Allah ﷺ around the time of al-Hudaybiyah, and the Messenger of Allah ﷺ said: “Who will keep watch over us?” Bilal said: “I will.” But they slept until the sun rose. The Prophet ﷺ woke up and said: “Do as you used to do.” So we did so. Then he said: “Do likewise for the one who sleeps or forgets.”"]},"buhuth":{"en":["His statement “Do as you used to do” means: pray as you would at the proper time—perform ablution, give the call to prayer, make the call to begin the prayer, and then pray."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (447)."},{"num":1885,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يُغِيرُ إِذَا طَلَعَ الْفَجْرُ، وَكَانَ يَسْتَمِعُ الأَذَانَ، فَإِنْ سَمِعَ أَذَانًا أَمْسَكَ وَإِلَّا أَغَارَ، فَسَمِعَ رَجُلًا يَقُولُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَلَى الْفِطْرَةِ، ثُمَّ قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَرَجْتَ مِنَ النَّارِ فَنَظَرُوا، فَإِذَا هُوَ رَاعِي مِعْزًى."],"takhrij":"متفق عليه: رواه مسلم في الصلاة (382) من طريق حماد بن سلمة، ثنا ثابت، عن أنس بن مالك فذكر الحديث، ورواه البخاري في الجهاد (2943) من وجه آخر عن أنس بن مالك مختصرا.","grade":"متفق عليه","chapter_ar":"باب استحباب الأذان لمن يصلي وحده","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (382)","chapter_en":"Recommendation of giving the call to prayer for one who prays alone","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ would launch a raid when dawn appeared, and he would listen for the call to prayer. If he heard a call, he would refrain; if not, he would proceed. He heard a man saying, “Allah is the Greatest, Allah is the Greatest,” so the Messenger of Allah ﷺ said: “Upon the natural religion.” Then the man said: “I testify that there is no god worthy of worship except Allah, I testify that there is no god worthy of worship except Allah,” and the Messenger of Allah ﷺ said: “You have escaped the Fire.” They looked and found that he was a shepherd of goats."]},"buhuth":{"en":["“Upon the natural religion” means: upon Islam. “You have escaped the Fire” means: because of affirming pure monotheism. As for “they found he was a shepherd of goats,” al-Nawawi said: it is evidence that the call to prayer is legislated for someone praying alone, and this is the correct view in our school and in others."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7858,10364],"tks":"متفق عليه: رواه مسلم (382)."},{"num":1886,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: يَعْجَبُ رَبُّكُمْ مِنْ رَاعِي غَنَمٍ فِي رَأْسِ شَظِيَّةٍ بِجَبَلٍ، يُؤَذِّنُ بِالصَّلَاةِ وَيُصَلِّي، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: انْظُرُوا إِلَى عَبْدِي هَذَا يُؤَذِّنُ وَيُقِيمُ الصَّلَاةَ، يَخَافُ مِنِّي قَدْ غَفَرْتُ لِعَبْدِي وَأَدْخَلْتُهُ الْجَنَّةَ."],"takhrij":"صحيح: رواه أبو داود (1203)، والنسائي (666) كلاهما من طريق ابن وهب، عن عمرو بن الحارث، أن أبا عُشَّانة المعافري حدَّثه، عن عُقبة بن عامر فذكر الحديث. ومن هذا الطّريق رواه أيضاً الإمام أحمد (17443).","grade":"صحيح","chapter_ar":"باب استحباب الأذان لمن يصلي وحده","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (1203), al-Nasa’i (666), Ahmad (17443)","chapter_en":"Recommendation of giving the call to prayer for one who prays alone","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["‘Uqbah ibn ‘Amir said: I heard the Messenger of Allah ﷺ say: “Your Lord is amazed by a shepherd of sheep on the peak of a high outcrop on a mountain who gives the call to prayer and prays. Allah, Mighty and Majestic, says: ‘Look at this servant of Mine: he gives the call and establishes the prayer, fearing Me. I have forgiven My servant and admitted him into Paradise.’”"]},"buhuth":{"en":["“Shadhiyyah” means an elevated piece at the top of a mountain; it is also said to be a huge rock protruding from the mountain, like the mountain’s “nose.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1203)، النسائي (666)، أحمد (17443)."},{"num":1887,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ سَمِعْنَا مُنَادِيًا يُنَادِي: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَلَى الْفِطْرَةِ، فَقَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَرَجَ مِنَ النَّارِ، قَالَ: فَابْتَدَرْنَاهُ، فَإِذَا هُوَ صَاحِبُ مَاشِيَةٍ أَدْرَكَتْهُ الصَّلَاةُ، فَنَادَى بِهَا."],"takhrij":"صحيح: رواه أحمد (3861) قال: حدثنا محمد بن بِشْر، حدثنا سعيد (وهو ابن أبي عروبة) حدثنا قتادة.","grade":"صحيح","chapter_ar":"باب استحباب الأذان لمن يصلي وحده","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (3861), Abu Ya‘la (5400), al-Tabarani in al-Kabir (10062)","chapter_en":"Recommendation of giving the call to prayer for one who prays alone","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: While we were with the Messenger of Allah ﷺ on one of his journeys, we heard someone calling out: “Allah is the Greatest, Allah is the Greatest.” The Prophet of Allah ﷺ said: “Upon the natural religion.” Then the man said: “I testify that there is no god worthy of worship except Allah.” The Prophet of Allah ﷺ said: “He has escaped the Fire.” We rushed toward him and found that he was a herdsman whose prayer time had come, so he called for it."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10365],"tks":"صحيح: رواه أحمد (3861)، أبو يعلى (5400)، الطبراني في الكبير (10062)."},{"num":1888,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ بِلَالًا يُؤَذِّنُ بِلَيْلٍ، فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ابْنُ أُمِّ مَكْتُومٍ، ثُمَّ قَالَ: وَكَانَ رَجُلًا أَعْمَى لَا يُنَادِي حَتَّى يُقَالَ لَهُ أَصْبَحْتَ أَصْبَحْتَ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (15) عن ابن شهاب، عن سالم بن عبدالله مرسلاً.","grade":"متفق عليه","chapter_ar":"باب جواز أذان الأعمى إذا كان من يُخبِرُه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (15), al-Bukhari (617), Muslim (1092)","chapter_en":"Permissibility of the blind caller to prayer if someone informs him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":13,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “Bilal gives the call during the night, so eat and drink until Ibn Umm Maktum calls.” Then he said: He was a blind man, and he would not call until it was said to him, “Morning has come, morning has come.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (15)، البخاري (617)، مسلم (1092)."},{"num":1889,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ ابْنُ أُمِّ مَكْتُومٍ، يُؤَذِّنُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ أَعْمَى."],"takhrij":"صحيح: رواه مسلم في الصلاة (381) من طريق هشام، عن أبيه، عن عائشة.","grade":"صحيح","chapter_ar":"باب جواز أذان الأعمى إذا كان من يُخبِرُه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (381)","chapter_en":"Permissibility of the blind caller to prayer if someone informs him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":13,"content":{"translation":{"en":["‘A’ishah said: Ibn Umm Maktum used to give the call to prayer for the Messenger of Allah ﷺ while he was blind."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (381)."},{"num":1890,"demo":false,"sanad":"","matn":["عَنْ أَبِي الشَّعْثَاءِ قَالَ: كُنَّا قُعُودًا فِي الْمَسْجِدِ مَعَ أَبِي هُرَيْرَةَ، فَأَذَّنَ الْمُؤَذِّنُ، فَقَامَ رَجُلٌ مِنَ الْمَسْجِدِ يَمْشِي، فَأَتْبَعَهُ أَبُو هُرَيْرَةَ بَصَرَهُ، حَتَّى خَرَجَ مِنَ الْمَسْجِدِ، فَقَالَ أَبُو هُرَيْرَةَ: أَمَّا هَذَا، فَقَدْ عَصَى أَبَا الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.","وَفِي رِوَايَةِ: وَرَأَى رَجُلًا يَجْتَازُ الْمَسْجِدَ خَارِجًا بَعْدَ الأَذَانِ، فَقَالَ: أَمَّا هَذَا فَقَدْ عَصَى أَبَا الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في المساجد (655) من طريق إبراهيم بن المهاجر، عن أبي الشعثاء به مثله وزاد أبو داود (536) من هذا الوجه بأن ذلك في صلاة العصر.","grade":"صحيح","chapter_ar":"باب النهي عن الخروج من المسجد بعد الأذان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (655)","chapter_en":"Prohibition of leaving the mosque after the call to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Abu al-Sha‘tha’ said: We were sitting in the mosque with Abu Hurayrah when the caller gave the call to prayer. A man stood up and walked out of the mosque. Abu Hurayrah watched him until he left, then Abu Hurayrah said: “As for this one, he has disobeyed Abu al-Qasim.” In another narration: He saw a man passing through the mosque to leave after the call to prayer, and he said: “As for this one, he has disobeyed Abu al-Qasim.”"]},"buhuth":{"en":["The statement “he has disobeyed Abu al-Qasim” carries the ruling of being traced back to the Prophet ﷺ. Ahmad (10933) added: “The Messenger of Allah ﷺ commanded us: if we are in the mosque and the call to prayer is made, then none of you should leave until he prays.” Al-Tabarani narrated in al-Awsat (3854) with wording meaning: “No one hears the call in this mosque of mine and then leaves except for a need—and if he does not return, then he is a hypocrite.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (655)."},{"num":1891,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: كَانَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُؤَذِّنَانِ، بِلَالٌ وَابْنُ أُمِّ مَكْتُومٍ الأَعْمَى."],"takhrij":"صحيح: رواه مسلم في الصلاة (380) عن ابن نمير، قال: حدثنا أبي، حدثنا عبيدالله، عن نافع، عن ابن عمر، فذكر مثله.","grade":"صحيح","chapter_ar":"باب جواز اتخاذ مؤذنين فأكثر للمسجد الواحد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (380)","chapter_en":"Permissibility of appointing two or more callers to prayer for one mosque","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ had two callers to prayer: Bilal and Ibn Umm Maktum, who was blind."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (380)."},{"num":1892,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُؤَذِّنَانِ، بِلَالٌ وَابْنُ أُمِّ مَكْتُومٍ الأَعْمَى."],"takhrij":"صحيح: رواه مسلم في الصلاة (380) عن ابن نمير، ثنا أبي، ثنا عبيدالله، ثنا القاسم، عن عائشة، فذكرته. ولم يذكر مسلمٌ لفظه وإنّما حال على حديث ابن عمر.","grade":"صحيح","chapter_ar":"باب جواز اتخاذ مؤذنين فأكثر للمسجد الواحد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (380)","chapter_en":"Permissibility of appointing two or more callers to prayer for one mosque","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ had two callers to prayer: Bilal and Ibn Umm Maktum."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (380)."},{"num":1893,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ قَالَ: يَا رَسُولَ اللَّهِ ! اجْعَلْنِي إِمَامَ قَوْمِي، قَالَ: أَنْتَ إِمَامُهُمْ وَاقْتَدِ بِأَضْعَفِهِمْ وَاتَّخِذْ مُؤَذِّنًا لَا يَأْخُذُ عَلَى أَذَانِهِ أَجْرًا."],"takhrij":"صحيح: رواه أبو داود (531)، والنسائي (672) وأحمد (16271) كلهم من طريق حماد بن سلمة، ثنا سعيد الجُريري، عن أبي العلاء، عن مطرف بن عبدالله، عن عثمان بن أبي العاص فذكره. ومن هذا الوجه أخرجه أيضاً ابن خزيمة (423)، والحاكم (715) وقال: صحيح على شرط مسلم.","grade":"صحيح","chapter_ar":"باب كراهية أخذ الأجر على التأذين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (531), al-Nasa’i (672), Ibn Khuzaymah (423), al-Hakim (715)","chapter_en":"Dislike of taking payment for giving the call to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":16,"content":{"translation":{"en":["‘Uthman ibn Abi al-‘As said: I said, “O Messenger of Allah ﷺ, appoint me as the leader of my people.” He said: “You are their imam, so consider the weakest among them, and appoint a caller to prayer who does not take payment for his call.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (531)، النسائي (672)، ابن خزيمة (423)، الحاكم (715)."},{"num":1894,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ، قَالَهَا ثَلَاثًا، قَالَ فِي الثَّالِثَةِ لِمَنْ شَاءَ.","وَفِي رِوَايَةِ: قَالَ: فِي الرَّابِعَةِ لِمَنْ شَاءَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (624)، ومسلم في صلاة المسافرين (838) كلاهما من طريق عبدالله بن بريدة، عن عبدالله بن المغفل فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب بين كل أذانين صلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (624), Muslim (838)","chapter_en":"Between every two calls there is a prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["‘Abdullah ibn Mughaffal al-Muzani reported that the Messenger of Allah ﷺ said: “Between every two calls there is a prayer,” and he said it three times. Then the third time he said: “For whoever wishes.” In another narration: he said “For whoever wishes” the fourth time."]},"buhuth":{"en":["The phrase “between every two calls” means: between the call to prayer and the call to begin the prayer. Al-Khattabi explained that the two are both referred to as “two calls” by using one name for both, similar to how people say “the two black things” meaning dates and water."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (624)، مسلم (838)."},{"num":1895,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ الْمُؤَذِّنُ إِذَا أَذَّنَ قَامَ نَاسٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبْتَدِرُونَ السَّوَارِيَ حَتَّى يَخْرُجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُمْ كَذَلِكَ يُصَلُّونَ الرَّكْعَتَيْنِ قَبْلَ الْمَغْرِبِ، وَلَمْ يَكُنْ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ شَيْءٌ.","قَالَ عُثْمَانُ بْنُ جَبَلَةَ: وَأَبُو دَاوُدَ عَنْ شُعْبَةَ، لَمْ يَكُنْ بَيْنَهُمَا إِلَّا قَلِيلٌ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (625) من طريق شعبة قال: سمعتُ عمرو بن عامر الأنصاري، عن أنس بن مالك فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب بين كل أذانين صلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (625), Muslim (837)","chapter_en":"Between every two calls there is a prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["Anas ibn Malik said: When the caller to prayer gave the call, some of the Companions of the Prophet ﷺ would rush to the pillars until the Prophet ﷺ came out while they were still praying two units before the sunset prayer, and there was no (long) gap between the call and the call to begin the prayer. ‘Uthman ibn Jablah and Abu Dawud narrated from Shu‘bah: “There was only a little time between them.”"]},"buhuth":{"en":["“Rushing to the pillars” means they hurried to them and competed to reach them so they could pray with some concealment behind a pillar. “There was no gap between the call and the call to begin the prayer” means there was not much time; they would pray those two units quickly because the interval was short."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (625)، مسلم (837)."},{"num":1896,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا سَمِعْتُمُ النِّدَاءَ، فَقُولُوا مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (2) عن ابن شهاب، عن عطاء بن يزيد الليثي، عن أبي سعيد، ورواه البخاري في الأذان (611)، ومسلم في الصلاة (383) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (2), al-Bukhari (611), Muslim (383)","chapter_en":"What to say when one hears the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Messenger of Allah ﷺ said: “When you hear the call, then say the same as what the caller says.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10981],"tks":"متفق عليه: رواه مالك (2)، البخاري (611)، مسلم (383)."},{"num":1897,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ، ثُمَّ صَلُّوا عَلَيَّ، فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا، ثُمَّ سَلُوا اللَّهَ لِي الْوَسِيلَةَ، فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ لَا تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللَّهِ، وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ، فَمَنْ سَأَلَ لِي الْوَسِيلَةَ، حَلَّتْ لَهُ الشَّفَاعَةُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (384) من طريق كعب بن علقمة، عن عبدالرحمن بن جبير، عن عبدالله بن عمرو بن العاص فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (384)","chapter_en":"What to say when one hears the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As said that he heard the Prophet ﷺ say: “When you hear the caller, repeat what he says. Then send blessings upon me, for whoever sends blessings upon me once, Allah sends blessings upon him ten times. Then ask Allah for me to be granted the ‘Wasilah,’ for it is a rank in Paradise that is only suitable for one servant of Allah’s servants, and I hope that I am that one. Whoever asks for me to be granted the Wasilah will have my intercession made due for him.”"]}},"tuhfa":{},"full":1,"rep":[1910,16302],"tks":"صحيح: رواه مسلم (384)."},{"num":1898,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا قَالَ الْمُؤَذِّنُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، فَقَالَ أَحَدُكُمُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، ثُمَّ قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، ثُمَّ قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، ثُمَّ قَالَ: حَيَّ عَلَى الصَّلَاةِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، ثُمَّ قَالَ: حَيَّ عَلَى الْفَلَاحِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، ثُمَّ قَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، قَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، ثُمَّ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، مِنْ قَلْبِهِ دَخَلَ الْجَنَّةَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (385) حدثنا إسحاق بن منصور، أخبرنا أبو جعفر محمد بن جَهْضَم الثقفي، حدثنا إسماعيل بن جعفر، عن عُمارة بن غَزية، عن خُبيب بن عبدالرحمن بن أساف، عن حفص بن عاصم بن عمر بن الخطاب، عن أبيه، عن جده فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (385)","chapter_en":"What to say when one hears the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["‘Umar ibn al-Khattab reported that the Messenger of Allah ﷺ said: “When the caller says: ‘Allah is the Greatest, Allah is the Greatest,’ and one of you says: ‘Allah is the Greatest, Allah is the Greatest’; then he says: ‘I testify that there is no god worthy of worship except Allah,’ and he says: ‘I testify that there is no god worthy of worship except Allah’; then he says: ‘I testify that Muhammad is the Messenger of Allah,’ and he says: ‘I testify that Muhammad is the Messenger of Allah’; then he says: ‘Come to prayer,’ and he says: ‘There is no might and no power except with Allah’; then he says: ‘Come to success,’ and he says: ‘There is no might and no power except with Allah’; then he says: ‘Allah is the Greatest, Allah is the Greatest,’ and he says: ‘Allah is the Greatest, Allah is the Greatest’; then he says: ‘There is no god worthy of worship except Allah,’ and he says: ‘There is no god worthy of worship except Allah’—from his heart—he will enter Paradise.”"]}},"tuhfa":{},"full":1,"rep":[1908,10982],"tks":"صحيح: رواه مسلم (385)."},{"num":1899,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ، عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: مَنْ قَالَ حِينَ يَسْمَعُ الْمُؤَذِّنَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللَّهِ رَبًّا، وَبِمُحَمَّدٍ رَسُولًا، وَبِالإِسْلَامِ دِينًا، غُفِرَ لَهُ ذَنْبُهُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (386) من طريق الليث، عن الحُكيم بن عبدالله، عن عامر بن سعد بن أبي وقَّاص، عن سعد بن أبي وقَّاص، فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (386)","chapter_en":"What to say when one hears the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas reported that the Messenger of Allah ﷺ said: “Whoever says when he hears the caller: ‘I testify that there is no god worthy of worship except Allah alone with no partner, and that Muhammad is His servant and Messenger. I am pleased with Allah as Lord, with Muhammad as Messenger, and with Islam as religion’—his sin will be forgiven.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (386)."},{"num":1900,"demo":false,"sanad":"","matn":["عَنْ عَلْقَمَةَ بْنِ وَقَّاصٍ قَالَ: كُنَّا عِنْدَ مُعَاوِيَةَ، فَقَالَ الْمُؤَذِّنُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، فَقَالَ مُعَاوِيَةُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، فَقَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، فَقَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، فَقَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَقَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَقَالَ: حَيَّ عَلَى الصَّلَاةِ، فَقَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، فَقَالَ: حَيَّ عَلَى الْفَلَاحِ، فَقَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، فَقَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، فَقَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، فَقَالَ: لَا إِلَهَ إِلَّا اللَّهُ، قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، قَالَ: هَكَذَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ أَوْ نَبِيُّكُمْ إِذَا أَذَّنَ الْمُؤَذِّنُ."],"takhrij":"حسن: رواه الإمام أحمد (16896) قال: حدثنا يحيى (ابن سعيد) عن محمد بن عمرو قال: حدثني أبي، عن جدي، قال: فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (16896), al-Nasa’i (677)","chapter_en":"What to say when one hears the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["‘Alqamah ibn Waqqas said: We were with Mu‘awiyah when the caller began: “Allah is the Greatest, Allah is the Greatest.” Mu‘awiyah replied: “Allah is the Greatest, Allah is the Greatest.” The caller said: “I testify that there is no god worthy of worship except Allah,” and he replied likewise. The caller said: “I testify that Muhammad is the Messenger of Allah,” and he replied likewise. The caller said: “Come to prayer,” and he replied: “There is no might and no power except with Allah.” The caller said: “Come to success,” and he replied: “There is no might and no power except with Allah.” The caller said: “Allah is the Greatest, Allah is the Greatest,” and he replied likewise. The caller said: “There is no god worthy of worship except Allah,” and he replied likewise. Then Mu‘awiyah said: This is how the Messenger of Allah ﷺ—or your Prophet—used to say when the caller to prayer gave the call."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (16896)، النسائي (677)."},{"num":1901,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَمِعَ الْمُؤَذِّنَ يَتَشَهَّدُ، قَالَ: وَأَنَا وَأَنَا."],"takhrij":"حسن: رواه أبو داود (526) قال: حدثنا إبراهيم بن مهدي، ثنا علي بن مسهر، عن هشام بن عروة، عن أبيه، عن عائشة فذكرت الحديث.","grade":"حسن","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (526), Ahmad (24933)","chapter_en":"What to say when one hears the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["‘A’ishah reported that when the Messenger of Allah ﷺ heard the caller recite the testimony of faith, he would say: “And I (testify), and I (testify).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (526)، أحمد (24933)."},{"num":1902,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ قَالَ: سَمِعْتُ مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ وَهُوَ جَالِسٌ عَلَى الْمِنْبَرِ أَذَّنَ الْمُؤَذِّنُ، قَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، قَالَ مُعَاوِيَةُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، فَقَالَ مُعَاوِيَةُ: وَأَنَا، فَقَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَقَالَ مُعَاوِيَةُ: وَأَنَا، فَلَمَّا أَنْ قَضَى التَّأْذِينَ، قَالَ: يَا أَيُّهَا النَّاسُ، إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى هَذَا الْمَجْلِسِ حِينَ أَذَّنَ الْمُؤَذِّنُ يَقُولُ مَا سَمِعْتُمْ مِنِّي مِنْ مَقَالَتِي."],"takhrij":"صحيح: رواه البخاري في الجمعة (914) قال: حدثنا ابن مقاتل: قال: أخبرنا عبدالله (وهو: ابن المبارك) قال: أخبرنا أبو بكر بن عثمان بن سهل بن حُنيف، عن أبي أمامة بن سهل بن حُنَيف فذكر الحديث.","grade":"صحيح","chapter_ar":"باب يجيب الإمام على المنبر إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (914)","chapter_en":"The imam responds while on the pulpit when he hears the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abu Umamah ibn Sahl ibn Hunayf said: I heard Mu‘awiyah ibn Abi Sufyan while he was sitting on the pulpit. The caller gave the call and said: “Allah is the Greatest, Allah is the Greatest.” Mu‘awiyah replied: “Allah is the Greatest, Allah is the Greatest.” The caller said: “I testify that there is no god worthy of worship except Allah,” and Mu‘awiyah said: “And I (do as well).” The caller said: “I testify that Muhammad is the Messenger of Allah,” and Mu‘awiyah said: “And I (do as well).” When the call was finished, Mu‘awiyah said: “O people, I heard the Messenger of Allah ﷺ in this very place, when the caller gave the call, saying what you heard me say.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3310,10983],"tks":"صحيح: رواه البخاري (914)."},{"num":1903,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الدُّعَاءُ لَا يُرَدُّ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ...وَفِي رِوَايَةِ: فَادْعُوا."],"takhrij":"حسن: رواه أبو داود (521) والترمذي (212) والنسائي في اليوم والليلة (68،69،70) كلهم من طرق عن زيد العَمّي، عن أبي إياس، عن أنس بن مالك فذكر الحديث.","grade":"حسن","chapter_ar":"الدعاء بين الأذان والإقامة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (521), al-Tirmidhi (212) — he graded it good; al-Nasa’i in al-Yawm wa al-Laylah (68–70)","chapter_en":"Supplication between the call and the start of prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “Supplication is not rejected between the call to prayer and the call to begin the prayer, so make supplication.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (521)، الترمذي (212)، وقال: حسن، النسائي في عمل اليوم والليلة (68–70)."},{"num":1904,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ، اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ، حَلَّتْ لَهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه البخاري في الأذان (614) وفي التفسير bukhari(4719) في قوله تعالى: ﴿عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا﴾ [الإسراء: 79] عن علي بن عياش قال: حدثنا شعيب بن أبي حمزة، عن محمد بن المنكدر، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"الدعاء عند سماع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (4719, 614)","chapter_en":"Supplication upon hearing the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that the Messenger of Allah ﷺ said: “Whoever says when he hears the call: ‘O Allah, Lord of this perfect call and of the established prayer, grant Muhammad the Wasilah and virtue, and raise him to the praised station You promised him’—my intercession will be guaranteed for him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"rep":[913,10985],"tks":"صحيح: رواه البخاري (4719، 614)."},{"num":1905,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ قَالَ (فَذَكَرَ الْحَدِيثَ): قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ... ثُمَّ سَلُوا اللَّهَ لِي الْوَسِيلَةَ، فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ، لَا تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللَّهِ، وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ، فَمَنْ سَأَلَ لِي الْوَسِيلَةَ، حَلَّتْ لَهُ الشَّفَاعَةُ."],"takhrij":"صحيح:  رواه مسلم في الصلاة (384) من طريق كعب بن علقمة، عن عبدالرحمن بن جبير، عن عبدالله بن عمرو بن العاص فذكره.","grade":"صحيح","chapter_ar":"الدعاء عند سماع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (384)","chapter_en":"Supplication upon hearing the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As said: The Prophet ﷺ said: “Then ask Allah to grant me the Wasilah, for it is a rank in Paradise that is only suitable for one servant of Allah’s servants, and I hope that I am that one. Whoever asks Allah to grant me the Wasilah will have my intercession made due for him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (384)."},{"num":1906,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَلُوا اللَّهَ لِي الْوَسِيلَةَ، فَإِنَّهُ لَمْ يَسْأَلْهَا لِي عَبْدٌ فِي الدُّنْيَا إِلَّا كُنْتُ لَهُ شَهِيدًا، أَوْ شَفِيعًا يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: أخرجه الطبراني في الأوسط (633)، مجمع البحرين (639) قال: حدثنا أحمد، يعني ابن علي الأبار، ثنا الوليد بن عبد الملك الحراني، ثنا موسى بن أعين، عن ابن أبي ذئب، عن محمد بن عمرو بن عطاء، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"الدعاء عند سماع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Awsat; cited in Majma‘ al-Bahrayn (639)","chapter_en":"Supplication upon hearing the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ said: “Ask Allah to grant me the Wasilah. No servant asks it for me in this world except that I will be a witness or an intercessor for him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط، كما في مجمع البحرين (639)."},{"num":1907,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ! إِنَّ الْمُؤَذِّنِينَ يَفْضُلُونَنَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قُلْ كَمَا يَقُولُونَ، فَإِذَا انْتَهَيْتَ فَسَلْ تُعْطَهْ."],"takhrij":"حسن: رواه أبو داود (524) واللفظ له، وأحمد (6601) والبيهقي (1936) كلّهم من طريق حُييّ، عن أبي عبدالرحمن – يعني الحُبلِّي، عن عبدالله بن عمرو فذكره.","grade":"حسن","chapter_ar":"الدعاء عند سماع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (524) — wording his; Ahmad (6601); al-Bayhaqi (1/410)","chapter_en":"Supplication upon hearing the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As reported that a man said: “O Messenger of Allah, the callers to prayer surpass us.” The Messenger of Allah ﷺ said: “Say what they say, and when you finish, ask— and you will be given.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (524)، واللفظ له، أحمد (6601)، البيهقي (1936)."},{"num":1908,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا قَالَ الْمُؤَذِّنُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، فَقَالَ أَحَدُكُمُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، ثُمَّ قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، ثُمَّ قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، ثُمَّ قَالَ: حَيَّ عَلَى الصَّلَاةِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، ثُمَّ قَالَ: حَيَّ عَلَى الْفَلَاحِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، ثُمَّ قَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، قَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، ثُمَّ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، مِنْ قَلْبِهِ دَخَلَ الْجَنَّةَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (385) من طريق حفص بن عاصم بن عمر بن الخطاب، عن أبيه، عن جدِّه عمر بن الخطاب فذكر الحديث بطوله.","grade":"صحيح","chapter_ar":"باب ماذا يقول إذا قال المؤذن: حيَّ على الصلاة حيَّ على الفلاح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (385).","chapter_en":"What to say when the caller says: ‘Come to prayer’ and ‘Come to success’","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":22,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb reported that the Messenger of Allah ﷺ said: “When the muʾadhdhin says, ‘Allah is the Greatest, Allah is the Greatest,’ and one of you says, ‘Allah is the Greatest, Allah is the Greatest’; then he says, ‘I testify that there is no deity worthy of worship except Allah,’ and he says, ‘I testify that there is no deity worthy of worship except Allah’; then he says, ‘I testify that Muḥammad is the Messenger of Allah,’ and he says, ‘I testify that Muḥammad is the Messenger of Allah’; then he says, ‘Come to prayer,’ and he says, ‘There is no might and no power except with Allah’; then he says, ‘Come to success,’ and he says, ‘There is no might and no power except with Allah’; then he says, ‘Allah is the Greatest, Allah is the Greatest,’ and he says, ‘Allah is the Greatest, Allah is the Greatest’; then he says, ‘There is no deity worthy of worship except Allah,’ and he says sincerely from his heart, ‘There is no deity worthy of worship except Allah,’ he will enter Paradise.” The word ḥawl means movement or ability; that is, there is no movement or ability for me except by Allah’s will."]},"buhuth":{"en":["The expression used to refer to saying “There is no might and no power except with Allah” is “hawqalah.” The letters ḥā’ and wāw come from “might/turning,” the qāf comes from “power,” and the lām comes from the Name of Allah. It is like saying “basmalah” for “In the name of Allah,” and “hamdalah” for “All praise is for Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1898,10982],"tks":"صحيح: رواه مسلم (385)."},{"num":1909,"demo":false,"sanad":"","matn":["عَنْ عِيسَى بْنِ طَلْحَةَ قَالَ: دَخَلْنَا مَعَ مُعَاوِيَةَ، فَنَادَى الْمُنَادِي بِالصَّلاةِ، فَقَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، فَقَالَ مُعَاوِيَةُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، ثُمَّ قَالَ: أَشْهَدُ أَنْ لا إِلَهَ إِلا اللَّهُ، فَقَالَ مُعَاوِيَةُ: وَأَنَا أَشْهَدُ، ثُمَّ قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَقَالَ مُعَاوِيَةُ: وَأَنَا أَشْهَدُ، ثُمَّ قَالَ: حَيَّ عَلَى الصَّلاةِ، فَقَالَ مُعَاوِيَةُ: لا حَوْلَ وَلا قُوَّةَ إِلا بِاللَّهِ، ثُمَّ قَالَ: حَيَّ عَلَى الْفَلاحِ، فَقَالَ مُعَاوِيَةُ: لا حَوْلَ وَلا قُوَّةَ إِلا بِاللَّهِ، ثُمَّ قَالَ: هَكَذَا سَمِعْتُ نَبِيَّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ."],"takhrij":"حسن: رواه ابن خزيمة (414) عن يعقوب بن إبراهيم الدورقي، ثنا ابن علية ( وهو إسماعيل بن إبراهيم ) عن هشام الدستوائي، عن يحيى بن أبي كثير، عن محمد بن إبراهيم، عن عيسى بن طلحة فذكر مثله.","grade":"حسن","chapter_ar":"باب ماذا يقول إذا قال المؤذن: حيَّ على الصلاة حيَّ على الفلاح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Khuzaymah (414)","chapter_en":"What to say when the caller says: ‘Come to prayer’ and ‘Come to success’","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":22,"content":{"translation":{"en":["‘Isa ibn Talhah said: We entered upon Mu‘awiyah when the caller announced the prayer. He said: “Allah is the Greatest, Allah is the Greatest,” and Mu‘awiyah replied: “Allah is the Greatest, Allah is the Greatest.” Then he said: “I testify that there is no god worthy of worship except Allah,” and Mu‘awiyah said: “And I testify.” Then he said: “I testify that Muhammad is the Messenger of Allah,” and Mu‘awiyah said: “And I testify.” Then he said: “Come to prayer,” and Mu‘awiyah said: “There is no might and no power except with Allah.” Then he said: “Come to success,” and Mu‘awiyah said: “There is no might and no power except with Allah.” Then Mu‘awiyah said: This is how I heard your Prophet ﷺ say."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (414)."},{"num":1910,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: إِذَا سَمِعْتُمُ الْمُؤَذِّنَ، فَقُولُوا مِثْلَ مَا يَقُولُ، ثُمَّ صَلُّوا عَلَيَّ، فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلَاةً، صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا، ثُمَّ سَلُوا اللَّهَ لِي الْوَسِيلَةَ، فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ، لَا تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللَّهِ، وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ، فَمَنْ سَأَلَ لِي الْوَسِيلَةَ، حَلَّتْ لَهُ الشَّفَاعَةُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (384) عن محمد بن سلمة المرادي، حدَّثنا عبدالله بن وهب، عن حيوة وسعيد بن أبي أيوب وغيرهما، عن كعب ابن علقمة، عن عبدالرحمن بن جبير، عن عبدالله بن عمرو بن العاص فذكره.","grade":"صحيح","chapter_ar":"باب في الصلاة على النبي ﷺ عند الأذان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (384)","chapter_en":"Sending blessings upon the Prophet ﷺ after the call","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":23,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As said that he heard the Prophet ﷺ say: “When you hear the caller, repeat what he says. Then send blessings upon me, for whoever sends blessings upon me once, Allah sends blessings upon him ten times. Then ask Allah to grant me the Wasilah, for it is a rank in Paradise that is only suitable for one servant of Allah’s servants, and I hope that I am that one. Whoever asks Allah to grant me the Wasilah will have my intercession made due for him.”"]}},"tuhfa":{},"full":1,"rep":[1897,16302],"tks":"صحيح: رواه مسلم (384)."},{"num":1911,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ، اللَّهُمَّ أَرْشِدِ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ."],"takhrij":"صحيح: رواه الترمذي (207) قال: حدثنا هناد، حدثنا أبو الأحوص وأبو معاوية، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء أن الإمام ضامن والمؤذن مؤتمن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Tirmidhi (207), Ahmad (9942), Abu Dawud al-Tayalisi (2526)","chapter_en":"The imam is responsible and the caller to prayer is entrusted","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The imam is responsible, and the caller to prayer is entrusted. O Allah, guide the leaders of prayer and forgive the callers to prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (207)، أحمد (9942)، أبو داود الطيالسي (2526)."},{"num":1912,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ، اللَّهُمَّ أَرْشِدِ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ."],"takhrij":"صحيح: رواه أبو العباس السراج في مسنده (72) عن محمد بن عقيل، حدَّثنا حفص. وحدَّثنا أحمد بن حفص بن عبدالله، قال: حدثني أبي، قال: حدثني إبراهيم بن طهمان، حدثنا سليمان الأعمش، عن مجاهد، عن ابن عمر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء أن الإمام ضامن والمؤذن مؤتمن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu al-‘Abbas al-Siraj in his Musnad (72)","chapter_en":"The imam is responsible and the caller to prayer is entrusted","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “The imam is responsible, and the caller to prayer is entrusted. O Allah, guide the leaders of prayer and forgive the callers to prayer.”"]},"buhuth":{"en":["The phrase “the imam is responsible” means “the imam is a caretaker.” In Arabic usage, “guarantee” here means oversight and care. The meaning is that he safeguards the prayer and the number of its units for the congregation. It is also said it means he is responsible for the supplication that includes them, not restricting it to himself. It is not the kind of “guarantee” that implies financial liability.","Some scholars also interpreted this to mean that the imam bears the recitation on behalf of the followers in some circumstances, and likewise bears the standing for one who catches him while he is bowing. Al-Khattabi noted this."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو العباس السراج في مسنده (72)."},{"num":1913,"demo":false,"sanad":"","matn":["عَنْ أَبِي عَلِيٍّ الْهَمْدَانِيِّ، أَنَّهُ خَرَجَ فِي سَفِينَةٍ فِيهَا عُقْبَةُ بْنُ عَامِرٍ الْجُهَنِيُّ، فَحَانَتْ صَلَاةٌ مِنَ الصَّلَوَاتِ، فَأَمَرْنَاهُ أَنْ يَؤُمَّنَا، وَقُلْنَا لَهُ: إِنَّكَ أَحَقُّنَا بِذَلِكَ أَنْتَ صَاحِبُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَبَى فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَمَّ النَّاسَ فَأَصَابَ، فَالصَّلَاةُ لَهُ وَلَهُمْ، وَمَنِ انْتَقَصَ مِنْ ذَلِكَ شَيْئًا فَعَلَيْهِ وَلَا عَلَيْهِمْ."],"takhrij":"حسن: رواه أبو داود (580) وابن ماجه (983) كلاهما من طريق عبدالرحمن بن حرملة، عن أبي علي الهمداني فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء أن الإمام ضامن والمؤذن مؤتمن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (580), Ibn Majah (983)","chapter_en":"The imam is responsible and the caller to prayer is entrusted","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Abu ‘Ali al-Hamdani said: He went out on a ship in which ‘Uqbah ibn ‘Amir al-Juhani was present. When the time for one of the prayers came, we asked him to lead us. We said to him: “You are the most entitled among us to do so, for you are a Companion of the Messenger of Allah ﷺ.” He refused and said: I heard the Messenger of Allah ﷺ say: “Whoever leads people and does it correctly, the prayer is for him and for them. And whoever diminishes anything of that, then it is upon him, and not upon them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (580)، ابن ماجه (983)."},{"num":1914,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْإِمَامُ ضَامِنٌ، وَالْمُؤَذِّنُ مُؤْتَمَنٌ."],"takhrij":"حسن: رواه الإمام أحمد (22238)، والطبراني في الكبير (8097) كلاهما من طريق الحسين بن واقد، حدثني أبو غالب، عن أبي أمامة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن الإمام ضامن والمؤذن مؤتمن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (22238), al-Tabarani in al-Kabir (8/343)","chapter_en":"The imam is responsible and the caller to prayer is entrusted","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Abu Umamah reported that the Messenger of Allah ﷺ said: “The imam is responsible, and the caller to prayer is entrusted.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22238)، الطبراني في الكبير (8097)."},{"num":1915,"demo":false,"sanad":"","matn":["عَنْ أَبِي جُحَيْفَةَ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ وَهُوَ فِي قُبَّةٍ حَمْرَاءَ مِنْ أَدَمٍ، فَخَرَجَ بِلَالٌ فَأَذَّنَ، فَكُنْتُ أَتَتَبَّعُ فَمَهُ هَاهُنَا وَهَاهُنَا، قَالَ: ثُمَّ خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ حُلَّةٌ حَمْرَاءُ بُرُودٌ يَمَانِيَةٌ قِطْرِيٌّ.","وَقَالَ مُوسَى: قَالَ: رَأَيْتُ بِلَالًا خَرَجَ إِلَى الْأَبْطَحِ فَأَذَّنَ، فَلَمَّا بَلَغَ حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ، لَوَى عُنُقَهُ يَمِينًا وَشِمَالًا وَلَمْ يَسْتَدِرْ، ثُمَّ دَخَلَ فَأَخْرَجَ الْعَنَزَةَ، وَسَاقَ حَدِيثَهُ."],"takhrij":"صحيح: رواه أبو داود (520) عن موسى بن إسماعيل، حدثنا قيس، يعني ابن الربيع، ح وحدثنا محمد بن سليمان الأنباري، حدثنا وكيع، عن سفيان، جميعاً عن عون بن أبي حجيفة، عن أبيه فذكر الحديث.","grade":"صحيح","chapter_ar":"باب إدخال الإصبع في الأذن عند الأذان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (520). Also reported by al-Tirmidhi (197) and al-Hakim (1/202) with mention that Bilal placed his fingers in his ears, and al-Tirmidhi graded it “hasan sahih.”","chapter_en":"Placing the finger in the ear during the call to prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":25,"content":{"translation":{"en":["Abu Juhayfah said: I came to the Prophet ﷺ in Makkah while he was in a red leather tent. Bilal came out and gave the call to prayer, and I watched his mouth turn this way and that. Then the Messenger of Allah ﷺ came out wearing a red garment of Yemeni Qitri cloth. Musa said: He said: I saw Bilal go out to al-Abtah and give the call to prayer. When he reached “Come to prayer, come to success,” he turned his neck to the right and to the left without turning his whole body, then he went in and brought out a short spear, and he continued the narration."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (520)، ورواه الترمذي (197)، والحاكم (1/202)، وفيه ذكر أن بلالا جعل إصبعيه في أذنيه، وقال الترمذي: حسن صحيح."},{"num":1916,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: كَانَ بِلَالٌ يُؤَذِّنُ إِذَا دَحَضَتْ، فَلَا يُقِيمُ حَتَّى يَخْرُجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِذَا خَرَجَ أَقَامَ الصَّلَاةَ حِينَ يَرَاهُ."],"takhrij":"صحيح: رواه مسلم في المساجد (606) عن سلمة بن شبيب، ثنا الحسن ابن أعين، ثنا زهير، ثنا سماك بن حرْب، عن جابر بن عبدالله فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في المؤذن ينتظر الإمام، فإذا رآه يقيم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (606)","chapter_en":"The caller waits for the imam, and when he sees him, he begins the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":26,"content":{"translation":{"en":["Jabir ibn Samurah said: Bilal used to give the call to prayer when the sun had declined from the meridian, but he would not give the call to begin the prayer until the Prophet ﷺ came out. When he came out, Bilal would begin the prayer as soon as he saw him."]},"buhuth":{"en":["It is also reported by Abu Dawud and al-Tirmidhi with wording that the caller to prayer would call, then wait; when he saw the Prophet ﷺ come out, he would begin the prayer. Al-Tirmidhi did not name the caller, while Abu Dawud identified him as Bilal. Al-Tirmidhi said: Some scholars stated: “The caller has more authority over the call to prayer, and the imam has more authority over the call to begin the prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (606)."},{"num":1917,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: أُقِيمَتِ الصَّلَاةُ، فَقُمْنَا، فَعَدَّلْنَا الصُّفُوفَ قَبْلَ أَنْ يَخْرُجَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى إِذَا قَامَ فِي مُصَلَّاهُ قَبْلَ أَنْ يُكَبِّرَ ذَكَرَ، فَانْصَرَفَ وَقَالَ لَنَا: مَكَانَكُمْ، فَلَمْ نَزَلْ قِيَامًا نَنْتَظِرُهُ حَتَّى خَرَجَ إِلَيْنَا وَقَدِ اغْتَسَلَ يَنْطُفُ رَأْسُهُ مَاءً، فَكَبَّرَ فَصَلَّى بِنَا."],"takhrij":"متفق عليه: رواه البخاري في الغسل (275)، ومسلم في المساجد (605) –واللفظ له، كلاهما من طريق يونس، عن الزهري، عن أبي سلمة، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب أن المؤذن يقيم قبل أن يخرج الإمام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (275), Muslim (605) — wording per Muslim","chapter_en":"The caller begins the prayer before the imam comes out","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abu Hurayrah said: The prayer was started, so we stood and straightened the rows before the Messenger of Allah ﷺ came out to us. The Messenger of Allah ﷺ came until he stood in his place of prayer, but before he said the opening declaration, he remembered something, so he turned back and said to us: “Stay where you are.” We remained standing waiting until he came out to us after bathing, with water dripping from his head. Then he declared the opening and led us in prayer."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (275)، مسلم (605)، واللفظ لمسلم."},{"num":1918,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أُقِيمَتِ الصَّلَاةُ فَلَا تَقُومُوا حَتَّى تَرَوْنِي."],"takhrij":"متفق عليه: رواه البخاري في الأذان (637) ومسلم في المساجد (604) كلاهما من طريق يحيى بن أبي كثير، عن عبدالله بن أبي قتادة، وقرنه مسلم بأبي سلمة، عن أبي قتادة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب قيام الناس إذا رأوا الإمام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (637), Muslim (604)","chapter_en":"People stand when they see the imam","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":28,"content":{"translation":{"en":["Abu Qatadah reported that the Messenger of Allah ﷺ said: “When the prayer is started, do not stand until you see me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (637)، مسلم (604)."},{"num":1919,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: أُقِيمَتِ الصَّلَاةُ فَعَرَضَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ، فَحَبَسَهُ بَعْدَ مَا أُقِيمَتِ الصَّلَاةُ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (643) ومسلم في الحيض (376)، وقد مضى الحديث في الطهارة، باب نوم الجالس لا ينقض الوضوء.","grade":"متفق عليه","chapter_ar":"باب جواز الكلام إذا أقيمت الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (643), Muslim (376)","chapter_en":"Permissibility of speaking after the prayer is started","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الأذان","group_en":"Chapters on the Call to Prayer","part_no":9,"group_no":3,"chapter_no":29,"content":{"translation":{"en":["Anas said: The prayer was started, and a man came to the Prophet ﷺ with a matter and kept him occupied even after the prayer had been started."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (643)، مسلم (376)."},{"num":1920,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ قَالَ: أَتَيْنَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ شَبَبَةٌ مُتَقَارِبُونَ، فَأَقَمْنَا عِنْدَهُ عِشْرِينَ يَوْمًا وَلَيْلَةً، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَحِيمًا رَفِيقًا، فَلَمَّا ظَنَّ أَنَّا قَدِ اشْتَهَيْنَا أَهْلَنَا أَوْ قَدِ اشْتَقْنَا سَأَلَنَا عَمَّنْ تَرَكْنَا بَعْدَنَا، فَأَخْبَرْنَاهُ قَالَ: ارْجِعُوا إِلَى أَهْلِيكُمْ، فَأَقِيمُوا فِيهِمْ وَعَلِّمُوهُمْ وَمُرُوهُمْ، وَذَكَرَ أَشْيَاءَ أَحْفَظُهَا أَوْ لَا أَحْفَظُهَا وَصَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي، فَإِذَا حَضَرَتِ الصَّلَاةُ فَلْيُؤَذِّنْ لَكُمْ أَحَدُكُمْ وَلْيَؤُمَّكُمْ أَكْبَرُكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (631) واللفظ له، ومسلم في المساجد (674) كلاهما عن أبي قِلابة، عن مالك بن الحويرث فذكر مثله، ولم يذكر مسلم: صلوا كما رأيتموني أصلي. والحديث قد سبق ذكره في أبواب الأذان، وسيأتي أيضاً في باب رفع اليدين عند الركوع، وعند رفع الرأس منه.","grade":"متفق عليه","chapter_ar":"باب قوله ﷺ: «صلُّوا كما رأيتموني أُصلِّي»","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (631) — wording his; Muslim (674)","chapter_en":"His statement: “Pray as you have seen me pray.”","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Malik ibn al-Huwayrith said: We came to the Prophet ﷺ while we were young men of similar age. We stayed with him for twenty days and nights, and the Messenger of Allah ﷺ was merciful and gentle. When he thought we had begun to long for our families—or missed them—he asked us about those we had left behind, and we told him. He said: “Return to your families, stay among them, teach them, and command them…”—and he mentioned things I remember and things I do not—“and pray as you have seen me pray. When the prayer time comes, let one of you call to prayer, and let the eldest among you lead you.”"]},"intro_majmu":{"ar":["قال الله تعالى:","(لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا) [الأحزاب: 21].","وقال تعالى:","(يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ ۖ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۚ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا) [النساء: 59].","وقال تعالى:","(يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ وَاعْلَمُوا أَنَّ اللَّهَ يَحُولُ بَيْنَ الْمَرْءِ وَقَلْبِهِ وَأَنَّهُ إِلَيْهِ تُحْشَرُونَ) [الأنفال: 24]."],"en":["Allah Most High says: “Indeed, in the Messenger of Allah you have an excellent example for whoever hopes in Allah and the Last Day and remembers Allah often.” (Qur’an 33:21)","“O you who believe, obey Allah and obey the Messenger and those in authority among you. If you dispute over anything, refer it to Allah and the Messenger, if you truly believe in Allah and the Last Day. That is best and most suitable in outcome.” (Qur’an 4:59)","“O you who believe, respond to Allah and the Messenger when he calls you to what gives you life, and know that Allah intervenes between a person and his heart, and that to Him you will be gathered.” (Qur’an 8:24)"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (631)، واللفظ له، مسلم (674)."},{"num":1921,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى نَحْوَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ أَنْ يُوَجَّهَ إِلَى الْكَعْبَةِ، فَأَنْزَلَ اللَّهُ ﴿قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ﴾ [ سورة البقرة: 144] فَتَوَجَّهَ نَحْوَ الْكَعْبَةِ، وَقَالَ السُّفَهَاءُ مِنَ النَّاسِ وَهُمْ الْيَهُودُ: ﴿مَا وَلَّاهُمْ عَنْ قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا، قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ﴾ [ سورة البقرة: 142]. فَصَلَّى مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ، ثُمَّ خَرَجَ بَعْدَ مَا صَلَّى، فَمَرَّ عَلَى قَوْمٍ مِنْ الْأَنْصَارِ فِي صَلَاةِ الْعَصْرِ نَحْوَ بَيْتِ الْمَقْدِسِ، فَقَالَ: هُوَ يَشْهَدُ أَنَّهُ صَلَّى مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَنَّهُ تَوَجَّهَ نَحْوَ الْكَعْبَةِ فَتَحَرَّفَ الْقَوْمُ حَتَّى تَوَجَّهُوا نَحْوَ الْكَعْبَةِ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (399)، ومسلم في المساجد (525) كلاهما من حديث أبي إسحاق، عن البراء بن عازب، واللفظ للبخاري، وذكره مسلم مختصراً نحوه، وانفرد البخاري فذكر في كتاب الإيمان (40): وهم راكعون، فداروا كما هم قِبَل البيت، وكانت اليهود قد أعجبهم إذ كان يُصَلِّي قِبل بيت المقدس وأهلُ الكتاب، فلما ولَّى وجْهَه قِبل البيتِ أنكروا ذلك.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحويل القبلة من بيت المقدس إلى بيت الله الحرام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (399), Muslim (525)","chapter_en":"Reports about the change of the direction of prayer from Jerusalem to the Sacred House in Makkah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib said: The Messenger of Allah ﷺ prayed facing Jerusalem for sixteen—or seventeen—months. The Messenger of Allah ﷺ loved to be directed toward the Ka‘bah, so Allah revealed: “We have certainly seen the turning of your face toward the heaven…” (Qur’an 2:144), and he turned to face the Ka‘bah. The foolish among the people—meaning the Jews—said: “What has turned them away from their direction of prayer which they used to face? Say: To Allah belong the east and the west. He guides whom He wills to a straight path.” (Qur’an 2:142). A man prayed with the Prophet ﷺ, then left after praying. He passed by a group of the Ansar while they were praying the afternoon prayer facing Jerusalem, and he said: “I testify that I prayed with the Messenger of Allah ﷺ, and that he has turned toward the Ka‘bah.” So the people turned during the prayer until they faced the Ka‘bah."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (399)، مسلم (525)."},{"num":1922,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ مَعْرُورٍ قَالَ: أَنَّهُ قَالَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي خَرَجْتُ فِي سَفَرِي هَذَا وَقَدْ هَدَانِي اللَّهُ لِلإِسْلامِ، فَرَأَيْتُ أَلا أَجْعَلَ هَذِهِ الْبِنْيَةَ مِنِّي بِظَهْرٍ، فَصَلَّيْتُ إِلَيْهَا، وَقَدْ خَالَفَنِي أَصْحَابِي فِي ذَلِكَ حَتَّى وَقَعَ فِي نَفْسِي مِنْ ذَلِكَ شَيْءٌ، فَمَاذَا تَرَى ؟ قَالَ: قَدْ كُنْتَ عَلَى قِبْلَةٍ لَوْ صَبَرْتَ عَلَيْهَا.","قَالَ: فَرَجَعَ الْبَرَاءُ إِلَى قِبْلَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَصَلَّى مَعَنَا إِلَى الشَّامِ."],"takhrij":"حسن: رواه ابن خزيمة (429) من طريق ابن إسحاق، قال: حدثني معبد بن كعب بن مالك، وكان من أعلم الأنصار، ، حدثني أن أباه كعباً حدّثه، ورواه أحمد (15798) وفيه: عن معبد بن كعب، عن أخيه عبيد الله بن كعب، عن أبيه، وذكر الحديث بطوله.","grade":"حسن","chapter_ar":"باب ما جاء في تحويل القبلة من بيت المقدس إلى بيت الله الحرام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Khuzaymah (429). Ahmad narrated a similar report (15798).","chapter_en":"Reports about the change of the direction of prayer from Jerusalem to the Sacred House in Makkah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Al-Bara’ ibn Ma‘rur said that he said to the Prophet ﷺ: “I set out on this journey, and Allah guided me to Islam. I thought I should not keep this House behind my back, so I prayed facing it. My companions disagreed with me about that, and it began to trouble me. What do you think?” He said: “You were already upon a direction of prayer—if only you had remained patient upon it.” So al-Bara’ returned to the Prophet’s direction of prayer and prayed with us toward Syria."]},"buhuth":{"en":["“The small building” refers to the Ka‘bah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (429)، وروى أحمد نحوه (15798)."},{"num":1923,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنَّهُ قَالَ: بَيْنَمَا النَّاسُ بِقُبَاءٍ فِي صَلَاةِ الصُّبْحِ إِذْ جَاءَهُمْ آتٍ فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أُنْزِلَ عَلَيْهِ اللَّيْلَةَ قُرْآنٌ، وَقَدْ أُمِرَ أَنْ يَسْتَقْبِلَ الْكَعْبَةَ فَاسْتَقْبَلُوهَا وَكَانَتْ وُجُوهُهُمْ إِلَى الشَّامِ فَاسْتَدَارُوا إِلَى الْكَعْبَةِ."],"takhrij":"متفق عليه: رواه مالك في القبلة (6) عن عبدالله بن دينا، عن عبدالله بن عمر فذكره، ومن طريقه أخرجه البخاري في الصلاة (403)، ومسلم في المساجد (526).","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحويل القبلة من بيت المقدس إلى بيت الله الحرام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (6), al-Bukhari (403), Muslim (526)","chapter_en":"Reports about the change of the direction of prayer from Jerusalem to the Sacred House in Makkah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Umar said: While the people in Quba’ were in the dawn prayer, a messenger came to them and said: “Revelation has been sent down to the Messenger of Allah ﷺ tonight, and he has been commanded to face the Ka‘bah, so face it.” They had been facing Syria, so they turned around to face the Ka‘bah."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (6)، البخاري (403)، مسلم (526)."},{"num":1924,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي نَحْوَ بَيْتِ الْمَقْدِسِ فَنَزَلَتْ: ﴿قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ﴾ [ سورة البقرة: 144]، فَمَرَّ رَجُلٌ مِنْ بَنِي سَلِمَةَ وَهُمْ رُكُوعٌ فِي صَلَاةِ الْفَجْرِ، وَقَدْ صَلَّوْا رَكْعَةً فَنَادَى: أَلَا إِنَّ الْقِبْلَةَ قَدْ حُوِّلَتْ، فَمَالُوا كَمَا هُمْ نَحْوَ الْقِبْلَةِ."],"takhrij":"صحيح: رواه مسلم في المساجد (527) عن أبي بكر بن أبي شيبة، ثنا عفان، ثنا حماد بن سلمة، عن ثابت، عن أنس فذكر مثله، وبقية الأحاديث في تحويل القبلة ستأتي في كتاب التفسير إن شاء الله تعالى.","grade":"صحيح","chapter_ar":"باب ما جاء في تحويل القبلة من بيت المقدس إلى بيت الله الحرام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (527)","chapter_en":"Reports about the change of the direction of prayer from Jerusalem to the Sacred House in Makkah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ used to pray facing Jerusalem, then the verse was revealed: “We have certainly seen the turning of your face toward the heaven, so We will surely turn you to a direction of prayer that pleases you; so turn your face toward the Sacred Mosque…” (Qur’an 2:144). A man passed by the people of Banu Salimah while they were in bowing in the dawn prayer and had already prayed one unit. He called out: “Indeed, the direction of prayer has been changed!” So they turned, as they were, toward the new direction."]},"buhuth":{"en":["There is no contradiction between al-Bara’s report (that it happened during the afternoon prayer) and the reports of Ibn ‘Umar and Anas (that it happened during the dawn prayer). It is possible that the news reached those inside the city at the time of afternoon prayer, and it reached those outside the city—people of Quba’—at the time of dawn."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (527)."},{"num":1925,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: جَاءَ مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ الْقِبْلَةَ قَدْ حُوِّلَتْ، وَالإِمَامُ فِي الصَّلاةِ قَدْ صَلَّى رَكْعَتَيْنِ، فَقَالَ الْمُنَادِي: قَدْ حُوِّلَتِ الْقِبْلَةُ إِلَى الْكَعْبَةِ، فَصَلَّوُا الرَّكْعَتَيْنِ الْبَاقِيَتَيْنِ إِلَى الْكَعْبَةِ."],"takhrij":"حسن: رواه أبو بكر بن أبي شيبة (3373)، والبزار - كشف الأستار (421)، كلاهما من حديث زيد بن الحباب، ثنا جميل بن عبيد أبو النّضر، ثنا ثمامة، عن جدّه أنس بن مالك، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحويل القبلة من بيت المقدس إلى بيت الله الحرام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Bakr ibn Abi Shaybah (1/334), al-Bazzar in Kashf al-Astar (421)","chapter_en":"Reports about the change of the direction of prayer from Jerusalem to the Sacred House in Makkah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: A caller of the Messenger of Allah ﷺ came and said: “The direction of prayer has been changed.” The imam had already prayed two units. The caller said: “The direction has been changed to the Ka‘bah.” So they prayed the remaining two units facing the Ka‘bah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو بكر بن أبي شيبة (3373)، البزار في كشف الأستار (421)."},{"num":1926,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي وَهُوَ بِمَكَّةَ نَحْوَ بَيْتِ الْمَقْدِسِ، وَالْكَعْبَةُ بَيْنَ يَدَيْهِ، وَبَعْدَ مَا هَاجَرَ إِلَى الْمَدِينَةِ سِتَّةَ عَشَرَ شَهْرًا، ثُمَّ صُرِفَ إِلَى الْكَعْبَةِ."],"takhrij":"صحيح: رواه أحمد (2991)، والبزار - كشف الأستار (418)، والطبراني في الكبير (11066) كلّهم من طريق يحيى بن حماد، حدّثنا أبو عوانة، عن الأعمش، عن مجاهد، عن ابن عباس، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في تحويل القبلة من بيت المقدس إلى بيت الله الحرام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (2991), al-Bazzar in Kashf al-Astar (418), al-Tabarani in al-Kabir (11/67)","chapter_en":"Reports about the change of the direction of prayer from Jerusalem to the Sacred House in Makkah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Abbas said: While the Messenger of Allah ﷺ was in Makkah, he would pray facing Jerusalem with the Ka‘bah in front of him (between him and that direction). After he migrated to Madinah, he continued for sixteen months, then he was turned to face the Ka‘bah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (2991)، البزار في كشف الأستار (418)، الطبراني في المعجم الكبير (11066)."},{"num":1927,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: لَمَّا حُوِّلَتِ الْقِبْلَةُ إِلَى الْكَعْبَةِ مَرَّ رَجُلٌ بِأَهْلِ قُبَاءٍ وَهُمْ يُصَلُّونَ، فَقَالَ لَهُمْ: قَدْ حُوِّلَتِ الْقِبْلَةُ إِلَى الْكَعْبَةِ، فَاسْتَدَارُوا أَمَامَهُمْ نَحْوَ الْكَعْبَةِ."],"takhrij":"حسن: رواه الدارقطني (1074)، والطبراني في الكبير (5860) كلاهما من حديث عبيدالله بن موسى، حدثنا عبد السلام بن حفص، عن أبي حازم، عن سهل بن سعد، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحويل القبلة من بيت المقدس إلى بيت الله الحرام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Daraqutni (1074), al-Tabarani in al-Kabir (6/200)","chapter_en":"Reports about the change of the direction of prayer from Jerusalem to the Sacred House in Makkah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Sahl ibn Sa‘d said: When the direction of prayer was changed to the Ka‘bah, a man passed by the people of Quba’ while they were praying and told them: “The direction of prayer has been changed to the Ka‘bah.” So they turned, with their imam, toward the Ka‘bah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني (1074)، الطبراني في المعجم الكبير (5860)."},{"num":1928,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: كَانَ أَوَّلُ مَا نُسِخَ مِنَ الْقُرْآنِ الْقِبْلَةُ، وَذَلِكَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا هَاجَرَ إِلَى الْمَدِينَةِ. وَكَانَ أَكْثَرُ أَهْلِهَا الْيَهُودُ، أَمَرَهُ اللَّهُ أَنْ يَسْتَقْبِلَ بَيْتَ الْمَقْدِسِ، فَفَرِحَتِ الْيَهُودُ، فَاسْتَقْبَلَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَضْعَةَ عَشَرَ شَهْرًا، فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ قِبْلَةَ إِبْرَاهِيمَ فَكَانَ يَدْعُو وَيَنْظُرُ إِلَى السَّمَاءِ، فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى: ﴿قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ﴾ [البقرة: ١٤٤] إِلَى قَوْلِهِ: ﴿فَوَلُّوا وجُوهَكُمْ شَطْرَهُ﴾ [البقرة: ١٤٤] فَارْتَابَ مِنْ ذَلِكَ الْيَهُودُ، وَقَالُوا: ﴿مَا وَلَّاهُمْ عَنْ قِبْلَتِهِمْ الَّتِي كَانُوا عَلَيْهَا﴾ [البقرة: ١٤٢] فَأَنْزَلَ اللَّهُ عَزَّ وَجَلّ: ﴿قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ﴾ [البقرة: ١٤٢] وَقَالَ: ﴿ فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ﴾ [البقرة: 115]."],"takhrij":"صحيح: رواه ابن جرير في تفسيره (511)، وابن أبي حاتم في تفسيره (1/248)، والبيهقي (2246) كلّهم من طريق أبي صالح، عن معاوية ابن صالح، عن علي بن أبي طلحة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تحويل القبلة من بيت المقدس إلى بيت الله الحرام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Jarir (al-Tabari) in his Tafsir (2/450), Ibn Abi Hatim in his Tafsir (1/248)","chapter_en":"Reports about the change of the direction of prayer from Jerusalem to the Sacred House in Makkah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Abbas said: The first thing from the Qur’an to be abrogated was the direction of prayer. That was because the Messenger of Allah ﷺ migrated to Madinah, where most of its people were Jews. Allah commanded him to face Jerusalem, and the Jews rejoiced. The Messenger of Allah ﷺ faced it for more than ten months. But the Messenger of Allah ﷺ loved the direction of Abraham, so he would supplicate and look toward the sky. Then Allah, Blessed and Exalted, revealed: “We have certainly seen the turning of your face toward the heaven … so turn your face toward the Sacred Mosque … and wherever you are, turn your faces toward it” (Qur’an 2:144). They then doubted because of that and said: “What has turned them away from their direction of prayer which they used to face?” (Qur’an 2:142). So Allah revealed: “To Allah belong the east and the west” (Qur’an 2:142). And He said: “So wherever you turn, there is the Face of Allah” (Qur’an 2:115)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن جرير الطبري في تفسيره (511)، ابن أبي حاتم في تفسيره (1/248)."},{"num":1929,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَجُلا دَخَلَ الْمَسْجِدَ فَصَلَّى، ثُمَّ جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ الْحَدِيثَ، وَقَالَ: فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا قُمْتَ إِلَى الصَّلاةِ، فَأَسْبِغِ الْوُضُوءَ، ثُمَّ اسْتَقْبِلِ الْقِبْلَةَ فَكَبِّرْ... الْحَدِيثَ."],"takhrij":"متفق عليه: رواه البخاريّ في الأيمان والنذور (6667)، ومسلم في الصلاة (397: 46) كلاهما من حديث أبي أسامة، حدّثنا عبيدالله بن عمر، عن سعيد بن أبي سعيد، عن أبي هريرة، فذكره في حديث طويل وسيأتي.","grade":"متفق عليه","chapter_ar":"باب وجوب استقبال القبلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (6667), Muslim (397/46)","chapter_en":"Obligation of facing the direction of prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah reported that a man entered the mosque and prayed, then came and greeted the Prophet ﷺ… and in it the Messenger of Allah ﷺ said: “When you stand for prayer, perform ablution thoroughly, then face the direction of prayer, then say the opening declaration…” and so on in the hadith at length."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6667)، مسلم (397: 46)."},{"num":1930,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ قِبْلَةٌ."],"takhrij":"حسن: رواه الترمذي (342)، وابن ماجه (1011) كلاهما من حديث أبي معشر، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب وجوب استقبال القبلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tirmidhi (342), Ibn Majah (1011) — al-Tirmidhi said: “Hasan Sahih”","chapter_en":"Obligation of facing the direction of prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “What lies between the east and the west is a direction of prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (342)، ابن ماجه (1011)، وقال الترمذي: حسن صحيح."},{"num":1931,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ:أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا دَخَلَ الْبَيْتَ دَعَا فِي نَوَاحِيهِ كُلِّهَا، وَلَمْ يُصَلِّ فِيهِ، حَتَّى خَرَجَ فَلَمَّا خَرَجَ رَكَعَ فِي قُبُلِ الْبَيْتِ رَكْعَتَيْنِ، وَقَالَ: هَذِهِ الْقِبْلَةُ... (فَذَكَرَ الْحَدِيثَ)."],"takhrij":"صحيح: رواه مسلم في الحج (1330) من طريق محمد بن بكر، عن ابن جريج، قال: قلت لعطاء: أسمعت ابن عباس يقول: إنما أمرتم بالطواف، ولم تؤمروا بدخوله، قال: لم يكن ينهى عن دخوله، ولكني سمعتُ يقول: أخبرني أسامة بن زيد يقول فذكر الحديث.","grade":"صحيح","chapter_ar":"باب وجوب استقبال القبلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (1330)","chapter_en":"Obligation of facing the direction of prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Usamah ibn Zayd reported that when the Prophet ﷺ entered the House, he supplicated in all of its sides, and he did not pray inside it until he came out. When he came out, he prayed two units in front of the House and said: “This is the direction of prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1330)."},{"num":1932,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ يَقُولُ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ إِلَى الصَّلَاةِ يُكَبِّرُ حِينَ يَقُومُ، ثُمَّ يُكَبِّرُ حِينَ يَرْكَعُ، ثُمَّ يَقُولُ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ حِينَ يَرْفَعُ صُلْبَهُ مِنَ الرَّكْعَةِ، ثُمَّ يَقُولُ وَهُوَ قَائِمٌ رَبَّنَا لَكَ الْحَمْدُ، ثُمَّ يُكَبِّرُ حِينَ يَهْوِي، ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ، ثُمَّ يُكَبِّرُ حِينَ يَسْجُدُ، ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ، ثُمَّ يَفْعَلُ ذَلِكَ فِي الصَّلَاةِ كُلِّهَا حَتَّى يَقْضِيَهَا وَيُكَبِّرُ حِينَ يَقُومُ مِنَ الثِّنْتَيْنِ بَعْدَ الْجُلُوسِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (789)، ومسلم في الصلاة (392) كلاهما من طريق ابن شهاب، عن أبي بكر بن عبدالرحمن بن الحارث، أنه سمع أبا هريرة يقول فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صفة صلاة النبي ﷺ وافتتاحها بالتكبير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (789), Muslim (392)","chapter_en":"The description of the Prophet ﷺ’s prayer and beginning it with the opening declaration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: When the Messenger of Allah ﷺ stood for prayer, he would say “Allāhu akbar” as he stood, then say it when he bowed. Then he would say, “Allah hears the one who praises Him,” when he raised his back from bowing. Then while standing he would say, “Our Lord, to You belongs all praise.” Then he would say “Allāhu akbar” as he went down, and he would say it when he raised his head, and he would say it when he prostrated, and he would say it when he raised his head from prostration. He would do that throughout the whole prayer until he finished it, and he would say “Allāhu akbar” when he stood up after sitting following the two units."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (789)، مسلم (392)."},{"num":1933,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْعَرِيَّ جَمَعَ قَوْمَهُ فَقَالَ: يَا مَعْشَرَ الْأَشْعَرِيِّينَ اجْتَمِعُوا وَاجْمَعُوا نِسَاءَكُمْ، وَأَبْنَاءَكُمْ أُعَلِّمْكُمْ صَلَاةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّتِي صَلَّى لَنَا بِالْمَدِينَةِ فَاجْتَمَعُوا، وَجَمَعُوا نِسَاءَهُمْ وَأَبْنَاءَهُمْ، فَتَوَضَّأَ وَأَرَاهُمْ كَيْفَ يَتَوَضَّأُ، فَأَحْصَى الْوُضُوءَ إِلَى أَمَاكِنِهِ حَتَّى لَمَّا أَنْ فَاءَ الْفَيْءُ، وَانْكَسَرَ الظِّلُّ قَامَ، فَأَذَّنَ فَصَفَّ الرِّجَالَ فِي أَدْنَى الصَّفِّ، وَصَفَّ الْوِلْدَانَ خَلْفَهُمْ، وَصَفَّ النِّسَاءَ خَلْفَ الْوِلْدَانِ، ثُمَّ أَقَامَ الصَّلَاةَ، فَتَقَدَّمَ فَرَفَعَ يَدَيْهِ وَكَبَّرَ، فَقَرَأَ بِفَاتِحَةِ الْكِتَابِ وَسُورَةٍ يُسِرُّهُمَا، ثُمَّ كَبَّرَ فَرَكَعَ فَقَالَ: سُبْحَانَ اللهِ وَبِحَمْدِهِ ثَلَاثَ مِرَارٍ، ثُمَّ قَالَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، وَاسْتَوَى قَائِمًا، ثُمَّ كَبَّرَ، وَخَرَّ سَاجِدًا، ثُمَّ كَبَّرَ فَرَفَعَ رَأْسَهُ، ثُمَّ كَبَّرَ فَسَجَدَ، ثُمَّ كَبَّرَ فَانْتَهَضَ قَائِمًا، فَكَانَ تَكْبِيرُهُ فِي أَوَّلِ رَكْعَةٍ سِتَّ تَكْبِيرَاتٍ، وَكَبَّرَ حِينَ قَامَ إِلَى الرَّكْعَةِ الثَّانِيَةِ، فَلَمَّا قَضَى صَلَاتَهُ أَقْبَلَ إِلَى قَوْمِهِ بِوَجْهِهِ، فَقَالَ: احْفَظُوا تَكْبِيرِي، وَتَعَلَّمُوا رُكُوعِي وَسُجُودِي؛ فَإِنَّهَا صَلَاةُ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّتِي كَانَ يُصَلِّي لَنَا كَذَي السَّاعَةِ مِنَ النَّهَارِ ثُمَّ إِنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا قَضَى صَلَاتَهُ أَقْبَلَ إِلَى النَّاسِ بِوَجْهِهِ فَقَالَ: يَا أَيُّهَا النَّاسُ اسْمَعُوا وَاعْقِلُوا، وَاعْلَمُوا أَنَّ لِلَّهِ عِبَادًا لَيْسُوا بِأَنْبِيَاءَ وَلَا شُهَدَاءَ يَغْبِطُهُمْ، النَّبِيُّونَ وَالشُّهَدَاءُ عَلَى مَجَالِسِهِمْ وَقُرْبِهِمْ مِنَ اللهِ، فَجَثَى رَجُلٌ مِنَ الْأَعْرَابِ مِنْ قَاصِيَةِ النَّاسِ، وَأَلْوَى بِيَدِهِ إِلَى نَبِيِّ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا نَبِيَّ اللهِ نَاسٌ مِنَ النَّاسِ لَيْسُوا بِأَنْبِيَاءَ وَلَا شُهَدَاءَ يَغْبِطُهُمُ الْأَنْبِيَاءُ وَالشُّهَدَاءُ عَلَى مَجَالِسِهِمْ وَقُرْبِهِمْ مِنَ اللهِ انْعَتْهُمْ لَنَا حَلِّمْهُمْ لَنَا، يَعْنِي صِفْهُمْ لَنَا، شَكِّلْهُمْ لَنَا فَسُرَّ وَجْهُ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِسُؤَالِ الْأَعْرَابِيِّ فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هُمْ نَاسٌ مِنْ أَفْنَاءِ النَّاسِ وَنَوَازِعِ الْقَبَائِلِ لَمْ تَصِلْ بَيْنَهُمْ أَرْحَامٌ مُتَقَارِبَةٌ تَحَابُّوا فِي اللهِ وَتَصَافَوْا، يَضَعُ اللهُ لَهُمْ يَوْمَ الْقِيَامَةِ مَنَابِرَ مِنْ نُورٍ فَيُجْلِسُهُمْ عَلَيْهَا فَيَجْعَلُ وُجُوهَهُمْ نُورًا، وَثِيَابَهُمْ نُورًا، يَفْزَعُ النَّاسُ يَوْمَ الْقِيَامَةِ وَلَا يَفْزَعُونَ، وَهُمْ أَوْلِيَاءُ اللهِ الَّذِينَ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ."],"takhrij":"حسن: رواه الإمام أحمد (22906) عن أبي النضر، حدثنا عبد الحميد ابن بهرام الفَزاري، عن شهر بن حوشب، حدثنا عبدالرحمن بن غَنْم، أن أبا مالك الأشعري جمع قومه فذكر الحديث مثله.","grade":"حسن","chapter_ar":"باب ما جاء في صفة صلاة النبي ﷺ وافتتاحها بالتكبير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (22906)","chapter_en":"The description of the Prophet ﷺ’s prayer and beginning it with the opening declaration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Abu Malik al-Ash‘ari gathered his people and said: “O people of the Ash‘ariyyin, gather together, and gather your women and your children, and I will teach you the prayer of the Prophet ﷺ which he prayed for us in Madinah.” So they gathered, and they brought their women and children. He performed ablution and showed them how to perform it, completing it thoroughly in all its proper places. Then when the afternoon shade returned and the sun’s harshness eased, he stood and gave the call to prayer. He arranged the men in the front row, the boys behind them, and the women behind the boys. Then he began the prayer. He stepped forward, raised his hands, and said “Allāhu akbar”. He recited the Opening of the Book and another chapter quietly. Then he said “Allāhu akbar” and bowed, saying: “Glory be to Allah, and with His praise” three times. Then he said: “Allah hears the one who praises Him,” and stood upright. Then he said “Allāhu akbar” and fell into prostration. Then he said “Allāhu akbar” and raised his head, then said it again and prostrated, then said it again and rose to stand. In the first unit, his takbīrs in the first rakʿah amounted to six, and he also said “Allāhu akbar” when he rose for the second unit. When he finished the prayer, he turned to his people and said: “Memorize my takbīrs, and learn my bowing and prostration, for this is the prayer of the Messenger of Allah ﷺ which he used to pray for us at this time of day.” Then (in another part of the report) the Messenger of Allah ﷺ, when he finished his prayer, turned to the people and said: “O people, listen and understand, and know that Allah has servants who are neither prophets nor martyrs, yet the prophets and martyrs will envy them for their gatherings and their closeness to Allah.” A man from the desert Arabs, from the far edge of the crowd, knelt and motioned with his hand toward the Prophet ﷺ and said: “O Prophet of Allah, people who are neither prophets nor martyrs, yet the prophets and martyrs envy them for their gatherings and their closeness to Allah—describe them to us, make them clear to us.” The Prophet’s face brightened with joy at the Bedouin’s question, and he said: “They are people from various groups and scattered tribes, not connected by close kinship. They loved one another for Allah’s sake and were sincere with one another. Allah will place for them on the Day of Resurrection pulpits of light and seat them upon them, making their faces light and their clothes light. People will be terrified on the Day of Resurrection, but they will not be terrified. They are the allies of Allah—no fear will be upon them, nor will they grieve.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22906)."},{"num":1934,"demo":false,"sanad":"","matn":["عَنْ مُطَرِّفٍ قَالَ: صَلَّيْتُ أَنَا وَعِمْرَانُ صَلَاةً خَلْفَ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ، فَكَانَ إِذَا سَجَدَ كَبَّرَ، وَإِذَا رَفَعَ كَبَّرَ، وَإِذَا نَهَضَ مِنَ الرَّكْعَتَيْنِ كَبَّرَ، فَلَمَّا سَلَّمَ أَخَذَ عِمْرَانُ بِيَدِي، فَقَالَ: لَقَدْ صَلَّى بِنَا هَذَا صَلَاةَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ قَالَ: لَقَدْ ذَكَّرَنِي هَذَا صَلَاةَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (826) ومسلم في الصلاة (393) كلاهما من طريق حماد بن زيد قال: حدثنا غيلان بن جرير، عن مطرف فذكر مثله، ورواه أيضاً البخاري من وجه آخر عن أبي العلاء يزيد بن عبدالله بن الشخير أخى مُطَرّف، عن مطرف، عن عمران بن حصين، قال: صَلَّى مع علي رضي الله عنه بالبصرة، فقال: ذكَّرنا هذا الرجل صلاةً كنا نُصليها مع رسول الله صلى الله عليه وسلم فذكر أنه كان يُكبر كلما رفع، وكلما وضع (784).","grade":"متفق عليه","chapter_ar":"باب ما جاء في إتمام التكبيرات في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (826), Muslim (393)","chapter_en":"Completing the declarations of “Allah is the Greatest” throughout the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Mutarrif said: ‘Imran and I prayed behind ‘Ali ibn Abi Talib. He would say “Allāhu akbar” when he prostrated, and when he raised up, and when he rose after the two units. When he finished, ‘Imran took my hand and said: “He has just led us in the prayer of Muhammad ﷺ”—or he said: “He has reminded me of the prayer of Muhammad ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (826)، مسلم (393)."},{"num":1935,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّهُ كَانَ يُصَلِّي لَهُمْ فَيُكَبِّرُ كُلَّمَا خَفَضَ وَرَفَعَ فَإِذَا انْصَرَفَ، قَالَ: وَاللَّهِ إِنِّي لَأَشْبَهُكُمْ بِصَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (19) عن ابن شهاب، عن أبي سلمة ابن عبدالرحمن بن عوف، أن أبا هريرة كان يصلي بهم فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إتمام التكبيرات في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (19), al-Bukhari (785), Muslim (392)","chapter_en":"Completing the declarations of “Allah is the Greatest” throughout the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah used to lead them in prayer, saying “Allāhu akbar” every time he lowered himself and every time he rose. When he finished, he would say: “By Allah, I am the one among you whose prayer most resembles the prayer of the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (19)، البخاري (785)، مسلم (392)."},{"num":1936,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ الْحَارِثِ قَالَ: صَلَّى لَنَا أَبُو سَعِيدٍ فَجَهَرَ بِالتَّكْبِيرِ حِينَ رَفَعَ رَأْسَهُ مِنَ السُّجُودِ وَحِينَ سَجَدَ وَحِينَ رَفَعَ وَحِينَ قَامَ مِنَ الرَّكْعَتَيْنِ، وَقَالَ: هَكَذَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في الأذان (825) عن يحيى بن صالح، قال: حدثنا فليح بن سليمان، عن سعيد بن الحارث، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إتمام التكبيرات في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (825)","chapter_en":"Completing the declarations of “Allah is the Greatest” throughout the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Sa‘id ibn al-Harith said: Abu Sa‘id led us in prayer and recited “Allāhu akbar” out loud when he raised his head from prostration, when he prostrated, when he rose, and when he stood after the two units. He said: “This is how I saw the Prophet ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (825)."},{"num":1937,"demo":false,"sanad":"","matn":["عَنْ عِكْرِمَة قَالَ: رَأَيْتُ رَجُلًا عِنْدَ الْمَقَامِ يُكَبِّرُ فِي كُلِّ خَفْضٍ وَرَفْعٍ وَإِذَا قَامَ وَإِذَا وَضَعَ، فَأَخْبَرْتُ ابْنَ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ: أَوَلَيْسَ تِلْكَ صَلَاةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا أُمَّ لَكَ."],"takhrij":"صحيح: رواه البخاري في الأذان (787) عن عمرو بن عون، قال: حدثنا هُشيم، عن أبي بشر، عن عكرمة فذكره، ورواه أيضاً عن موسى بن إسماعيل، قال: أخبرنا همام، عن قتادة، عن عكرمة قال: صلَّيتُ خلف شيخٍ بمكة، فكبَّر ثنتين وعشرين تكبيرةً، فقلتُ لابن عباس: إنه أحمقُ. فقال: ثكِلتْك أمُّك، سنة أبي القاسم صلى الله عليه وسلم.","grade":"صحيح","chapter_ar":"باب ما جاء في إتمام التكبيرات في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (787)","chapter_en":"Completing the declarations of “Allah is the Greatest” throughout the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["‘Ikramah said: I saw a man by the Station (near the Ka‘bah) saying “Allāhu akbar” at every lowering and rising, whenever he stood and whenever he went down. I told Ibn ‘Abbas, and he said: “Is that not the prayer of the Prophet ﷺ—may you lose your mother!” (an Arabic expression used for emphasis, not intended literally)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (787)."},{"num":1938,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا افْتَتَحَ الصَّلَاةَ رَفَعَ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ رَفَعَهُمَا كَذَلِكَ أَيْضًا وَقَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ، وَكَانَ لَا يَفْعَلُ ذَلِكَ فِي السُّجُودِ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (16) عن ابن شهاب، عن سالم بن عبدالله، عن عبدالله بن عمر فذكر مثله، ولم يذكر مالك الرفع عند الركوع. ولكن رواه البخاري في الأذان (735) عن عبدالله بن مسلمة، عن مالك بإسناده: إن رسول الله صلى الله عليه وسلم كان يرفع يديه حَذْو منكبيه إذا افتتح الصلاة، وإذا كبَّر للركوع، وإذا رفع رأسه من الركوع رفعهما كذلك أيضاً....","grade":"متفق عليه","chapter_ar":"باب رفع اليدين عند الركوع وعند رفع الرأس منه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (16), al-Bukhari (735), Muslim (390)","chapter_en":"Raising the hands when bowing and when rising from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Ibn ‘Umar said: When the Messenger of Allah ﷺ began the prayer, he raised his hands level with his shoulders. When he raised his head from bowing, he raised them likewise and said: “Allah hears the one who praises Him. Our Lord, and to You belongs all praise.” He did not do that in prostration."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (16)، البخاري (735)، مسلم (390)."},{"num":1939,"demo":false,"sanad":"","matn":["عَنْ أَبِي قِلَابَةَ، أَنَّهُ رَأَى مَالِكَ بْنَ الْحُوَيْرِثِ إِذَا صَلَّى كَبَّرَ وَرَفَعَ يَدَيْهِ، وَإِذَا أَرَادَ أَنْ يَرْكَعَ رَفَعَ يَدَيْهِ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ رَفَعَ يَدَيْهِ، وَحَدَّثَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَنَعَ هَكَذَا."],"takhrij":"متفق عليه: رواه البخاري في الأذان (737)، ومسلم في الصلاة (391) كلاهما من طريق خالد بن عبدالله، عن خالد (الحذاء) عن أبي قلابة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب رفع اليدين عند الركوع وعند رفع الرأس منه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (737), Muslim (391)","chapter_en":"Raising the hands when bowing and when rising from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Abu Qilabah said that he saw Malik ibn al-Huwayrith: when he prayed, he would say the opening declaration and raise his hands; when he intended to bow, he would raise his hands; and when he raised his head from bowing, he would raise his hands. And he narrated that the Messenger of Allah ﷺ did the same."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (737)، مسلم (391)."},{"num":1940,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ قَالَ: أَنَا كُنْتُ أَحْفَظَكُمْ لِصَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَيْتُهُ إِذَا كَبَّرَ جَعَلَ يَدَيْهِ حِذَاءَ مَنْكِبَيْهِ، وَإِذَا رَكَعَ أَمْكَنَ يَدَيْهِ مِنْ رُكْبَتَيْهِ ثُمَّ هَصَرَ ظَهْرَهُ، فَإِذَا رَفَعَ رَأْسَهُ اسْتَوَى حَتَّى يَعُودَ كُلُّ فَقَارٍ مَكَانَهُ، فَإِذَا سَجَدَ وَضَعَ يَدَيْهِ غَيْرَ مُفْتَرِشٍ وَلَا قَابِضِهِمَا وَاسْتَقْبَلَ بِأَطْرَافِ أَصَابِعِ رِجْلَيْهِ الْقِبْلَةَ، فَإِذَا جَلَسَ فِي الرَّكْعَتَيْنِ جَلَسَ عَلَى رِجْلِهِ الْيُسْرَى وَنَصَبَ الْيُمْنَى، وَإِذَا جَلَسَ فِي الرَّكْعَةِ الْآخِرَةِ قَدَّمَ رِجْلَهُ الْيُسْرَى وَنَصَبَ الْأُخْرَى وَقَعَدَ عَلَى مَقْعَدَتِهِ."],"takhrij":"صحيح: رواه البخاري في الأذان (828) قال: حدثنا يحيى بن بكير، قال: حدثنا الليثُ، عن خالد (هو ابن يزيد الجمحمي المصري) عن سعيد (ابن أبي هلال) عن محمد بن عمرو بن حَلْحَلَة، عن محمد بن عمرو بن عطاء، وحدثنا الليث عن يزيد بن أبي حبيب ويزيد بن محمد، عن محمد بن عمرو بن حَلْحَلة، عن محمد بن عمرو بن عطاء أنه كان جالساً مع نفر من أصحاب النبي صلى الله عليه وسلم، فذكرنا صلاة النبي صلى الله عليه وسلم فقال أبو حميد الساعدي: فذكر الحديث هكذا مختصراً.","grade":"صحيح","chapter_ar":"باب رفع اليدين عند الركوع وعند رفع الرأس منه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (828)","chapter_en":"Raising the hands when bowing and when rising from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Abu Humayd al-Sa‘idi said: I know the prayer of the Messenger of Allah ﷺ best among you. I saw that when he said the opening declaration, he placed his hands level with his shoulders. When he bowed, he held his hands firmly on his knees and kept his back straight. When he raised his head, he stood upright until every vertebra returned to its place. When he prostrated, he placed his hands without spreading them flat nor clenching them, and he faced the tips of his toes toward the direction of prayer. When he sat after the two units, he sat on his left foot and kept his right foot upright. When he sat in the final unit, he brought his left foot forward, kept the other upright, and sat on his buttocks."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (828)."},{"num":1941,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَبَّرَ لِلصَّلَاةِ جَعَلَ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ، وَإِذَا رَكَعَ فَعَلَ مِثْلَ ذَلِكَ، وَإِذَا رَفَعَ لِلسُّجُودِ فَعَلَ مِثْلَ ذَلِكَ، وَإِذَا قَامَ مِنَ الرَّكْعَتَيْنِ فَعَلَ مِثْلَ ذَلِكَ."],"takhrij":"صحيح: رواه أبو داود (738) حدثنا عبد الملك بن شُعيب بن الليث، حدثني أبي، عن جدي، عن يحيى بن أيوب، عن عبد الملك بن عبدالعزيز بن جريج، عن ابن شهاب، عن أبي بكر بن عبدالرحمن بن الحارث بن هشام، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب رفع اليدين عند الركوع وعند رفع الرأس منه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (738); Ibn Khuzaymah authenticated it (694)","chapter_en":"Raising the hands when bowing and when rising from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: When the Messenger of Allah ﷺ said “Allāhu akbar” for the prayer, he placed his hands level with his shoulders. When he bowed, he did likewise; when he raised his hands for prostration, he did likewise; and when he stood after the two units, he did likewise."]},"buhuth":{"en":["Ibn Mājah (860) also narrated: “I saw the Messenger of Allah ﷺ raise his hands level with his shoulders when he began the prayer, when he bowed, and when he prostrated.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (738)، وصححه ابن خزيمة (694)."},{"num":1942,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: قُلْتُ لَأَنْظُرَنَّ إِلَى صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَيْفَ يُصَلِّي، قَالَ: فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَقْبَلَ الْقِبْلَةَ فَكَبَّرَ فَرَفَعَ يَدَيْهِ حَتَّى حَاذَتَا أُذُنَيْهِ، ثُمَّ أَخَذَ شِمَالَهُ بِيَمِينِهِ، فَلَمَّا أَرَادَ أَنْ يَرْكَعَ رَفَعَهُمَا مِثْلَ ذَلِكَ ثُمَّ وَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ، فَلَمَّا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ رَفَعَهُمَا مِثْلَ ذَلِكَ، فَلَمَّا سَجَدَ وَضَعَ رَأْسَهُ بِذَلِكَ الْمَنْزِلِ مِنْ بَيْنِ يَدَيْهِ، ثُمَّ جَلَسَ فَافْتَرَشَ رِجْلَهُ الْيُسْرَى وَوَضَعَ يَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى وَحَدَّ مِرْفَقَهُ الْأَيْمَنَ عَلَى فَخِذِهِ الْيُمْنَى وَقَبَضَ ثِنْتَيْنِ وَحَلَّقَ حَلْقَةً، وَرَأَيْتُهُ يَقُولُ هَكَذَا: وَحَلَّقَ بِشْرٌ الْإِبْهَامَ وَالْوُسْطَى وَأَشَارَ بِالسَّبَّابَةِ."],"takhrij":"حسن: رواه أبو داود (726) واللفظ له، والنسائي (1267)، وابن ماجه (867) كلهم من طريق بِشر بن المفضل، قال: حدثنا عاصم بن كليب، عن أبيه، عن وائل بن حجر فذكره. وسيأتي التخريج مفصلاً في باب وضع اليمين على الشمال.","grade":"حسن","chapter_ar":"باب رفع اليدين عند الركوع وعند رفع الرأس منه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (726 — wording his), al-Nasa’i (1265), Ibn Majah (867)","chapter_en":"Raising the hands when bowing and when rising from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Wa’il ibn Hujr said: I said, “I will watch how the Messenger of Allah ﷺ prays.” The Messenger of Allah ﷺ stood and faced the direction of prayer and said “Allāhu akbar”, raising his hands until they were level with his ears. Then he held his left hand with his right. When he intended to bow, he raised them likewise, then placed his hands on his knees. When he raised his head from bowing, he raised them likewise. When he prostrated, he placed his head in that position in front of his hands. Then he sat and spread his left foot (sat on it), placed his left hand on his left thigh, rested his right elbow on his right thigh, folded two fingers and formed a ring. He demonstrated it like this; Bishr formed a ring with the thumb and middle finger and pointed with the index finger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (726، واللفظ له)، النسائي (1267)، ابن ماجه (867)."},{"num":1943,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ كَانَ إِذَا افْتَتَحَ الصَّلَاةَ رَفَعَ يَدَيْهِ، وَإِذَا رَكَعَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ فَعَلَ مِثْلَ ذَلِكَ، وَيَقُولُ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَلَ مِثْلَ ذَلِكَ.","وَرَفَعَ إِبْرَاهِيمُ بْنُ طَهْمَانَ (أَحَدُ الرُّوَاةِ) يَدَيْهِ إِلَى أُذُنَيْهِ."],"takhrij":"حسن: رواه ابن ماجه (868) عن محمد بن يحيى، قال: حدّثنا أبو حذيفة، قال: حدّثنا إبراهيم بن طهمان، عن أبي الزّبير، أنّ جابر بن عبدالله كان إذا افتتح الصّلاة، فذكره. وإسناده حسن من أجل أبي الزبير","grade":"حسن","chapter_ar":"باب رفع اليدين عند الركوع وعند رفع الرأس منه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (868)","chapter_en":"Raising the hands when bowing and when rising from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported: He would raise his hands when he began the prayer, when he bowed, and when he raised his head from bowing, and he would say: “I saw the Messenger of Allah ﷺ do the same.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (868)."},{"num":1944,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرٍ الصِّدِّيقِ قَالَ: صَلَّيْتُ خَلْفَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَانَ يَرْفَعً يَدَيْهِ إِذَا افْتَتَحَ الصَّلَاةَ وَإِذَا رَكَعَ وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ."],"takhrij":"حسن: رواه البيهقي (2519) قال: أخبرنا أبو عبدالله الحافظ، ثنا أبو عبدالله محمد بن عبدالله الصفار الزاهد، إملاء من أصل كتابه، قال: قال أبو إسمعيل محمد بن إسمعيل السلمى: صليت خلف أبى النعمان محمد بن الفضل فرفع يديه حين افتتح الصلاة وحين ركع وحين رفع راسه من الركوع فسألته عن ذلك، فقال: صليت خلف حماد بن زيد فرفع يديه حين افتتح الصلاة وحين ركع وحين رفع رأسه من الركوع، فسألته عن ذلك، فقال: صليت خلف أيوب السختيانى فكان يرفع يديه إذا افتتح الصلاة وإذا ركع وإذا رفع رأسه من الركوع، فسألته فقال: رأيت عطاء بن أبى رباح يرفع يديه إذا افتتح الصلاة وإذا ركع وإذا رفع رأسه من الركوع، فسألته فقال: صليت خلف عبدالله بن الزبير فكان يرفع يديه إذا افتتح الصلاة وإذا ركع وإذا رفع رأسه من الركوع فسألته، فقال عبدالله بن الزبير: صليت خلف أبى بكر الصديق رضى الله عنه فكان يرفع يديه إذا افتتح الصلاة وإذا ركع وإذا رفع رأسه من الركوع. وقال أبو بكر: صليت خلف رسول الله صلى الله عليه وسلم ... فذكره. قال البيهقي: رواته ثقات.","grade":"حسن","chapter_ar":"باب رفع اليدين عند الركوع وعند رفع الرأس منه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Bayhaqi (2/73)","chapter_en":"Raising the hands when bowing and when rising from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Abu Bakr al-Siddiq said: I prayed behind the Messenger of Allah ﷺ, and he used to raise his hands when he began the prayer, when he bowed, and when he raised his head from bowing."]}},"tuhfa":{},"full":1,"tks":"حسن: رواه البيهقي (2519)."},{"num":1945,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ الْمَكْتُوبَةِ كَبَّرَ وَرَفَعَ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ، وَيَصْنَعُ مِثْلَ ذَلِكَ إِذَا قَضَى قِرَاءَتَهُ وَأَرَادَ أَنْ يَرْكَعَ، وَيَصْنَعُهُ إِذَا رَفَعَ مِنَ الرُّكُوعِ، وَلَا يَرْفَعُ يَدَيْهِ فِي شَيْءٍ مِنْ صَلَاتِهِ وَهُوَ قَاعِدٌ وَإِذَا قَامَ مِنَ السَّجْدَتَيْنِ رَفَعَ يَدَيْهِ كَذَلِكَ وَكَبَّرَ."],"takhrij":"حسن: رواه أبو داود (744)، والترمذي (3423)، وابن ماجه (864) كلهم عن طريق سليمان بن داود الهاشمي، ثنا عبدالرحمن بن أبي الزناد، عن موسى بن عقبة، عن عبدالله بن فضل بن ربيعة بن الحارث بن عبد المطلب، عن عبدالرحمن بن الأعرج، عن عبيدالله بن أبي رافع، عن علي بن أبي طالب فذكر الحديث مثله واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب رفع اليدين عند الركوع وعند رفع الرأس منه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (744), al-Tirmidhi (3423), Ibn Majah (864) — al-Tirmidhi said: “Hasan Sahih”","chapter_en":"Raising the hands when bowing and when rising from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["‘Ali ibn Abi Talib reported from the Messenger of Allah ﷺ that when he stood for an obligatory prayer, he would say “Allāhu akbar” and raise his hands level with his shoulders. He would do likewise when he finished his recitation and intended to bow, and he would do likewise when he rose from bowing. He would not raise his hands in any part of the prayer while seated. When he rose from the two prostrations, he would raise his hands likewise and say “Allāhu akbar.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (744)، الترمذي (3423)، ابن ماجه (864)، وقال الترمذي: حسن صحيح."},{"num":1946,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا لِي أَرَاكُمْ رَافِعِي أَيْدِيكُمْ، كَأَنَّهَا أَذْنَابُ خَيْلٍ شُمْسٍ، اسْكُنُوا فِي الصَّلَاةِ... (فَذَكَرَ الْحَدِيثَ)."],"takhrij":"صحيح: رواه مسلم في الصلاة (430) من طرق عن أبي معاوية، عن الأعمش، عن المسيب بن رافع، عن تميم بن طَرفة، عن جابر بن سمرة، فذكره.","grade":"صحيح","chapter_ar":"باب من قال: لا يُسنّ رفع اليدين عند الركوع وعند الرفع منه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (430)","chapter_en":"Those who said it is not Sunnah to raise the hands at bowing and when rising from it","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn Samurah said: The Messenger of Allah ﷺ came out to us and said: “Why do I see you raising your hands as if they were the tails of skittish horses? Be still in the prayer.”"]},"buhuth":{"en":["This was not intended as a prohibition of raising the hands at bowing and rising from it, because its explanation is narrated in Sahih Muslim itself. Jabir ibn Samurah said: When we prayed with the Messenger of Allah ﷺ, we would say: “Peace be upon you and Allah’s mercy; peace be upon you and Allah’s mercy,” and we would gesture to both sides. The Messenger of Allah ﷺ said: “Why do you gesture with your hands as if they were the tails of skittish horses? It is enough for one of you to place his hand on his thigh, then give greetings to his brother on his right and left.”","He also said: I prayed with the Messenger of Allah ﷺ, and when we gave greetings we used to gesture with our hands, saying: “Peace be upon you, peace be upon you.” The Messenger of Allah ﷺ looked at us and said: “What is wrong with you, gesturing with your hands as if they were the tails of skittish horses? When one of you gives greetings, let him turn to his companion and do not gesture with his hand.”","“Shumus” (with the first letter vowelled and the second silent) is the plural of “shamus”: an animal that is restless and does not stay still due to its agitation and sharpness.","As for what is narrated from ʿAbdullāh ibn Masʿūd—that the Prophet ﷺ stood, said “Allāhu akbar”, raised his hands, and then did not repeat it; and in another wording, that he did not raise his hands except at the beginning—all of that is erroneous. What is authentic from his report is that the Prophet ﷺ began the prayer and raised his hands, then bowed, joined his hands together, and placed them between his knees.","This is because a group of scholars narrated it from ʿĀṣim ibn Kulayb, from ʿAbd al-Raḥmān ibn al-Aswad, from ʿAlqamah, from ʿAbdullāh ibn Masʿūd, and none of them mentioned “then he did not repeat it” except Sufyān al-Thawrī. He erred in this, as Aḥmad, al-Bukhārī, Abū Dāwūd, Abū Zurʿah, Ibn ʿAbd al-Barr, al-Bayhaqī, and others stated. This is not a case of an addition by a trustworthy narrator; rather, it is a contradiction of a group of trustworthy narrators."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (430)."},{"num":1947,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْكُتُ بَيْنَ التَّكْبِيرِ وَبَيْنَ الْقِرَاءَةِ إِسْكَاتَةً، قَالَ: أَحْسِبُهُ قَالَ: هُنَيَّةً، فَقُلْتُ: بِأَبِي وَأُمِّي يَا رَسُولَ اللَّهِ إِسْكَاتُكَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ مَا تَقُولُ ؟ قَالَ: أَقُولُ اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (744)، ومسلم في المساجد (598) كلاهما من طريق عبد الواحد بن زياد، قال: حدثنا عُمارة بن القَعْقاع، قال: حدثنا أبو زرعة، قال: حدثنا أبو هريرة، فذكر الحديث، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما يستفتح به الصلاة من الأدعية","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (744) — wording his; Muslim (598)","chapter_en":"Supplications with which one begins the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ would pause briefly between saying “Allāhu akbar” and the recitation. I said: “May my father and mother be sacrificed for you, O Messenger of Allah—what do you say during your pause between saying “Allāhu akbar” and the recitation?” He said: “O Allah, distance me from my sins as You have distanced the east from the west. O Allah, cleanse me of my sins as a white garment is cleansed of filth. O Allah, wash away my sins with water, snow, and hail.”"]},"buhuth":{"en":["Muslim’s wording includes: “Wash me of my sins with snow, water, and hail.” Muslim also adds that when he rose for the second unit, he began the recitation with “All praise is for Allah, Lord of all worlds,” and he did not pause."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10993],"tks":"متفق عليه: رواه البخاري (744)، واللفظ له، مسلم (598)."},{"num":1948,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ يَقُولُ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا نَهَضَ مِنَ الرَّكْعَةِ الثَّانِيَةِ، اسْتَفْتَحَ الْقِرَاءَةَ بِـــــ ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾، وَلَمْ يَسْكُتْ."],"takhrij":"صحيح: رواه مسلم في المساجد (599) معلقاً قال: وحُدِّثتُ عن يحيى بن حسان ويونس المؤدِّب وغيرهما قالوا: حدثنا عبد الواحد بن زياد قال: حدثنا عمارةُ بن القعقاع، حدثنا أبو زرعة. قال: سمعت أبا هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما يستفتح به الصلاة من الأدعية","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (599)","chapter_en":"Supplications with which one begins the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah said: When the Messenger of Allah ﷺ rose for the second unit, he would begin the recitation with “All praise is for Allah, Lord of all worlds,” and he would not pause."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (599)."},{"num":1949,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ قَالَ: وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، ﴿إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ، وَبِذَلِكَ أُمِرْتُ وَأَنَا﴾ [سورة الأنعام: 162، 163] مِنَ الْمُسْلِمِينَ، اللَّهُمَّ أَنْتَ الْمَلِكُ، لَا إِلَهَ إِلَّا أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، وَاهْدِنِي لِأَحْسَنِ الأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ، لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ كُلُّهُ فِي يَدَيْكَ، وَالشَّرُّ لَيْسَ إِلَيْكَ، أَنَا بِكَ وَإِلَيْكَ تَبَارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ.","وَإِذَا رَكَعَ قَالَ: اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي وَبَصَرِي، وَمُخِّي وَعَظْمِي وَعَصَبِي.","وَإِذَا رَفَعَ قَالَ: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ.","وَإِذَا سَجَدَ قَالَ: اللَّهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ.","ثُمَّ يَكُونُ مِنْ آخِرِ مَا يَقُولُ بَيْنَ التَّشَهُّدِ وَالتَّسْلِيمِ: اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (771) عن محمد بن أبي بكر المقدمي، ثنا يوسف الماجشون، حدثني أبي، عن عبدالرحمن الأعرج، عن عبيدالله بن أبي رافع، عن علي بن أبي طالب، فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما يستفتح به الصلاة من الأدعية","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (771)","chapter_en":"Supplications with which one begins the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["‘Ali ibn Abi Talib reported that the Messenger of Allah ﷺ used to say when he stood for prayer: “I have turned my face toward the One who created the heavens and the earth, inclining to truth, and I am not among those who associate partners with Allah. Indeed, my prayer, my sacrifice, my living, and my dying are for Allah, Lord of all worlds. He has no partner; with that I have been commanded, and I am among those who submit. O Allah, You are the King; there is no god worthy of worship except You. You are my Lord and I am Your servant. I have wronged myself and admitted my sin, so forgive me all my sins, for none forgives sins except You. Guide me to the best character—none guides to the best of it except You—and turn away from me its bad traits—none turns them away except You. Here I am at Your service and in Your obedience; all good is in Your hands, and evil is not attributed to You. I rely on You and return to You. Blessed and Exalted are You; I seek Your forgiveness and I repent to You.” When he bowed he said: “O Allah, to You I have bowed; in You I have believed; and to You I have submitted. My hearing, my sight, my mind, my bones, and my nerves have humbled themselves to You.”","When he rose he said: “O Allah, our Lord, to You belongs all praise—filling the heavens, filling the earth, filling what is between them, and filling whatever You will of anything thereafter.”","When he prostrated he said: “O Allah, to You I have prostrated; in You I have believed; and to You I have submitted. My face has prostrated to the One who created it and formed it, and split open its hearing and its sight. Blessed is Allah, the best of creators.”","Then among the last things he would say between the testimony of faith and the closing greetings was: “O Allah, forgive me what I have sent ahead and what I have left behind, what I have concealed and what I have made public, what I have exceeded in, and what You know better than I. You are the One who brings forward and the One who delays. There is no god worthy of worship except You.”"]},"buhuth":{"en":["The phrase “I rely on You and return to You” means: I seek refuge with You, I belong to You, and my success is by You."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10991],"tks":"صحيح: رواه مسلم (771)."},{"num":1950,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ رَجُلًا جَاءَ فَدَخَلَ الصَّفَّ، وَقَدْ حَفَزَهُ النَّفَسُ فَقَالَ: الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، فَلَمَّا قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ قَالَ: أَيُّكُمُ الْمُتَكَلِّمُ بِالْكَلِمَاتِ ؟ فَأَرَمَّ الْقَوْمُ، فَقَالَ: أَيُّكُمُ الْمُتَكَلِّمُ بِهَا؟ فَإِنَّهُ لَمْ يَقُلْ بَأْسًا، فَقَالَ رَجُلٌ: جِئْتُ وَقَدْ حَفَزَنِي النَّفَسُ فَقُلْتُهَا . فَقَالَ: لَقَدْ رَأَيْتُ اثْنَيْ عَشَرَ مَلَكًا يَبْتَدِرُونَهَا، أَيُّهُمْ يَرْفَعُهَا."],"takhrij":"صحيح: رواه مسلم في المساجد (600) من حديث قتاده وثابت وحميد، عن أنس فذكره. وقوله: فأرمَّ القومُ أي سكتوا.","grade":"صحيح","chapter_ar":"باب ما يستفتح به الصلاة من الأدعية","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (600)","chapter_en":"Supplications with which one begins the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Anas reported that a man came and entered the row while he was short of breath, and he said: “All praise is for Allah—abundant, pure, and blessed.” When the Messenger of Allah ﷺ finished his prayer, he said: “Which of you spoke those words?” The people remained silent, so he said: “Which of you said them? He has not said anything wrong.” A man said: “I came while I was short of breath, so I said them.” He said: “I saw twelve angels racing to it—each of them wanting to be the one to raise it up.”"]},"buhuth":{"ar":["وقوله: «فأرمَّ القوم» أي: سكتوا."],"en":["“The people remained silent” means: they became quiet."]}},"tuhfa":{},"full":1,"rep":[10994],"tks":"صحيح: رواه مسلم (600)."},{"num":1951,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: بَيْنَمَا نَحْنُ نُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ قَالَ رَجُلٌ مِنَ الْقَوْمِ: اللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ الْقَائِلُ كَلِمَةَ كَذَا وَكَذَا ؟ قَالَ رَجُلٌ مِنِ الْقَوْمِ: أَنَا يَا رَسُولَ اللَّهِ! قَالَ: عَجِبْتُ لَهَا، فُتِحَتْ لَهَا أَبْوَابُ السَّمَاءِ."],"takhrij":"صحيح: رواه مسلم في المساجد (601) من حديث أبي الزبير، عن عون ابن عبدالله بن عتبة، عن ابن عمر فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما يستفتح به الصلاة من الأدعية","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (601)","chapter_en":"Supplications with which one begins the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Ibn ‘Umar said: While we were praying with the Messenger of Allah ﷺ, a man from the people said: “Allah is the Greatest—greatly. And all praise is for Allah—abundantly. And glory be to Allah in the morning and in the evening.” The Messenger of Allah ﷺ said: “Who said such-and-such words?” A man said: “I did, O Messenger of Allah.” He said: “I was amazed by it; the gates of heaven were opened for it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (601)."},{"num":1952,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ وَعِمْرَانَ بْنِ حُصَيْنٍ أَنَّهُمَا تَذَاكَرَا، فَحَدَّثَ سَمُرَةُ بْنُ جُنْدُبٍ أَنَّهُ حَفِظَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَكْتَتَيْنِ: سَكْتَةً إِذَا كَبَّرَ وَسَكْتَةً إِذَا فَرَغَ مِنْ قِرَاءَةِ ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ﴾ [ سورة الفاتحة: 7]، فَحَفِظَ ذَلِكَ سَمُرَةُ وَأَنْكَرَ عَلَيْهِ عِمْرَانُ بْنُ حُصَيْنٍ، فَكَتَبَا فِي ذَلِكَ إِلَى أُبَيِّ بْنِ كَعْبٍ، فَكَانَ فِي كِتَابِهِ إِلَيْهِمَا أَوْ فِي رَدِّهِ عَلَيْهِمَا: أَنَّ سَمُرَةَ قَدْ حَفِظَ."],"takhrij":"صحيح: رواه أبو داود (779)، واللفظ له، والترمذي (251)، وابن ماجه (844،845) كلهم من طرق عن سعيد، عن قتادة، عن الحسن، عن سمرة.","grade":"صحيح","chapter_ar":"باب ما يستفتح به الصلاة من الأدعية","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (779) — wording his; al-Tirmidhi (251); Ibn Majah (844–845)","chapter_en":"Supplications with which one begins the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Samurah ibn Jundub and ‘Imran ibn Husayn discussed the matter. Samurah said that he had memorized from the Messenger of Allah ﷺ two brief pauses: a pause after saying “Allāhu akbar”, and a pause after finishing the recitation of “not those who earned anger, nor those who went astray.” Samurah retained this, while ‘Imran ibn Husayn objected to it, so they wrote to Ubayy ibn Ka‘b about it. In his letter back to them—or in his reply—he affirmed that Samurah had indeed preserved it correctly."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (779)، واللفظ له، الترمذي (251)، ابن ماجه (844–845)."},{"num":1953,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَفْتَحَ الصَّلَاةَ كَبَّر،َ ثُمَّ ﴿قَالَ: إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا﴾ [سورة الأنعام: 162، 163] مِنْ الْمُسْلِمِينَ، اللَّهُمَّ اهْدِنِي لِأَحْسَنِ الْأَعْمَالِ وَأَحْسَنِ الْأَخْلَاقِ، لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَقِنِي سَيِّئَ الْأَعْمَالِ وَسَيِّئَ الْأَخْلَاقِ، لَا يَقِي سَيِّئَهَا إِلَّا أَنْتَ."],"takhrij":"صحيح: رواه النسائي (896) عن عمرو بن عثمان بن سعيد، قال: حدثنا شريح بن يزيد الحضرمي، قال: أخبرني شعيب بن أبي حمزة، قال: أخبرني محمد بن المنكدر، عن جابر بن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما يستفتح به الصلاة من الأدعية","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (896)","chapter_en":"Supplications with which one begins the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: When the Prophet ﷺ began the prayer, he would say “Allāhu akbar”, then say: “Indeed, my prayer, my sacrifice, my living, and my dying are for Allah, Lord of all worlds. He has no partner; with that I have been commanded, and I am among those who submit. O Allah, guide me to the best deeds and the best character—none guides to the best of them except You—and protect me from bad deeds and bad character—none protects from their evil except You.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10992],"tks":"صحيح: رواه النسائي (896)."},{"num":1954,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ أَنَّهُ قَالَ: كَانَ النَّاسُ يُؤْمَرُونَ، أَنْ يَضَعَ الرَّجُلُ الْيَدَ الْيُمْنَى عَلَى ذِرَاعِهِ الْيُسْرَى فِي الصَّلَاةِ.","قَالَ أَبُو حَازِمٍ: لَا أَعْلَمُ إِلَّا أَنَّهُ يَنْمِي ذَلِكَ."],"takhrij":"صحيح: رواه مالك في قصر الصلاة (47) عن أبي حازم بن دينار، عن سهل بن سعد فذكره. ومن طريقه أخرجه البخاريّ (740).","grade":"صحيح","chapter_ar":"باب ما جاء في وضع اليمين على الشمال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (47), al-Bukhari (740)","chapter_en":"Reports about placing the right hand over the left","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Sahl ibn Sa‘d said: The people were commanded that a man should place his right hand on his left forearm in prayer. Abu Hazim said: I only know that he attributed that (report) upward."]},"buhuth":{"en":["The statement “the people were commanded” has the ruling of being traced back to the Prophet ﷺ, because it is understood that the one commanding them was the Prophet. The phrase “he attributed it upward” means he ascribed it to the Prophet. In hadith terminology, when a narrator says “he attributed it,” it means he is raising it back to the Prophet even if he does not state that explicitly.","The phrase “on his left forearm” implies placing the hands over the upper body (over the chest). The compiler states that this is established."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (47)، البخاري (740)."},{"num":1955,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، رَفَعَ يَدَيْهِ حِينَ دَخَلَ فِي الصَّلَاةِ كَبَّرَ، وَصَفَ هَمَّامٌ حِيَالَ أُذُنَيْهِ، ثُمَّ الْتَحَفَ بِثَوْبِهِ، ثُمَّ وَضَعَ يَدَهُ الْيُمْنَى عَلَى الْيُسْرَى، فَلَمَّا أَرَادَ أَنْ يَرْكَعَ، أَخْرَجَ يَدَيْهِ مِنَ الثَّوْبِ، ثُمَّ رَفَعَهُمَا، ثُمَّ كَبَّرَ فَرَكَعَ، فَلَمَّا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَفَعَ يَدَيْهِ، فَلَمَّا سَجَدَ، سَجَدَ بَيْنَ كَفَّيْهِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (401) عن زهير بن حرْب، حدثنا عفان، حدثنا همَّام، حدثنا محمد بن جحادة، حدثني عبد الجبار بن وائل، عن علقمة بن وائل ومولى لهم، أنهما حدَّثاه عن أبيه وائل بن حُجْر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في وضع اليمين على الشمال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (401)","chapter_en":"Reports about placing the right hand over the left","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Wa’il ibn Hujr said that he saw the Prophet ﷺ raise his hands when he entered the prayer. He said “Allāhu akbar”—and Hammam described the hands as being level with the ears—then he wrapped himself in his garment, then he placed his right hand over his left. When he intended to bow, he brought his hands out from the garment and raised them, then he said “Allāhu akbar” and bowed. When he said: “Allah hears the one who praises Him,” he raised his hands. When he prostrated, he prostrated between his palms."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (401)."},{"num":1956,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، أَنَّهُ كَانَ يُصَلِّي فَوَضَعَ يَدَهُ الْيُسْرَى عَلَى الْيُمْنَى، فَرَآهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَضَعَ يَدَهُ الْيُمْنَى عَلَى الْيُسْرَى."],"takhrij":"حسن: أخرجه أبو داود (755)، والنسائي (888)، وابن ماجه (811) كلهم من طريق هشيم بن بشير، عن الحجاج بن أبي زينب، قال: سمعتُ أبا عثمان يحدث عن ابن مسعود قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في وضع اليمين على الشمال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (755), al-Nasa’i (888), Ibn Majah (811)","chapter_en":"Reports about placing the right hand over the left","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Ibn Mas‘ud used to pray and placed his left hand over his right. The Prophet ﷺ saw him and placed his right hand over his left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (755)، النسائي (888)، ابن ماجه (811)."},{"num":1957,"demo":false,"sanad":"","matn":["عَنِ الْحَارِثِ بْنِ غُطَيْفٍ أَوْ غُطَيْفِ بْنِ الْحَارِثِ، قَالَ: مَا نَسِيتُ مِنَ الْأَشْيَاءِ لَمْ أَنْسَ أَنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاضِعًا يَمِينَهُ عَلَى شِمَالِهِ فِي الصَّلَاةِ."],"takhrij":"حسن: رواه أحمد (16968 ، 22497)، والطبراني في الكبير (3400)، وابن قانع في معجم الصحابة (2/316)، وابن أبي شيبة (3933) كلهم من طريق معاوية بن صالح، عن يونس بن سيف، عن الحارث بن غُطيف، أو غُطيف بن الحارث فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في وضع اليمين على الشمال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (22497, 16968), al-Tabarani in al-Kabir (3/312)","chapter_en":"Reports about placing the right hand over the left","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Al-Harith ibn Ghutayf—or Ghutayf ibn al-Harith—said: Of all the things I may forget, I have not forgotten that I saw the Messenger of Allah ﷺ placing his right hand over his left in prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22497، 16968)، الطبراني في المعجم الكبير (3400)."},{"num":1958,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّا مَعَاشِرَ الْأَنْبِيَاءِ أُمِرْنَا أَنْ نُعَجِّلَ الْإِفْطَارَ، وَأَنْ نُؤَخِّرَ السَّحُورَ، وَأَنْ نَضْرِبَ بِأَيْمَانِنَا عَلَى شمائِلِنا."],"takhrij":"صحيح: رواه الطبراني في الكبير (10851) عن العباس بن محمد المجاشعي الأصبهاني، ثنا محمد بن أبي يعقوب الكرماني، ثنا سفيان بن عيينة، عن عمرو بن دينار، عن طاوس، عن ابن عباس فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في وضع اليمين على الشمال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Tabarani in al-Kabir (10851)","chapter_en":"Reports about placing the right hand over the left","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Prophet ﷺ said: “We, the community of prophets, have been commanded to hasten breaking the fast, to delay the pre-dawn meal, and to place our right hands over our left hands.”"]},"buhuth":{"en":["It is not recommended to clasp the right hand over the left while standing after rising from bowing, because this is not established in the Sunnah, and because that standing is brief and is a time to prepare to go down into prostration."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في المعجم الكبير (10851)."},{"num":1959,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَبَا بَكْرٍ، وَعُمَرَ رَضِيَ اللَّهُ عَنْهُمَا كَانُوا يَفْتَتِحُونَ الصَّلَاةَ بِـــ ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ [ سورة الفاتحة: 2]."],"takhrij":"متفق عليه: رواه البخاري في الأذان (743)، ومسلم في الصلاة (399) كلاهما من حديث شعبة قال: سمعتُ قتادة، يحدث عن أنس واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب البداءة بفاتحة الكتاب قبل السورة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (743), Muslim (399) — wording per al-Bukhari","chapter_en":"Beginning with the Opening of the Book before the surah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Anas said: The Prophet ﷺ, and Abu Bakr and ‘Umar (may Allah be pleased with them), used to begin the prayer with “All praise is for Allah, Lord of all worlds.”"]},"intro":{"ar":["(الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ)"],"en":["“All praise is for Allah, Lord of all worlds.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (743)، مسلم (399)، واللفظ للبخاري."},{"num":1960,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا نَهَضَ مِنَ الرَّكْعَةِ الثَّانِيَةِ، اسْتَفْتَحَ الْقِرَاءَةَ بِـــ ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾، وَلَمْ يَسْكُتْ."],"takhrij":"صحيح: رواه مسلم في المساجد (599) انظر تفصيله: في باب ما يقول بعد التكبير.","grade":"صحيح","chapter_ar":"باب البداءة بفاتحة الكتاب قبل السورة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (599)","chapter_en":"Beginning with the Opening of the Book before the surah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah said: When the Messenger of Allah ﷺ rose for the second unit, he began the recitation with “All praise is for Allah, Lord of all worlds,” and he did not pause."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (599)."},{"num":1961,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَسْتَفْتِحُ الصَّلَاةَ بِالتَّكْبِيرِ، وَالْقِرَاءَةَ بِـــ ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾... الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (498) من حديث حسين المعلم، عن بديل بن ميسرة، عن أبي الجوزاء، عن عائشة فذكرته بطوله.","grade":"صحيح","chapter_ar":"باب البداءة بفاتحة الكتاب قبل السورة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (498)","chapter_en":"Beginning with the Opening of the Book before the surah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ used to begin the prayer with saying “Allāhu akbar”, and the recitation with “All praise is for Allah, Lord of all worlds” (and so on in the hadith)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (498)."},{"num":1962,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَطِّعُ قِرَاءَتَهُ يَقُولُ: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ ثُمَّ يَقِفُ: ﴿الرَّحْمَنِ الرَّحِيمِ﴾ ثُمَّ يَقِفُ، وَكَانَ يَقْرَؤُهَا: ﴿مَالِكِ يَوْمِ الدِّينِ﴾.","وَفِي رِوَايَةِ: قِرَاءَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ﴿بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، الرَّحْمَنِ الرَّحِيمِ، مَلِكِ يَوْمِ الدِّينِ ﴾ يُقَطِّعُ قِرَاءَتَهُ آيَةً آيَةً."],"takhrij":"صحيح: رواه أبو داود (4001)، والترمذي (2927) كلاهما من طريق يحيى ابن سعيد الأموي، ثنا ابن جريج، عن ابن أبي مليكة، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في القراءة آية آية","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (4001), al-Tirmidhi (2927)","chapter_en":"Reciting verse by verse","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["Umm Salamah said: The Messenger of Allah ﷺ used to separate his recitation. He would say, “In the name of Allah, the Most Merciful, the Especially Merciful,” then pause. Then he would say, “All praise is for Allah, Lord of all worlds,” then pause. Then he would say, “The Most Merciful, the Especially Merciful,” then pause. Then he would say, “Master of the Day of Judgment.” In this way, he would separate his recitation verse by verse."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4001)، الترمذي (2927)."},{"num":1963,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ بِفَاتِحَةِ الْكِتَابِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (756)، ومسلم في الصلاة (394) كلاهما من حديث سفيان بن عيينة، عن الزهري، عن محمود بن الربيع، عن عبادة بن الصامت فذكر الحديث. ولمسلم طرق أخرى واللفظ سواء، إلا ما رواه عبدالرزاق، عن معمر، عن الزهري بهذا الإسناد وزاد فيه: فصاعداً.","grade":"متفق عليه","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (756), Muslim (394)","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["‘Ubadah ibn al-Samit reported that the Messenger of Allah ﷺ said: “There is no prayer for the one who does not recite the Opening of the Book.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (756)، مسلم (394)."},{"num":1964,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ قَالَ: كُنَّا خَلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الْفَجْرِ، فَقَرَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَثَقُلَتْ عَلَيْهِ الْقِرَاءَةُ فَلَمَّا فَرَغَ قَالَ: لَعَلَّكُمْ تَقْرَءُونَ خَلْفَ إِمَامِكُمْ، قُلْنَا: نَعَمْ هَذًّا يَا رَسُولَ اللَّهِ، قَالَ: لَا تَفْعَلُوا إِلَّا بِفَاتِحَةِ الْكِتَابِ فَإِنَّهُ لَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ بِهَا."],"takhrij":"حسن: رواه أبو داود (823)، والترمذي (311) كلاهما من طريق محمد ابن إسحاق، عن مكحول، عن محمود بن الربيع، عن عبادة بن الصامت فذكره.","grade":"حسن","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (823), al-Tirmidhi (311) — he graded it good","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["‘Ubadah ibn al-Samit said: We were behind the Messenger of Allah ﷺ in the dawn prayer. The Messenger of Allah ﷺ recited and the recitation became difficult for him. When he finished, he said: “Perhaps you recite behind your imam?” We said: “Yes, rapidly, O Messenger of Allah.” He said: “Do not do so except with the Opening of the Book, for there is no prayer for the one who does not recite it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (823)، الترمذي (311)، وقال: حسن."},{"num":1965,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا بِأُمِّ الْقُرْآنِ فَهِيَ خِدَاجٌ هِيَ خِدَاجٌ، هِيَ خِدَاجٌ غَيْرُ تَامٍ، فَقُلْتُ: يَا أَبَا هُرَيْرَةَ: إِنِّي أَكُونُ أَحْيَانًا وَرَاءَ الْإِمَامِ فَغَمَزَ ذِرَاعِي، وقَالَ: اقْرَأْ بِهَا يَا فَارِسِيُّ في نَفْسِكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قَالَ اللَّهُ تَعَالَى قَسَمْتُ الصَّلَاةَ بَيْنِي وَبَيْنَ عَبْدِي نِصْفَيْنِ، فَنِصْفُهَا لِي وَنِصْفُهَا لِعَبْدِي، وَلِعَبْدِي مَا سَأَلَ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اقْرَءُوا، يَقُولُ الْعَبْدُ: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾، يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى: حَمِدَنِي عَبْدِي، وَيَقُولُ العبد: ﴿الرَّحْمَنِ الرَّحِيمِ﴾، يَقُولُ اللَّهُ: أَثْنَى عَلَيَّ عَبْدِي، وَيَقُولُ الْعَبْدُ: ﴿مَالِكِ يَوْمِ الدِّينِ﴾، يَقُولُ اللَّهُ: مَجَّدَنِي عَبْدِي، يَقُولُ الْعَبْدُ: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ (6) صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ (7).﴾ فَهَؤُلَاءِ لِعَبْدِي وَلِعَبْدِي مَا سَأَلَ."],"takhrij":"صحيح: رواه مالك في الصلاة (39) عن العلاء بن عبدالرحمن بن يعقوب، أنه سمع أبا السائب مولى هشام بن زهرة يقول: سمعت أبا هريرة يقول: فذكره.","grade":"صحيح","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (39), Muslim (395)","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Whoever prays a prayer in which he does not recite the Mother of the Qur’an, then it is deficient—deficient—deficient, incomplete.” He said: I said, “O Abu Hurayrah, sometimes I am behind the imam.” He pinched my forearm and said: “Recite it to yourself, O Persian.” For I heard the Messenger of Allah ﷺ say that Allah the Exalted said: “I have divided the prayer between Me and My servant into two halves: half is for Me and half is for My servant, and My servant will have what he asks.” The Messenger of Allah ﷺ said: “Recite.” When the servant says, “All praise is for Allah, Lord of all worlds,” Allah says: “My servant has praised Me.” When the servant says, “The Most Merciful, the Especially Merciful,” Allah says: “My servant has extolled Me.” When the servant says, “Master of the Day of Judgment,” Allah says: “My servant has glorified Me.” And when the servant says, “Guide us to the straight path—the path of those You have favored, not those who earned anger nor those who went astray,” Allah says: “These are for My servant, and My servant will have what he asked.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (39)، مسلم (395)."},{"num":1966,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ مرفوعاً لَا تُجْزِئُ صَلاةٌ لا يَقْرَأُ فِيهَا بِفَاتِحَةِ الْكِتَابِ."],"takhrij":"صحيح: رواه ابن خزيمة (490) وعنه ابن حبان (1789) عن محمد بن يحيى الذهلي قال: حدثنا وهب بن جرير، قال: حدثنا شعبةُ، عن العلاء بن عبدالرحمن، عن أبيه، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Khuzaymah (490), Ibn Hibban (1789)","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah narrated it as raised to the Prophet ﷺ: “A prayer is not sufficient if the Opening of the Book is not recited in it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (490)، ابن حبان (1789)."},{"num":1967,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ انْصَرَفَ مِنْ صَلَاةٍ جَهَرَ فِيهَا بِالْقِرَاءَةِ فَقَالَ: هَلْ قَرَأَ مَعِي مِنْكُمْ أَحَدٌ آنِفًا ؟ فَقَالَ رَجُلٌ: نَعَمْ، أَنَا يَا رَسُولَ اللَّهِ، قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي أَقُولُ: مَا لِي أُنَازَعُ الْقُرْآنَ.","فَانْتَهَى النَّاسُ عَنِ الْقِرَاءَةِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا جَهَرَ فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْقِرَاءَةِ، حِينَ سَمِعُوا ذَلِكَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: أخرجه مالك في الصلاة (44) عن ابن شهاب، عن ابن أكيمة الليثي، عن أبي هريرة فذكر الحديث، وعن مالك رواه أبو داود (826)، والترمذي (312)، والنسائي (919). قال الترمذي: حسن.","grade":"حسن","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nMalik (44), Abu Dawud (826), al-Tirmidhi (312), al-Nasa’i (919) — al-Tirmidhi said: “Hasan”","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ finished a prayer in which he recited aloud and said: “Did any of you recite along with me just now?” A man said: “Yes, I did, O Messenger of Allah.” The Messenger of Allah ﷺ said: “I am saying: Why am I being contested over the Qur’an?” After hearing that from the Messenger of Allah ﷺ, the people stopped reciting along with him in the prayers in which he recited aloud."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مالك (44)، أبو داود (826)، الترمذي (312)، النسائي (919)، وقال الترمذي: حسن."},{"num":1968,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ، فَإِذَا كَبَّرَ فَكَبِّرُوا، وَإِذَا قَرَأَ فَأَنْصِتُوا، وَإِذَا قَالَ: ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ﴾ فَقُولُوا: آمِينَ، وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ، وَإِذَا سَجَدَ فَاسْجُدُوا، وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعِينَ."],"takhrij":"حسن: رواه أبو داود (604) مختصراً، والنسائي (921)، وابن ماجه (846) واللفظ له، كلهم من طريق أبي خالد الأحمر، عن ابن عجلان، عن زيد بن أسلم، عن أبي صالح، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (604) in a shortened form; al-Nasa’i (921); Ibn Majah (846) — wording per Ibn Majah","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The imam has only been appointed to be followed. So when he says “Allāhu akbar,” then say “Allāhu akbar”. When he recites, listen attentively. When he says, ‘not those who earned anger nor those who went astray,’ then say: ‘Amen.’ When he bows, bow. When he says, ‘Allah hears the one who praises Him,’ then say: ‘O Allah, our Lord, to You belongs all praise.’ When he prostrates, prostrate. And if he prays seated, then pray seated.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (604) مختصرا، النسائي (921)، ابن ماجه (846)، واللفظ لابن ماجه."},{"num":1969,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَعَلَّكُمْ تَقْرَءُونَ وَالْإِمَامُ يَقْرَأُ مَرَّتَيْنِ أَوْ ثَلَاثًا . قَالُوا: يَا رَسُولَ اللَّهِ إِنَّا لَنَفْعَلُ . قَالَ: فَلَا تَفْعَلُوا إِلَّا أَنْ يَقْرَأَ أَحَدُكُمْ بِفَاتِحَةِ الْكِتَابِ."],"takhrij":"حسن: رواه عبد الرزاق (2766) وعنه الإمام أحمد (18070)، والبخاري في جزء القراءة (73)، والبيهقي (2922) كلهم من طريق خالد الحذاء، عن أبي قلابة، عن محمد بن أبي عائشة، عن رجل من أصحاب النبي صلى الله عليه وسلم.","grade":"حسن","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\n‘Abd al-Razzaq (2766); Ahmad (18070); al-Bukhari in Juz’ al-Qira’ah (73)","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ reported that the Prophet ﷺ said two or three times: “Perhaps you recite while the imam is reciting?” They said: “O Messenger of Allah, we do.” He said: “Do not do so, except that one of you recites the Opening of the Book.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد الرزاق (2766)، أحمد (18070)، البخاري في جزء القراءة (73)."},{"num":1970,"demo":false,"sanad":"","matn":["عَنْ رِفَاعَةَ بْنِ رَافِعٍ، أَنَّ رجلا دَخَلَ الْمَسْجِدَ فَذَكَرَ قِصَّتَهُ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا قُمْتَ فَتَوَجَّهْتَ إِلَى الْقِبْلَةِ فَكَبِّرْ، ثُمَّ اقْرَأْ بِأُمِّ الْقُرْآنِ وَبِمَا شَاءَ اللَّهُ أَنْ تَقْرَأَ... (فَذَكَرَ الْحَدِيثَ)."],"takhrij":"حسن: رواه أبو داود (859) عن وهب بن بقية، عن خالد، عن محمد ابن عمرو، عن علي بن يحيى بن خلاد، عن أبيه، عن رفاعة بن رافع، فذكره.","grade":"حسن","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (859)","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Rifa‘ah ibn Rafi‘ reported, about the story of a man who entered the mosque, that the Prophet ﷺ said to him: “When you stand and face the direction of prayer, then say “Allāhu akbar.” Then recite the Mother of the Qur’an, and whatever Allah wills for you to recite…”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (859)."},{"num":1971,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قال: صَلَّى رَجُلٌ والنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْظُرُ إِلَيْهِ، فَلَمَّا قَضَى صَلَاتَهُ قَالَ: ارْجِعْ فَصَلِّ، فَإِنَّكَ لَمْ تُصَلِّ ثَلَاثًا، فَقَامَ الرَّجُلُ فَلَمَّا قَضَى صَلَاتَهُ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ارْجِعْ فَصَلِّ ثَلَاثًا. فَقَالَ: فَحَلَفَ لَهُ كَيْفَ اجْتَهَدْتَ فَقَالَ لَهُ: ابْدَأْ فَكَبِّرْ وَتَحْمَدُ اللَّهَ وَتَقْرَأُ بِأُمِّ الْقُرْآنِ ثُمَّ تَرْكَعُ... فَذَكَرَ الْحَدِيثَ."],"takhrij":"صحيح: رواه البخاري في جزء القراءة (100) عن يحيى بن بكير، قال: ثنا عبدالله بن سويد، عن عياش بن بكير بن عبدالله، عن علي بن يحيى، عن أبي السائب، عن رجل من أصحاب النبيّ صلى الله عليه وسلم، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari in Juz’ al-Qira’ah (100)","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ said: A man prayed while the Prophet ﷺ was watching him. When he finished his prayer, he said: “Go back and pray, for you have not prayed,” three times. The man stood, and when he had finished his prayer, the Prophet ﷺ said: “Go back and pray,” three times. He said: Then he swore to him, saying, “How? I have exerted myself like this.” So he said to him: “Begin by saying ‘Allāhu akbar,’ praise Allah, and recite the Mother of the Qur’an, then bow…” and he mentioned the rest of the hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري في جزء القراءة (100)."},{"num":1972,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: خَطَبَنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَيَّنَ لَنَا سُنَّتَنَا، وَعَلَّمَنَا صَلَاتَنَا، فَقَالَ: إِذَا صَلَّيْتُمْ، فَأَقِيمُوا صُفُوفَكُمْ، ثُمَّ لَيَؤُمَّكُمْ أَحَدُكُمْ، فَإِذَا كَبَّرَ فَكَبِّرُوا، وَإِذْ قَالَ: غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ، فَقُولُوا: آمِينَ، يُجِبْكُمُ اللَّهُ... فَذَكَرَ الْحَدِيثَ بِطُولِهِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (404) من طرق عن أبي عوانة، عن قتادة، عن يونس بن جبير، عن حِطّان بن عبدالله الرقاشي، قال: صليتُ مع أبي موسى الأشعريّ صلاة... فذكر القصة والحديث بطوله.","grade":"صحيح","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (404)","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Abu Musa said: The Messenger of Allah ﷺ delivered a sermon to us, clarifying our Sunnah and teaching us our prayer. Among what he said was: “When you pray, straighten your rows, then let one of you lead you. When he says “Allāhu akbar,” then say “Allāhu akbar.” When he says: ‘not those who earned anger nor those who went astray,’ then say: ‘Amen,’ and Allah will respond to you…” and he mentioned the hadith in full."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (404)."},{"num":1973,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُلُّ صَلَاةٍ لَا يُقْرَأُ فِيهَا بِفَاتِحَةِ الْكِتَابِ فَهِيَ خِدَاجٌ، فَهِيَ خِدَاجٌ."],"takhrij":"حسن: رواه ابن ماجه (841) عن الوليد بن عمرو بن السُكين، حدثنا يوسف بن يعقوب السَلْعِيُّ، حدثنا حسين المعلِّمُ، عن عمرو بن شعيب فذكره.","grade":"حسن","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (841)","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb, from his father, from his grandfather, reported that the Messenger of Allah ﷺ said: “Every prayer in which the Opening of the Book is not recited is deficient—deficient.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (841)."},{"num":1974,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كُلُّ صَلَاةٍ لَا يُقْرَأُ فِيهَا بِأُمِّ الْكِتَابِ فَهِيَ خِدَاجٌ."],"takhrij":"حسن: رواه ابن ماجه (840) قال: حدثنا الفضل بن يعقوب الجزري، قال: حدثنا عبد الأعلى، عن محمد بن إسحاق، عن يحيى بن عبَّاد بن عبدالله ابن الزبير، عن أبيه، عن عائشة فذكر الحديث.","grade":"حسن","chapter_ar":"باب وجوب قراءة سورة الفاتحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Good\nReference(s): Ibn Majah (840), Ahmad (26356)","chapter_en":"Obligation of reciting the Opening Chapter","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["‘A’ishah said: I heard the Messenger of Allah ﷺ say: “Every prayer in which the Mother of the Book is not recited is deficient.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (840)."},{"num":1975,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: فِي كُلِّ صَلَاةٍ يُقْرَأُ فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَسْمَعْنَاكُمْ وَمَا أَخْفَى عَنَّا أَخْفَيْنَا عَنْكُمْ، وَإِنْ لَمْ تَزِدْ عَلَى أُمِّ الْقُرْآنِ أَجْزَأَتْ، وَإِنْ زِدْتَ فَهُوَ خَيْرٌ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (772)، ومسلم في الصلاة (396، 42) كلاهما من حديث إسماعيل بن إبراهيم قال: أخبرنا ابن جريج، قال: أخبرني عطاء، أنه سمع أبا هريرة يقول فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما زاد على سورة الفاتحة فهو حسن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (772), Muslim (396/42)","chapter_en":"What is added beyond the Opening Chapter is good","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abu Hurayrah said: “In every prayer there is recitation. Whatever the Messenger of Allah ﷺ recited aloud to us, we recite aloud to you; and whatever he kept quiet from us, we keep quiet from you. If you do not add anything beyond the Mother of the Qur’an, it is sufficient; and if you add more, then it is better.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (772)، مسلم (396/42)."},{"num":1976,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أُنَادِيَ أَنَّهُ لَا صَلَاةَ إِلَّا بِقِرَاءَةِ فَاتِحَةِ الْكِتَابِ فَمَا زَادَ.","وَفِيهِ لَفْظُ: لَا صَلَاةَ إِلَّا بِقُرْآنٍ وَلَوْ بِفَاتِحَةِ الْكِتَابِ فَمَا زَادَ.","وَالْبَعْضُ لَمْ يَذْكُرْ لَفْظَ: فَمَا زَادَ."],"takhrij":"حسن: رواه أبو داود (819، 820)، وأحمد (9529)، والدارقطني (1224)، وابن حبان (1791)، والحاكم (872)، والبيهقي (2456، 2361، 3953)، والبخاري في القراءة خلف الإمام (7) كلهم من طرق عن جعفر بن ميمون، قال: حدثنا أبو عثمان النهدي، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما زاد على سورة الفاتحة فهو حسن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (819, 820), Ahmad (9529), al-Daraqutni (1224), Ibn Hibban (1791)","chapter_en":"What is added beyond the Opening Chapter is good","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said to me: “Go out and announce: There is no prayer except with the recitation of the Opening of the Book, and whatever is added beyond it.” In another wording: “There is no prayer except with Qur’an recitation, even if it is the Opening of the Book, and whatever is added beyond it.” Some narrations do not include the phrase “and whatever is added beyond it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (819، 820)، أحمد (9529)، الدارقطني (1224)، ابن حبان (1791)."},{"num":1977,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: أُمِرْنَا أَنْ نَقْرَأَ بِفَاتِحَةِ الْكِتَابِ وَمَا تَيَسَّرَ."],"takhrij":"صحيح: رواه أبو داود (818)، قال: حدّثنا أبو الوليد الطّيالسيّ، حدّثنا همّام، عن قتادة، عن أبي نَضْرة، عن أبي سعيد، فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما زاد على سورة الفاتحة فهو حسن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (818)","chapter_en":"What is added beyond the Opening Chapter is good","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: “We were commanded to recite the Opening of the Book and whatever is easy (thereafter).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (818)."},{"num":1978,"demo":false,"sanad":"","matn":["عَنْ رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ، وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: جَاءَ رَجُلٌ وَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، فَذَكَرَ الْحَدِيثَ فِي إسَاءَتِهِ لِلصَّلَاةِ ثُمَّ ذَكَرَ تَوْجِيهَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَهُ وِجَاءٌ فِيه: ثُمَّ اقْرَأْ بِأُمِّ الْقُرْآنِ وَبِمَا شَاءَ اللَّهُ أَنْ تَقْرَأَ."],"takhrij":"حسن: رواه أبو داود (859) قال: حدثنا وهب بن بقية، عن خالد، عن محمد، يعني ابن عمرو، عن علي بن يحيى بن خلاد (عن أبيه) عن رفاعة بن رافع فذكره.","grade":"حسن","chapter_ar":"باب ما زاد على سورة الفاتحة فهو حسن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (859). Also narrated by Ahmad (18995) with a close wording.","chapter_en":"What is added beyond the Opening Chapter is good","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Rifa‘ah ibn Rafi‘ al-Zuraqi, a Companion of the Prophet ﷺ, said: A man came while the Messenger of Allah ﷺ was in the mosque. He then mentioned the hadith about the man’s deficient prayer and the Prophet’s instruction to him, including: “Then recite the Mother of the Qur’an, and whatever Allah wills for you to recite.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (859)، ورواه أيضا أحمد (18995) بلفظ قريب."},{"num":1979,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كَانَ مُعَاذٌ يُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ، ثُمَّ يَرْجِعُ فَيُصَلِّي بِأَصْحَابِهِ فَرَجَعَ ذَاتَ يَوْمٍ، فَصَلَّى بِهِمْ، وَصَلَّى خَلْفَهُ فَتًى مِنْ قَوْمِهِ..... (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ).","وَفِي رِوَايَةِ: ذَكَرَ قِصَّةَ مُعَاذٍ قَالَ: وَقَالَ يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْفَتَى: كَيْفَ تَصْنَعُ يَا ابْنَ أَخِي إِذَا صَلَّيْتَ ؟ قَالَ: أَقْرَأُ بِفَاتِحَةِ الْكِتَابِ، وَأَسْأَلُ اللَّهَ الْجَنَّةَ، وَأَعُوذُ بِهِ مِنَ النَّارِ، وَإِنِّي لَا أَدْرِي مَا دَنْدَنَتُكَ وَلَا دَنْدَنَةُ مُعَاذٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي وَمُعَاذٌ حَوْلَ هَاتَيْنِ، أَوْ نَحْوَ هَذَا."],"takhrij":"حسن: رواه أبو داود (793) عن يحيى بن حبيب، ثنا خالد بن الحارث، ثنا محمد بن عجلان، عن عبيدالله بن مقسم، عن جابر فذكر نحوه، وعن أبي داود رواه كل من البغوي في شرح السنة (601)، والبيهقي (5273).","grade":"حسن","chapter_ar":"باب ما زاد على سورة الفاتحة فهو حسن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (793); Ibn Khuzaymah authenticated it (1634); Ahmad (14241)","chapter_en":"What is added beyond the Opening Chapter is good","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: Mu‘adh used to pray the night prayer with the Messenger of Allah ﷺ, then return and lead his people. He then mentioned the story of Mu‘adh. He said: The Prophet ﷺ said to the young man: “What do you do, my nephew, when you pray?” He said: “I recite the Opening of the Book, ask Allah for Paradise, and seek refuge with Him from the Fire. I do not know your murmuring, nor Mu‘adh’s murmuring.” The Messenger of Allah ﷺ said: “Mu‘adh and I revolve around these two,” or words to that effect."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (793)، وصححه ابن خزيمة (1634)، أحمد (14241)."},{"num":1980,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الظُّهْرِ أَوِ الْعَصْرِ فَقَالَ: أَيُّكُمْ قَرَأَ خَلْفِي، بسَبِّحِ اسْمَ رَبِّكَ الأَعْلَى، قَالَ رَجُلٌ: أَنَا، وَلَمْ أُرِدْ بِهَا إِلَّا الْخَيْرَ، قَالَ: قَدْ عَلِمْتُ أَنَّ بَعْضَكُمْ خَالَجَنِيهَا."],"takhrij":"صحيح: رواه مسلم في الصلاة (389) عن سعيد بن منصور وقتيبة بن سعيد، كلاهما عن أبي عوانة، قال سعيد: حدثنا أبو عوانة، عن قتادة، عن زرارة بن أوفى، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب لا يجهر المأموم بالقراءة خلف الإمام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (398)","chapter_en":"The follower does not recite aloud behind the imam","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":15,"content":{"translation":{"en":["‘Imran ibn Husayn said: The Messenger of Allah ﷺ led us in the noon prayer—or the afternoon prayer—and said: “Which of you recited behind me: ‘Glorify the Name of your Lord, the Most High’?” A man said: “I did, and I only intended good by it.” He said: “I knew that one of you was contending with me in it.”"]},"buhuth":{"en":["“Contending with me” means: pulling against me, i.e., the two recitations overlapped. The objection was to raising his voice such that others could hear, not to the mere act of reciting itself."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (389)."},{"num":1981,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: كَانَ النَّاسُ يَجْهَرُونَ بِالْقِرَاءَةِ خَلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَلَطْتُمْ عَلَيَّ الْقُرْآنَ."],"takhrij":"حسن: رواه أحمد (4309) وأبو يعلى- المقصد العلي (269)، والبزار - كشف الأستار (488) والبخاري في جزء القراءة (ص 126) كلهم من طريق يونس بن أبي إسحاق، عن أبي إسحاق، عن أبي الأحوص، عن عبدالله، فذكره.","grade":"حسن","chapter_ar":"باب لا يجهر المأموم بالقراءة خلف الإمام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (4309), Abu Ya‘la (al-Maqsad al-‘Ali, 269), al-Bazzar (Kashf al-Astar, 488)","chapter_en":"The follower does not recite aloud behind the imam","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":15,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: People used to recite the Qur’an aloud behind the Messenger of Allah ﷺ, so the Messenger of Allah ﷺ said to them: “You have mixed up the Qur’an for me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (4309)، أبو يعلى في المقصد العلي (269)، البزار في كشف الأستار (488)."},{"num":1982,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا قَالَ الْإِمَامُ: ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ﴾ فَقُولُوا: آمِينَ، فَمَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (45) عن سُمَيّ مولى أبي بكر، عن أبي صالح السمان، عن أبي هريرة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الجهر بآمين للإمام والمأموم فيما يجهر فيه بالقراءة، وإخفاؤها فيما يخفى فيه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (45), al-Bukhari (4475, 782), Muslim (410)","chapter_en":"Saying “Amen” aloud in audible prayers, and quietly in quiet prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When the imam says: ‘not those who earned anger nor those who went astray,’ then say: ‘Amen.’ Whoever’s saying matches the saying of the angels will have his past sins forgiven.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11867],"tks":"متفق عليه: رواه مالك (45)، البخاري (4475، 782)، مسلم (410)."},{"num":1983,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا فَرَغَ مِنْ قِرَاءَةِ أُمِّ الْقُرْآنِ، رَفَعَ صَوْتَهُ، وَقَالَ: آمِينَ."],"takhrij":"حسن: رواه الدارقطني (1274)، وابن حبان (1806)، والحاكم (812)، والبيهقي (2452) كلهم من طريق إسحاق بن إبراهيم الزبيدي، حدّثني عمرو بن الحارث، حدثني عبدالله بن سالم، عن الزبيدي، أخبرني الزهري، عن أبي سلمة وسعيد بن المسيب، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الجهر بآمين للإمام والمأموم فيما يجهر فيه بالقراءة، وإخفاؤها فيما يخفى فيه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Daraqutni (1274), Ibn Hibban (1806), al-Hakim (812), al-Bayhaqi (2/58)","chapter_en":"Saying “Amen” aloud in audible prayers, and quietly in quiet prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah said: When the Prophet ﷺ finished reciting the Opening of the Book, he raised his voice and said: “Amen.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني (1274)، ابن حبان (1806)، الحاكم (812)، البيهقي (2452)."},{"num":1984,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: خَطَبَنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَيَّنَ لَنَا سُنَّتَنَا، وَعَلَّمَنَا صَلَاتَنَا، فَقَالَ: إِذَا صَلَّيْتُمْ، فَأَقِيمُوا صُفُوفَكُمْ، ثُمَّ لَيَؤُمَّكُمْ أَحَدُكُمْ، فَإِذَا كَبَّرَ فَكَبِّرُوا، وَإِذْ قَالَ: غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ، فَقُولُوا: آمِينَ، يُجِبْكُمُ اللَّهُ... (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"صحيح: رواه مسلم في الصلاة (404) من طرق عن أبي عوانة، عن قتادة، عن يونس بن جبير، عن حِطّان بن عبدالله الرقاشي، قال: صليتُ مع أبي موسى الأشعريّ صلاة... فذكر الحديث بطوله.","grade":"صحيح","chapter_ar":"باب ما جاء في الجهر بآمين للإمام والمأموم فيما يجهر فيه بالقراءة، وإخفاؤها فيما يخفى فيه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (404)","chapter_en":"Saying “Amen” aloud in audible prayers, and quietly in quiet prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":16,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ delivered a sermon to us, clarified our Sunnah, and taught us our prayer. He said: “When you pray, straighten your rows, then let one of you lead you. When he says “Allāhu akbar,” then say “Allāhu akbar.” When he says, ‘not those who earned anger nor those who went astray,’ then say: ‘Amin,’ and Allah will answer you…” (and so on in the hadith)."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (404)."},{"num":1985,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ: ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ﴾ فَقَالَ: آمِينَ وَمَدَّ بِهَا صَوْتَهُ."],"takhrij":"حسن: رواه أبو داود (932)، والترمذي (248) كلاهما من طريق سفيان، عن سلمة بن كُهيل، عن حُجْر بن عَنْبس، عن وائل بن حُجْر، واللفظ للترمذي، ولفظ أبي داود: ورفع بها صوته.","grade":"حسن","chapter_ar":"باب ما جاء في الجهر بآمين للإمام والمأموم فيما يجهر فيه بالقراءة، وإخفاؤها فيما يخفى فيه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (932), al-Tirmidhi (248) — wording per al-Tirmidhi; Abu Dawud’s wording: “and he raised his voice with it.”","chapter_en":"Saying “Amen” aloud in audible prayers, and quietly in quiet prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":16,"content":{"translation":{"en":["Wa’il ibn Hujr said: I heard the Prophet ﷺ recite: “not those who earned anger nor those who went astray,” then he said: “Amin,” extending his voice with it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (932)، الترمذي (248)، واللفظ للترمذي، ولفظ أبي داود: «ورفع بها صوته»."},{"num":1986,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا، يَقُولُ: لَا تُبَادِرُوا الإِمَامَ، إِذَا كَبَّرَ فَكَبِّرُوا، وَإِذَا قَالَ: ﴿وَلا الضَّالِّينَ﴾، فَقُولُوا: آمِينَ، وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (415) من طريق الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن مبادرة الإمام بالتأمين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (415)","chapter_en":"Prohibition of preceding the imam in saying “Amin”","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":17,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ used to teach us, saying: “Do not precede the imam. When he says “Allāhu akbar,” then say “Allāhu akbar.” When he says, ‘nor those who went astray,’ then say: ‘Amin.’ When he bows, bow. When he says, ‘Allah hears the one who praises Him,’ then say: ‘O Allah, our Lord, to You belongs all praise.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (415)."},{"num":1987,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا حَسَدَتْكُمْ الْيَهُودُ عَلَى شَيْءٍ مَا حَسَدَتْكُمْ عَلَى السَّلَامِ وَالتَّأْمِينِ."],"takhrij":"صحيح: رواه ابن ماجه (856) عن إسحاق بن منصور، أخبرنا عبدالصمد بن عبدالوارث، ثنا حماد بن سلمة، حدثنا سُهيل بن أبي صالح، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل التأمين وحسد اليهود عليه وعلى القبلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (856)","chapter_en":"The virtue of saying “Amin,” and the Jews’ envy over it and over the direction of prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ said: “The Jews have not envied you for anything as much as they have envied you for the greeting of peace and for saying ‘Amin.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (856)."},{"num":1988,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْيَهُودَ لَيَحْسُدُونَكُمْ عَلَى السَّلامِ وَالتَّأْمِينِ."],"takhrij":"حسن: رواه الخطيب في تاريخه (5733)، والضياء المقدسي في المختارة (1730) كلاهما من طريق إبراهيم بن إسحاق الحربي، نا أبو ظفر، نا سليمان بن المغيرة، عن ثابت، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل التأمين وحسد اليهود عليه وعلى القبلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Khatib in Tarikh Baghdad (11/43), al-Diya’ al-Maqdisi in al-Mukhtarah (5/107)","chapter_en":"The virtue of saying “Amin,” and the Jews’ envy over it and over the direction of prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Malik reported that the Messenger of Allah ﷺ said: “Indeed the Jews envy you for the greeting of peace and for saying ‘Amin.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الخطيب في تاريخ بغداد (5733)، الضياء المقدسي في المختارة (1730)."},{"num":1989,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ الأَسْلَمِيَّ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُؤَخِّرُ الْعِشَاءَ إِلَى ثُلُثِ اللَّيْلِ، وَيَكْرَهُ النَّوْمَ قَبْلَهَا، وَالْحَدِيثَ بَعْدَهَا، وَكَانَ يَقْرَأُ فِي صَلَاةِ الْفَجْرِ مِنَ الْمِائَةِ إِلَى السِّتِّينَ، وَكَانَ يَنْصَرِفُ حِينَ يَعْرِفُ بَعْضُنَا وَجْهَ بَعْضٍ."],"takhrij":"متفق عليه: رواه مسلم في المساجد (647) من طريق حماد بن سلمة، عن سيَّار بن سلامة أبي المنهال، قال سمعت أبا برزة الأسلمي فذكر الحديث. وهو جزء من الحديث الطويل في مواقيت الصلاة، اتفق الشيخان على تخريجه متفرقة، فأخرج البخاري في كتاب الأذان، باب القراءة في الفجر من طريق شعبة قال: حدثنا سيَّار بن سلامة قال: دخلت أنا وأبي على أبي بَرْزَة فسألناه عن وقت الصلاة فذكر الحديث وفيه: وكان يقرأ في الركعتين أو أحدهما ما بين الستين إلى المائة. ومسلم في الصلاة (461) من طريقين أُخرين عن أبي المنهال.","grade":"متفق عليه","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMuslim (647). Al-Bukhari also narrated with wording: “in the two units—or in one of them—between sixty and one hundred (verses).”","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["Abu Barzah al-Aslami said: The Messenger of Allah ﷺ used to delay the night prayer until one-third of the night, and he disliked sleeping before it and talking after it. He would recite in the dawn prayer between sixty and one hundred verses, and he would finish when we could recognize one another’s faces."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مسلم (647)، ورواه البخاري أيضا بلفظ: «في الركعتين — أو في إحداهما — ما بين الستين إلى المائة»."},{"num":1990,"demo":false,"sanad":"","matn":["عَنْ قُطْبَةَ بْنِ مَالِكٍ قَالَ: صَلَّيْتُ وَصَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَرَأ: ﴿ق وَالْقُرْآنِ الْمَجِيدِ﴾ حَتَّى قَرَأَ: ﴿وَالنَّخْلَ بَاسِقَاتٍ﴾ [ سورة ق: 1 - 10]."],"takhrij":"صحيح: رواه مسلم في الصلاة (457) من طريق أبي عوانة، عن زياد بن عِلاقة، عن قُطْبة بن مالك فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (457)","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["Qutbah ibn Malik said: I prayed, and the Messenger of Allah ﷺ led us in prayer and recited: “Qaf. By the Glorious Qur’an…” until he reached: “and tall palm trees…” (Qur’an 50:1–10)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (457)."},{"num":1991,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ حُرَيْثٍ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْفَجْرِ: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ﴾ [ سورة التكوير: 17]."],"takhrij":"صحيح: رواه مسلم في الصلاة (456) من طريق ابن بشر، عن مسعر، قال: حدثني الوليد بن سريع، عن عمرو بن حريث فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (456)","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["‘Amr ibn Hurayth said that he heard the Prophet ﷺ recite in the dawn prayer: “And by the night as it retreats…” (Qur’an 81:17)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (456)."},{"num":1992,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَانَ يَقْرَأُ فِي الْفَجْرِ بِـــ ﴿ق وَالْقُرْآنِ الْمَجِيدِ﴾، وَكَانَ صَلَاتُهُ بَعْدُ تَخْفِيفًا."],"takhrij":"صحيح: رواه مسلم في الصلاة (458) من طريق زائدة، ثنا سماك، عن جابر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (458)","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Samurah said: The Prophet ﷺ used to recite in the dawn prayer: “Qaf. By the Glorious Qur’an,” and his prayer after that (in general) was lightened."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13374],"tks":"صحيح: رواه مسلم (458)."},{"num":1993,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ يَقُولُ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الصَّلَوَاتِ كَنَحْوٍ مِنْ صَلَاتِكُمْ الَّتِي تُصَلُّونَ الْيَوْمَ، وَلَكِنَّهُ كَانَ يُخَفِّفُ، كَانَتْ صَلَاتُهُ أَخَفَّ مِنْ صَلَاتِكُمْ، وَكَانَ يَقْرَأُ فِي الْفَجْرِ الْوَاقِعَةَ وَنَحْوَهَا مِنَ السُّوَرِ."],"takhrij":"حسن: رواه أحمد (20995)، والطبراني في الكبير (1914) كلاهما من طريق عبدالرزاق، وهو في مصنفه (2720) قال: أخبرنا إسرائيل، عن سماك بن حرب، أنه سمع جابر بن سمرة فذكر الحديث. وصحَّحه ابن خزيمة (531)، والحاكم (875) من هذا الوجه.","grade":"حسن","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (20995), al-Tabarani (1914), ‘Abd al-Razzaq (2720), and Ibn Khuzaymah authenticated it (531)","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Samurah said: The Messenger of Allah ﷺ used to pray in a manner similar to the prayers you perform today, but he would make them lighter; his prayer was lighter than yours. He would recite in the dawn prayer “The Inevitable Event” and similar chapters."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20995)، الطبراني (1914)، عبد الرزاق (2720)، وصححه ابن خزيمة (531)."},{"num":1994,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَهْلِ الْمَدِينَةِ أَنَّهُ صَلَّى خَلْفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَمِعَهُ يَقْرَأُ فِي صَلَاةِ الْفَجْرِ: ﴿ق وَالْقُرْآنِ الْمَجِيدِ﴾ وَ ﴿يس (1) وَالْقُرْآنِ الْحَكِيمِ (2)﴾."],"takhrij":"حسن: رواه الإمام أحمد (16396) عن يونس، حدثنا أبو عوانة، عن سماك بن حرب، عن رجل من أهل المدينة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (16396)","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["A man from the people of Madinah said that he prayed behind the Prophet ﷺ and heard him recite in the dawn prayer: “Qaf. By the Glorious Qur’an,” and “Ya-Sin. By the Wise Qur’an.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (16396)."},{"num":1995,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ السَّائِبِ قَالَ: صَلَّى لَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصُّبْحَ بِمَكَّةَ، فَاسْتَفْتَحَ سُورَةَ الْمُؤْمِنِينَ، حَتَّى جَاءَ ذِكْرُ مُوسَى وَهَارُونَ، أَوْ ذِكْرُ عِيسَى، مُحَمَّدُ بْنُ عَبَّادٍ، يَشُكُّ أَوِ اخْتَلَفُوا عَلَيْهِ، أَخَذَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَعْلَةٌ، فَرَكَعَ وَعَبْدُ اللَّهِ بْنُ السَّائِبِ حَاضِرٌ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (455) من طريق عبد الرزاق، أخبرنا ابن جريج، قال: سمعت محمد بن عبَّاد بن جعفر، يقول: أخبرني أبو سلمة بن سفيان وعبدالله بن عمرو بن العاص وعبدالله بن المسيب، عن عبدالله بن السّائب فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (455)","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["‘Abdullah ibn al-Sa’ib said: The Prophet ﷺ led us in the dawn prayer in Makkah. He began reciting Surat al-Mu’minun until he reached the mention of Musa and Harun—or the mention of ‘Isa—then the Prophet ﷺ was seized by a cough, so he bowed. ‘Abdullah ibn al-Sa’ib witnessed that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (455)."},{"num":1996,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ عَبْدِ اللَّهِ الْجُهَنِيِّ، أَنَّ رَجُلًا مِنْ جُهَيْنَةَ، أَخْبَرَهُ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الصُّبْحِ: ﴿إِذَا زُلْزِلَتِ الأَرْضُ﴾ [سورة الزلزلة] فِي الرَّكْعَتَيْنِ كِلْتَيْهِمَا . فَلَا أَدْرِي أَنَسِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْ قَرَأَ ذَلِكَ عَمْدًا."],"takhrij":"حسن: رواه أبو داود (816) عن أحمد بن صالح، حدثنا ابن وهب، أخبرني عمرو، عن ابن أبي هلال، عن معاذ بن عبدالله الجهني فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (816)","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["Mu‘adh ibn ‘Abd Allah al-Juhani said that a man from Juhaynah told him that he heard the Prophet ﷺ recite in the dawn prayer “When the earth is shaken…” (Surat al-Zalzalah) in both units. I do not know whether the Messenger of Allah ﷺ forgot (and repeated it) or recited it intentionally."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (816)."},{"num":1997,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: إِنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيَؤُمُّنَا فِي الْفَجْرِ بِالصَّافَّاتِ."],"takhrij":"حسن: رواه أحمد (4989)، وأبو يعلى (5445)، وابن حبان (1817) كلّهم من حديث يزيد بن هارون، حدثنا ابن أبي ذئب، عن الحارث بن عبدالرحمن، عن سالم، عن أبيه عبدالله بن عمر، فذكر الحديث واللفظ له.","grade":"حسن","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (4989), Abu Ya‘la (5445), Ibn Hibban (1817) — wording per Ibn Hibban","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: The Messenger of Allah ﷺ would lead us in the dawn prayer reciting Surat al-Saffat."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (4989)، أبو يعلى (5445)، ابن حبان (1817)، واللفظ لابن حبان."},{"num":1998,"demo":false,"sanad":"","matn":["عَنْ أُمِّ هِشَامٍ بِنْتِ حَارِثَةَ بْنِ النُّعْمَانِ قالت: مَا أَخَذْتُ ﴿ق وَالْقُرْآنِ الْمَجِيدِ﴾ إِلَّا مِنْ وَرَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي بِهَا فِي الصُّبْحِ."],"takhrij":"حسن: رواه النسائي (949) عن عمران بن يزيد، قال: حدثنا ابن أبي الرِجال، عن يحيى بن سعيد، عن عمرة، عن أم هشام فذكرت الحديث مثله.","grade":"حسن","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (949)","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["Umm Hisham bint Harithah ibn al-Nu‘man said: I only learned “Qaf. By the Glorious Qur’an” from behind the Messenger of Allah ﷺ, because he used to pray with it in the dawn prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (949)."},{"num":1999,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: كُنْتُ أَقُودُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عُقْبَةُ، أَلَا أُعَلِّمُكَ خَيْرَ سُورَتَيْنِ قُرِئَتَا ؟ فَعَلَّمَنِي ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ وَ ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ﴾ فَلَمْ يَرَنِي سُرِرْتُ بِهِمَا جِدًّا، فَلَمَّا نَزَلَ لِصَلَاةِ الصُّبْحِ صَلَّى بِهِمَا صَلَاةَ الصُّبْحِ لِلنَّاسِ، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الصَّلَاةِ الْتَفَتَ إِلَيَّ فَقَالَ: يَا عُقْبَةُ كَيْفَ رَأَيْتَ ؟."],"takhrij":"صحيح: رواه أبو داود (1462)، والنسائي (5436) كلاهما عن أحمد ابن عمرو قال: أنبانا ابن وهب، قال: أخبرني معاوية بن صالح، عن العلاء بن الحارث، عن القاسم مولى معاوية، عن عقبة بن عامر فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (1462), al-Nasa’i (5436), Ibn Khuzaymah authenticated it (535), al-Hakim (877)","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["‘Uqbah ibn ‘Amir said: I used to lead the Messenger of Allah ﷺ by his mount while traveling. The Messenger of Allah ﷺ said: “O ‘Uqbah, shall I teach you the best two chapters that have been recited?” Then he taught me: “Say: I seek refuge in the Lord of daybreak” and “Say: I seek refuge in the Lord of mankind.” I did not find myself especially delighted by them. When he stopped for the dawn prayer, he led the people in prayer reciting them. When he finished, he turned to me and said: “O ‘Uqbah, what did you think?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1462)، النسائي (5436)، وصححه ابن خزيمة (535)، الحاكم (877)."}]);